import { SUPPORTED_POLICY_VERSION } from "../core/constants";
import { formatZodIssues } from "../core/config";
import { PolicyError } from "../core/errors";
import { validateGlob } from "../utils/glob";
import { policyFileSchema, type LoadedPolicy, type PolicyDefinition } from "./policy-schema";

export interface PolicyValidation {
  readonly policies: readonly LoadedPolicy[];
  readonly errors: readonly PolicyError[];
}

/**
 * Validates an already-parsed policy document (the result of YAML parsing).
 * Pure and synchronous so it can be unit-tested without the file system.
 */
export function validatePolicyDocument(
  document: unknown,
  file: string,
  knownRuleIds: ReadonlySet<string>,
): PolicyValidation {
  const errors: PolicyError[] = [];

  const version = readVersion(document);
  if (version !== undefined && version !== SUPPORTED_POLICY_VERSION) {
    return {
      policies: [],
      errors: [
        new PolicyError(
          "policy-invalid",
          `Unsupported policy version ${String(version)} (supported: ${SUPPORTED_POLICY_VERSION}).`,
          {
            file,
            suggestion: `Set "version: ${SUPPORTED_POLICY_VERSION}" at the top of the file.`,
          },
        ),
      ],
    };
  }

  const parsed = policyFileSchema.safeParse(document);
  if (!parsed.success) {
    return {
      policies: [],
      errors: [
        new PolicyError(
          "policy-invalid",
          `Invalid policy file:\n${formatZodIssues(parsed.error)}`,
          {
            file,
            suggestion: "See docs/policy-format.md for the policy schema.",
          },
        ),
      ],
    };
  }

  const policies: LoadedPolicy[] = [];
  for (const policy of parsed.data.policies) {
    const problems = checkPolicy(policy, knownRuleIds, file);
    if (problems.length > 0) errors.push(...problems);
    else policies.push({ ...policy, sourceFile: file });
  }
  return { policies, errors };
}

function readVersion(document: unknown): unknown {
  if (typeof document !== "object" || document === null) return undefined;
  return (document as Record<string, unknown>)["version"];
}

function checkPolicy(
  policy: PolicyDefinition,
  knownRuleIds: ReadonlySet<string>,
  file: string,
): PolicyError[] {
  const errors: PolicyError[] = [];

  if (!knownRuleIds.has(policy.rule)) {
    errors.push(
      new PolicyError(
        "policy-unknown-rule",
        `Policy "${policy.id}" references unknown rule "${policy.rule}".`,
        {
          file,
          suggestion: `Use one of: ${[...knownRuleIds].sort().join(", ")}.`,
        },
      ),
    );
  }

  const globFields: ReadonlyArray<[string, readonly string[]]> = [
    ["paths.include", policy.paths.include],
    ["paths.exclude", policy.paths.exclude],
    ...policy.suppressions.map((s, i): [string, readonly string[]] => [
      `suppressions[${i}].paths`,
      s.paths,
    ]),
  ];
  for (const [field, patterns] of globFields) {
    for (const pattern of patterns) {
      const problem = validateGlob(pattern);
      if (problem) {
        errors.push(
          new PolicyError(
            "policy-invalid",
            `Policy "${policy.id}" has an invalid glob in ${field}: "${pattern}" (${problem}).`,
            { file, suggestion: 'Use repository-relative POSIX globs such as "src/**/*.ts".' },
          ),
        );
      }
    }
  }
  return errors;
}

/** Reports policies whose ids collide across (or within) files. Later duplicates are dropped. */
export function rejectDuplicateIds(policies: readonly LoadedPolicy[]): PolicyValidation {
  const seen = new Map<string, LoadedPolicy>();
  const unique: LoadedPolicy[] = [];
  const errors: PolicyError[] = [];
  for (const policy of policies) {
    const first = seen.get(policy.id);
    if (first) {
      errors.push(
        new PolicyError(
          "policy-duplicate-id",
          `Duplicate policy id "${policy.id}" (first defined in ${first.sourceFile}).`,
          { file: policy.sourceFile, suggestion: "Policy ids must be unique across all files." },
        ),
      );
    } else {
      seen.set(policy.id, policy);
      unique.push(policy);
    }
  }
  return { policies: unique, errors };
}
