import type { PolicyGuardError } from "../core/errors";
import type { RepositoryReader } from "../git/repository-reader";
import { ImportGraph } from "./import-graph";
import { findMountedMiddleware, type MountedMiddleware } from "./route-indexer";
import { SymbolTable } from "./symbol-table";
import type {
  FileEntry,
  FileIndex,
  MigrationInfo,
  PackageManifest,
  RouteDefinition,
  TestCase,
} from "./types";

export interface IndexedRepositoryData {
  readonly reader: RepositoryReader;
  readonly files: ReadonlyMap<string, FileEntry>;
  readonly fileIndexes: ReadonlyMap<string, FileIndex>;
  readonly manifests: ReadonlyMap<string, PackageManifest>;
  readonly migrations: ReadonlyMap<string, MigrationInfo>;
  readonly errors: readonly PolicyGuardError[];
  /** Number of files whose index came from the cache. */
  readonly cacheHits: number;
}

/** Read-only semantic view of the repository at the head ref. */
export class IndexedRepository {
  readonly reader: RepositoryReader;
  readonly files: ReadonlyMap<string, FileEntry>;
  readonly fileIndexes: ReadonlyMap<string, FileIndex>;
  readonly manifests: ReadonlyMap<string, PackageManifest>;
  readonly migrations: ReadonlyMap<string, MigrationInfo>;
  readonly errors: readonly PolicyGuardError[];
  readonly cacheHits: number;
  readonly graph: ImportGraph;
  readonly symbols: SymbolTable;
  private readonly fileSet: ReadonlySet<string>;

  constructor(data: IndexedRepositoryData) {
    this.reader = data.reader;
    this.files = data.files;
    this.fileIndexes = data.fileIndexes;
    this.manifests = data.manifests;
    this.migrations = data.migrations;
    this.errors = data.errors;
    this.cacheHits = data.cacheHits;
    this.fileSet = new Set(data.files.keys());
    this.graph = new ImportGraph(data.fileIndexes, this.fileSet);
    this.symbols = new SymbolTable(data.fileIndexes);
  }

  hasFile(filePath: string): boolean {
    return this.fileSet.has(filePath);
  }

  getFileIndex(filePath: string): FileIndex | undefined {
    return this.fileIndexes.get(filePath);
  }

  /** File contents at the head ref. */
  readFile(filePath: string): Promise<string | undefined> {
    return this.reader.readFile(filePath);
  }

  /** Routes defined in `filePath`, or in the whole repository when omitted. */
  routes(filePath?: string): readonly RouteDefinition[] {
    if (filePath !== undefined) return this.fileIndexes.get(filePath)?.routes ?? [];
    return [...this.fileIndexes.values()].flatMap((index) => index.routes);
  }

  /** Test cases declared in `filePath`, or in all test files when omitted. */
  tests(filePath?: string): readonly (TestCase & { readonly file: string })[] {
    const entries =
      filePath === undefined ? [...this.fileIndexes.entries()] : this.entriesFor(filePath);
    return entries.flatMap(([file, index]) => index.tests.map((test) => ({ ...test, file })));
  }

  /** `app.use(auth, router)` style mounts of the router exported from `routeFile`. */
  mountedMiddleware(routeFile: string): readonly MountedMiddleware[] {
    return findMountedMiddleware(routeFile, this.fileIndexes, this.fileSet);
  }

  /** True when any indexed file carries the given marker (e.g. `APP_GUARD`). */
  hasMarker(marker: string): boolean {
    for (const index of this.fileIndexes.values()) if (index.markers.includes(marker)) return true;
    return false;
  }

  /** The manifest that governs `filePath` (nearest package.json up the tree). */
  manifestFor(filePath: string): PackageManifest | undefined {
    let dir = filePath.includes("/") ? filePath.slice(0, filePath.lastIndexOf("/")) : "";
    for (;;) {
      const candidate = dir === "" ? "package.json" : `${dir}/package.json`;
      const manifest = this.manifests.get(candidate);
      if (manifest) return manifest;
      if (dir === "") return undefined;
      dir = dir.includes("/") ? dir.slice(0, dir.lastIndexOf("/")) : "";
    }
  }

  private entriesFor(filePath: string): [string, FileIndex][] {
    const index = this.fileIndexes.get(filePath);
    return index ? [[filePath, index]] : [];
  }
}
