import { mkdir, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import path from "node:path";
import { CACHE_SUBDIR, POLICYGUARD_DIR } from "../core/constants";
import { loadConfig, type PolicyGuardConfig } from "../core/config";
import { toPolicyGuardError, type PolicyGuardError } from "../core/errors";
import { silentLogger, type Logger } from "../core/logger";
import { err, ok, type Result } from "../core/result";
import type { Finding, ReviewOptions, ReviewResult, ReviewSummary, Severity } from "../core/types";
import { resolveBaseRef, resolveHeadRef } from "../git/branch-utils";
import { GitClient } from "../git/git-client";
import { GitObjectReader } from "../git/repository-reader";
import { buildIndexedRepository } from "../indexing/file-indexer";
import { TypeScriptIndexer } from "../indexing/typescript-indexer";
import { loadPolicies } from "../policies/policy-loader";
import { applySuppressions, isSuppressed } from "../policies/suppression";
import {
  createDefaultRegistry,
  runRules,
  sortFindings,
  type RuleRegistry,
} from "../rules/rule-registry";
import type { RuleContext } from "../rules/rule-context";
import { headLines } from "../rules/rule-utils";
import { emptySeverityCounts, meetsThreshold } from "../utils/severity";

export interface ReviewInput {
  readonly cwd: string;
  readonly options: ReviewOptions;
  readonly logger?: Logger;
  readonly registry?: RuleRegistry;
  /** Disable the on-disk index cache (the repository is then not written to at all). */
  readonly useCache?: boolean;
  /** Hook for the optional LLM stage; receives deterministic findings and returns additional ones. */
  readonly extraFindings?: (
    context: RuleContext,
    deterministic: readonly Finding[],
  ) => Promise<{
    readonly findings: readonly Finding[];
    readonly errors: readonly PolicyGuardError[];
    readonly notes?: readonly string[];
  }>;
}

export interface ReviewOutcome {
  readonly result: ReviewResult;
  readonly config: PolicyGuardConfig;
  readonly policiesLoaded: number;
  readonly filesChanged: number;
  readonly failOn: Severity;
  readonly strict: boolean;
  /** Active findings at or above `failOn` (all warnings and above in strict mode). */
  readonly blocking: readonly Finding[];
  readonly warnings: readonly string[];
  /** Policy ids whose rule produced no result because it was skipped. */
  readonly skippedRules: readonly { readonly ruleId: string; readonly reason: string }[];
}

/** Builds the per-severity summary. `bySeverity` counts active (unsuppressed) findings only. */
export function summarize(findings: readonly Finding[]): ReviewSummary {
  const bySeverity = emptySeverityCounts();
  let suppressed = 0;
  for (const finding of findings) {
    if (isSuppressed(finding)) suppressed += 1;
    else bySeverity[finding.severity] += 1;
  }
  return {
    total: findings.length,
    bySeverity,
    deterministic: findings.filter((f) => f.source === "deterministic").length,
    llmAssisted: findings.filter((f) => f.source === "llm-assisted").length,
    suppressed,
  };
}

/** Findings that make the review fail. Suppressed findings never block. */
export function blockingFindings(
  findings: readonly Finding[],
  failOn: Severity,
  strict: boolean,
): Finding[] {
  const threshold: Severity = strict ? "warning" : failOn;
  return findings.filter((f) => !isSuppressed(f) && meetsThreshold(f.severity, threshold));
}

/**
 * Runs a full review: Git diff -> index -> policies -> deterministic rules -> suppressions.
 * Returns the collected errors when the review cannot run at all (bad repo, refs, config, policies).
 */
export async function runReview(
  input: ReviewInput,
): Promise<Result<ReviewOutcome, readonly PolicyGuardError[]>> {
  const cleanups: Array<() => Promise<void>> = [];
  try {
    return await executeReview(input, cleanups);
  } finally {
    for (const cleanup of cleanups) await cleanup();
  }
}

async function executeReview(
  input: ReviewInput,
  cleanups: Array<() => Promise<void>>,
): Promise<Result<ReviewOutcome, readonly PolicyGuardError[]>> {
  const logger = input.logger ?? silentLogger;
  const startedAt = new Date();
  const registry = input.registry ?? createDefaultRegistry();

  const opened = await GitClient.open(input.cwd);
  if (!opened.ok) return err([opened.error]);
  const client = opened.value;
  const repositoryPath = client.repositoryPath;

  const configResult = await loadConfig(repositoryPath, input.options.configPath);
  if (!configResult.ok) return err([configResult.error]);
  const config = configResult.value.config;

  const warnings: string[] = [];
  const baseResolution = await resolveBaseRef(client, {
    ...(input.options.base === undefined ? {} : { explicit: input.options.base }),
    ...(config.review.defaultBase === undefined ? {} : { configured: config.review.defaultBase }),
  });
  if (!baseResolution.ok) return err([baseResolution.error]);
  warnings.push(...baseResolution.value.warnings);
  const headResolution = await resolveHeadRef(client, input.options.head);
  if (!headResolution.ok) return err([headResolution.error]);
  const base = baseResolution.value.ref;
  const head = headResolution.value;

  const policyLoad = await loadPolicies(repositoryPath, registry.ids());
  if (policyLoad.errors.length > 0) return err(policyLoad.errors);
  const policies = policyLoad.policies;

  let diff;
  try {
    diff = await client.readDiff(base, head);
  } catch (cause) {
    return err([toPolicyGuardError(cause, "git-failure")]);
  }
  logger.debug(`Diff ${base.name}...${head.name}: ${diff.files.length} file(s)`);

  const headReader = new GitObjectReader(client, head.sha, head.name);
  const baseReader = new GitObjectReader(client, diff.mergeBase, base.name);
  cleanups.push(
    () => headReader.close(),
    () => baseReader.close(),
  );
  const cacheFile = await prepareCacheFile(repositoryPath, input.useCache ?? true);
  const indexedRepository = await buildIndexedRepository({
    reader: headReader,
    config,
    changedPaths: diff.files.map((f) => f.path),
    ...(cacheFile ? { cacheFile } : {}),
  });

  const context: RuleContext = {
    repositoryPath,
    baseRef: base.name,
    headRef: head.name,
    changedFiles: diff.files,
    indexedRepository,
    policies,
    config,
    options: input.options,
    headReader,
    baseReader,
    indexer: new TypeScriptIndexer(),
    commitMessages: await client.commitMessages(base.sha, head.sha),
  };

  const ruleRun = await runRules(registry, context);
  const errors: PolicyGuardError[] = [
    ...diff.errors,
    ...indexedRepository.errors,
    ...ruleRun.errors,
  ];
  let findings: Finding[] = [...ruleRun.findings];

  if (input.extraFindings) {
    const extra = await input.extraFindings(context, ruleRun.findings);
    // The LLM stage is additive only: it cannot replace or shadow deterministic findings.
    const deterministicIds = new Set(ruleRun.findings.map((f) => f.id));
    findings.push(
      ...extra.findings.filter((f) => f.source === "llm-assisted" && !deterministicIds.has(f.id)),
    );
    errors.push(...extra.errors);
    warnings.push(...(extra.notes ?? []));
  }

  findings = sortFindings(await suppress(context, findings));

  const completedAt = new Date();
  const failOn = input.options.failOn ?? config.reporting.failOn;
  const result: ReviewResult = {
    repositoryPath,
    baseRef: base.name,
    headRef: head.name,
    startedAt: startedAt.toISOString(),
    completedAt: completedAt.toISOString(),
    durationMs: completedAt.getTime() - startedAt.getTime(),
    findings,
    summary: summarize(findings),
    errors,
  };
  return ok({
    result,
    config,
    policiesLoaded: policies.length,
    filesChanged: diff.files.length,
    failOn,
    strict: input.options.strict,
    blocking: blockingFindings(findings, failOn, input.options.strict),
    warnings,
    skippedRules: ruleRun.skippedRules,
  });
}

async function suppress(context: RuleContext, findings: readonly Finding[]): Promise<Finding[]> {
  const files = new Set(findings.map((f) => f.file));
  const lines = new Map<string, readonly string[] | undefined>();
  for (const file of files) lines.set(file, await headLines(context, file).catch(() => undefined));
  return applySuppressions(findings, {
    config: context.config,
    policies: context.policies,
    readLines: (file) => lines.get(file),
  });
}

/** Creates the self-ignoring cache directory and returns its path, or undefined on failure. */
export async function ensureCacheDir(repositoryPath: string): Promise<string | undefined> {
  const dir = path.join(repositoryPath, POLICYGUARD_DIR, CACHE_SUBDIR);
  try {
    await mkdir(dir, { recursive: true });
    const ignore = path.join(dir, ".gitignore");
    if (!existsSync(ignore)) await writeFile(ignore, "*\n");
    return dir;
  } catch {
    return undefined;
  }
}

async function prepareCacheFile(
  repositoryPath: string,
  enabled: boolean,
): Promise<string | undefined> {
  if (!enabled) return undefined;
  const dir = await ensureCacheDir(repositoryPath);
  return dir ? path.join(dir, "index-cache.json") : undefined;
}
