import { z } from "zod";
import type { Evidence, Finding } from "../../core/types";
import type { FileIndex, RouteDefinition } from "../../indexing/types";
import { policiesForRule } from "../../policies/policy-context";
import type { LoadedPolicy } from "../../policies/policy-schema";
import type { RuleContext } from "../rule-context";
import type { PolicyRuleImplementation, RuleResult } from "../rule-result";
import {
  createFinding,
  filesInScope,
  findReasonAnnotations,
  headLines,
  parseOptions,
  snippet,
} from "../rule-utils";

const RULE_ID = "new-route-requires-authorization";

const optionsSchema = z
  .object({
    additionalAuthPatterns: z.array(z.string()).default([]),
    requireUnauthorizedTest: z.boolean().default(true),
  })
  .strict();

type Options = z.output<typeof optionsSchema>;

/** Identifier words that indicate authentication/authorization in middleware, guards, or decorators. */
const AUTH_WORDS = new Set([
  "auth",
  "authn",
  "authz",
  "authenticate",
  "authenticated",
  "authentication",
  "authorize",
  "authorized",
  "authorization",
  "jwt",
  "passport",
  "guard",
  "guards",
  "permission",
  "permissions",
  "role",
  "roles",
  "rbac",
  "acl",
  "bearer",
  "protect",
  "protected",
  "scopes",
]);

const NEST_NON_AUTH =
  /^(Controller|Get|Post|Put|Patch|Delete|All|Head|Options|Api\w*|HttpCode|Header|Redirect|Render|Version|Sse)\b/;
const NEST_PUBLIC = /^(Public|AllowAnonymous|SkipAuth|NoAuth)\b/;
const INLINE_AUTH_CHECK =
  /\b(req|request|ctx)\.(user|auth|principal)\b|\b(is|check|assert|ensure)(Authorized|Authenticated|Permission|Role)\w*\s*\(|\bhasRole\s*\(|\bhasPermission\s*\(|\bauthorize\s*\(|\bUnauthorized\w*\b|\bForbidden\w*\b|\.status\(\s*40[13]\s*\)|\.code\(\s*40[13]\s*\)|\bunauthorized\b/i;
const UNAUTHORIZED_TEST =
  /\b(401|403)\b|unauthori[sz]ed|forbidden|unauthenticated|not authenticated/i;

/** True when an expression/decorator text names an auth mechanism. */
export function isAuthLike(text: string, extraPatterns: readonly RegExp[] = []): boolean {
  const words = text
    .split(/(?=[A-Z][a-z])|[^A-Za-z0-9]+/)
    .map((word) => word.toLowerCase())
    .filter(Boolean);
  if (words.some((word) => AUTH_WORDS.has(word))) return true;
  if (/verify\w*(token|jwt|session)/i.test(text)) return true;
  return extraPatterns.some((pattern) => pattern.test(text));
}

interface AuthEvidence {
  readonly kind:
    | "annotation"
    | "middleware"
    | "router-middleware"
    | "mounted-middleware"
    | "decorator"
    | "global-guard"
    | "inline-check"
    | "public-decorator";
  readonly detail: string;
}

export const newRouteRequiresAuthorization: PolicyRuleImplementation = {
  id: RULE_ID,
  title: "New route requires authorization",
  description:
    "Newly added HTTP routes must apply authorization or be explicitly annotated as public with a reason.",
  category: "security",
  defaultSeverity: "error",
  supportedLanguages: ["typescript"],

  async run(context: RuleContext): Promise<RuleResult> {
    const findings: Finding[] = [];
    for (const policy of policiesForRule(context.policies, RULE_ID)) {
      const options = parseOptions(policy, optionsSchema);
      const extra = options.additionalAuthPatterns.map((source) => new RegExp(source, "i"));
      const files = filesInScope(context, policy, context.config.paths.api, {
        statuses: ["added", "modified", "renamed"],
      });
      for (const file of files) {
        const headIndex = context.indexedRepository.getFileIndex(file.path);
        if (!headIndex) continue;
        const newRoutes = await findNewRoutes(
          context,
          file.status,
          file.previousPath ?? file.path,
          headIndex,
        );
        const lines = await headLines(context, file.path);
        for (const route of newRoutes) {
          const result = await assessRoute(context, route, headIndex, lines, options, extra);
          if (result.finding) findings.push(buildFinding(policy, route, result.finding, lines));
        }
      }
    }
    return { findings, errors: [] };
  },
};

async function findNewRoutes(
  context: RuleContext,
  status: string,
  basePath: string,
  headIndex: FileIndex,
): Promise<readonly RouteDefinition[]> {
  if (status === "added") return headIndex.routes;
  const baseContent = await context.baseReader.readFile(basePath);
  if (baseContent === undefined) return headIndex.routes;
  const baseKeys = new Set(
    context.indexer.indexContent(basePath, baseContent).routes.map((r) => `${r.method} ${r.path}`),
  );
  return headIndex.routes.filter((route) => !baseKeys.has(`${route.method} ${route.path}`));
}

interface Assessment {
  /** Set when the route should produce a finding. */
  readonly finding?: {
    readonly reason: "no-auth" | "annotation-without-reason";
    readonly annotationLine?: number;
    readonly protection: readonly string[];
  };
}

async function assessRoute(
  context: RuleContext,
  route: RouteDefinition,
  index: FileIndex,
  lines: readonly string[] | undefined,
  options: Options,
  extra: readonly RegExp[],
): Promise<Assessment> {
  const annotation = findPublicAnnotation(lines, route);
  if (annotation?.reason) return {};
  if (annotation) {
    return {
      finding: {
        reason: "annotation-without-reason",
        annotationLine: annotation.line,
        protection: [],
      },
    };
  }

  const evidence = findAuthEvidence(context, route, index, extra);
  if (evidence) return {};

  if (options.requireUnauthorizedTest && hasUnauthorizedTest(context, route)) return {};
  return { finding: { reason: "no-auth", protection: route.middleware } };
}

function findPublicAnnotation(
  lines: readonly string[] | undefined,
  route: RouteDefinition,
): { line: number; reason?: string } | undefined {
  if (!lines) return undefined;
  const from = Math.max(1, route.line - 3);
  const window = lines.slice(from - 1, route.line);
  const [found] = findReasonAnnotations(window, "public-route");
  if (!found) return undefined;
  return { line: from + found.line - 1, ...(found.reason ? { reason: found.reason } : {}) };
}

function findAuthEvidence(
  context: RuleContext,
  route: RouteDefinition,
  index: FileIndex,
  extra: readonly RegExp[],
): AuthEvidence | undefined {
  const routeMiddleware = route.middleware.find((m) => isAuthLike(m, extra));
  if (routeMiddleware) return { kind: "middleware", detail: routeMiddleware };

  for (const usage of index.middlewareUsages) {
    if (usage.line >= route.line) continue;
    if (route.receiver !== undefined && usage.receiver !== route.receiver) continue;
    if (
      usage.kind === "use" &&
      usage.path !== undefined &&
      usage.path !== "/" &&
      !route.path.startsWith(usage.path)
    )
      continue;
    const hit =
      usage.args.find((arg) => isAuthLike(arg, extra)) ??
      (usage.kind === "hook" && isAuthLike(usage.path ?? "", extra) ? usage.path : undefined);
    if (hit) return { kind: "router-middleware", detail: hit };
  }

  for (const mount of context.indexedRepository.mountedMiddleware(route.file)) {
    const hit = mount.middleware.find((m) => isAuthLike(m, extra));
    if (hit) return { kind: "mounted-middleware", detail: `${hit} (${mount.file}:${mount.line})` };
  }

  if (route.framework === "nest") {
    for (const decorator of route.decorators) {
      if (NEST_PUBLIC.test(decorator)) return { kind: "public-decorator", detail: decorator };
      if (NEST_NON_AUTH.test(decorator)) continue;
      if (isAuthLike(decorator, extra)) return { kind: "decorator", detail: decorator };
    }
    if (
      context.indexedRepository.hasMarker("APP_GUARD") ||
      context.indexedRepository.hasMarker("useGlobalGuards")
    ) {
      return { kind: "global-guard", detail: "APP_GUARD / useGlobalGuards" };
    }
  }

  if (route.handlerSource && INLINE_AUTH_CHECK.test(route.handlerSource)) {
    return { kind: "inline-check", detail: "explicit authorization check in handler" };
  }
  return undefined;
}

function routePrefix(routePath: string): string {
  const cut = routePath.search(/[:*{]/);
  const prefix = cut === -1 ? routePath : routePath.slice(0, cut);
  return prefix.length > 1 ? prefix.replace(/\/$/, "") : prefix;
}

function hasUnauthorizedTest(context: RuleContext, route: RouteDefinition): boolean {
  const prefix = routePrefix(route.path);
  if (prefix === "/" || prefix === "<dynamic>" || prefix === "") return false;
  return context.indexedRepository
    .tests()
    .some(
      (test) =>
        test.kind === "test" &&
        `${test.fullName}\n${test.source ?? ""}`.includes(prefix) &&
        UNAUTHORIZED_TEST.test(`${test.fullName}\n${test.source ?? ""}`),
    );
}

function buildFinding(
  policy: LoadedPolicy,
  route: RouteDefinition,
  assessment: NonNullable<Assessment["finding"]>,
  lines: readonly string[] | undefined,
): Finding {
  const label = `${route.method} ${route.path}`;
  const evidence: Evidence[] = [
    {
      file: route.file,
      startLine: route.line,
      endLine: route.endLine,
      ...(snippet(lines, route.line, Math.min(route.endLine, route.line + 2))
        ? { snippet: snippet(lines, route.line, Math.min(route.endLine, route.line + 2)) as string }
        : {}),
      explanation: `Added ${label} route`,
      source: "diff",
    },
  ];

  if (assessment.reason === "annotation-without-reason") {
    evidence.push({
      file: route.file,
      startLine: assessment.annotationLine ?? route.line,
      explanation:
        'The "policyguard: public-route" annotation has no reason (expected reason="...")',
      source: "repository",
    });
  } else {
    evidence.push(
      {
        file: route.file,
        startLine: route.line,
        explanation:
          assessment.protection.length > 0
            ? `No authorization found in the route chain (middleware: ${assessment.protection.join(", ")})`
            : "No authorization middleware, guard, or explicit check found in the route chain",
        source: "repository",
      },
      {
        file: route.file,
        explanation: `No test found that asserts unauthorized (401/403) access to ${route.path}`,
        source: "test",
      },
    );
  }

  return createFinding({
    ruleId: RULE_ID,
    policy,
    title: "New route lacks authorization",
    message:
      assessment.reason === "annotation-without-reason"
        ? `${label} is marked public but gives no reason.`
        : `${label} was added without a recognizable authorization strategy.`,
    file: route.file,
    startLine: route.line,
    endLine: route.endLine,
    evidence,
    confidence: route.receiver === undefined && route.framework !== "nest" ? "medium" : "high",
    key: label,
    remediation:
      policy.remediation?.trim() ??
      'Add authorization middleware (e.g. requireRole("admin")) or mark the route public: // policyguard: public-route reason="..."',
  });
}
