import path from "node:path";
import type { FileIndex } from "./types";

const EXTENSIONS = [".ts", ".tsx", ".mts", ".cts", ".js", ".jsx", ".mjs", ".cjs"];

/**
 * Resolves a relative module specifier to a repository file path.
 * Handles extension-less imports, `index` files, and the TS ESM `.js` -> `.ts` convention.
 * Bare specifiers (packages) and path aliases return undefined.
 */
export function resolveModulePath(
  fromFile: string,
  specifier: string,
  files: ReadonlySet<string>,
): string | undefined {
  if (!specifier.startsWith("./") && !specifier.startsWith("../")) return undefined;
  const base = path.posix.normalize(path.posix.join(path.posix.dirname(fromFile), specifier));

  const candidates = [base];
  const jsSwap = /\.(m|c)?jsx?$/.exec(base);
  if (jsSwap) {
    const stem = base.slice(0, -jsSwap[0].length);
    candidates.push(...EXTENSIONS.map((ext) => `${stem}${ext}`));
  }
  candidates.push(...EXTENSIONS.map((ext) => `${base}${ext}`));
  candidates.push(...EXTENSIONS.map((ext) => `${base}/index${ext}`));
  return candidates.find((candidate) => files.has(candidate));
}

/** Directed file-level import graph built from {@link FileIndex} imports. */
export class ImportGraph {
  private readonly dependencies = new Map<string, readonly string[]>();
  private readonly importers = new Map<string, string[]>();

  constructor(indexes: ReadonlyMap<string, FileIndex>, files: ReadonlySet<string>) {
    for (const [file, index] of indexes) {
      const resolved = new Set<string>();
      for (const imported of index.imports) {
        const target = resolveModulePath(file, imported.moduleSpecifier, files);
        if (target) resolved.add(target);
      }
      this.dependencies.set(file, [...resolved]);
      for (const target of resolved) {
        const list = this.importers.get(target) ?? [];
        list.push(file);
        this.importers.set(target, list);
      }
    }
  }

  /** Files that `file` imports directly. */
  dependenciesOf(file: string): readonly string[] {
    return this.dependencies.get(file) ?? [];
  }

  /** Files that import `file` directly. */
  importersOf(file: string): readonly string[] {
    return this.importers.get(file) ?? [];
  }
}
