import type { PolicyGuardConfig } from "../core/config";
import { policyCoversLanguage } from "../policies/policy-context";
import type { LoadedPolicy } from "../policies/policy-schema";
import { matchesPathFilter } from "../utils/glob";

/** Configuration path group a built-in rule targets when its policy sets no `paths.include`. */
export function configPathsForRule(
  ruleId: string,
  config: PolicyGuardConfig,
): readonly string[] | undefined {
  switch (ruleId) {
    case "new-route-requires-authorization":
      return config.paths.api;
    case "migration-requires-rollback":
      return config.paths.migrations;
    case "no-direct-db-access-in-ui":
      return config.paths.ui;
    case "protected-path-requires-review-annotation":
      return config.paths.protected;
    case "deleted-test-requires-justification":
      return config.paths.tests;
    default:
      return undefined;
  }
}

/** True when the policy targets `filePath` (language, include with config fallback, exclude). */
export function policyScopeMatches(
  policy: LoadedPolicy,
  filePath: string,
  config: PolicyGuardConfig,
): boolean {
  if (!policyCoversLanguage(policy, filePath)) return false;
  const include =
    policy.paths.include.length > 0
      ? policy.paths.include
      : (configPathsForRule(policy.rule, config) ?? []);
  return matchesPathFilter(filePath, { include, exclude: policy.paths.exclude });
}
