import { z } from "zod";
import type { ChangedFile, Evidence, Finding } from "../../core/types";
import { policiesForRule } from "../../policies/policy-context";
import { matchesAny } from "../../utils/glob";
import type { RuleContext } from "../rule-context";
import type { PolicyRuleImplementation, RuleResult } from "../rule-result";
import {
  createFinding,
  effectiveFilter,
  filesInScope,
  headLines,
  parseOptions,
} from "../rule-utils";

const RULE_ID = "protected-path-requires-review-annotation";
const REVIEWED_BY = /policyguard:\s*reviewed-by\s+([^\s"'*]+)/i;
const CODEOWNERS_LOCATIONS = ["CODEOWNERS", ".github/CODEOWNERS", "docs/CODEOWNERS"] as const;

const optionsSchema = z.object({ acceptCodeowners: z.boolean().default(true) }).strict();

export interface CodeownersEntry {
  readonly pattern: string;
  readonly owners: readonly string[];
}

/** Parses CODEOWNERS text, ignoring comments and blank lines. */
export function parseCodeowners(text: string): CodeownersEntry[] {
  const entries: CodeownersEntry[] = [];
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.replace(/\s+#.*$/, "").trim();
    if (!line || line.startsWith("#")) continue;
    const [pattern, ...owners] = line.split(/\s+/);
    if (pattern) entries.push({ pattern, owners });
  }
  return entries;
}

function codeownersGlobs(pattern: string): string[] {
  const anchored = pattern.startsWith("/");
  const body = pattern.replace(/^\/+/, "").replace(/\/+$/, "");
  if (body === "*" || body === "**") return ["**"];
  const hasInnerSlash = body.includes("/");
  const base = anchored || hasInnerSlash ? body : `**/${body}`;
  return [base, `${base}/**`];
}

/** Owners from the last CODEOWNERS entry matching `filePath` (GitHub semantics: last match wins). */
export function codeownersOwnersFor(
  entries: readonly CodeownersEntry[],
  filePath: string,
): readonly string[] {
  let owners: readonly string[] = [];
  for (const entry of entries) {
    if (matchesAny(filePath, codeownersGlobs(entry.pattern))) owners = entry.owners;
  }
  return owners;
}

export const protectedPathRequiresReviewAnnotation: PolicyRuleImplementation = {
  id: RULE_ID,
  title: "Protected path requires review annotation",
  description:
    "Changes to protected paths need a reviewed-by annotation, a CODEOWNERS entry, or an explicit exception.",
  category: "security",
  defaultSeverity: "warning",
  supportedLanguages: ["any"],

  async run(context: RuleContext): Promise<RuleResult> {
    const findings: Finding[] = [];
    const policies = policiesForRule(context.policies, RULE_ID);
    if (policies.length === 0) return { findings, errors: [] };

    const codeowners = await loadCodeowners(context);
    const commitReviewer = commitReviewedBy(context.commitMessages);

    for (const policy of policies) {
      const options = parseOptions(policy, optionsSchema);
      const filter = effectiveFilter(policy, context.config.paths.protected);
      const files = filesInScope(context, policy, context.config.paths.protected, {
        includeBinary: true,
      });

      for (const file of files) {
        if (commitReviewer) continue;
        const owners = options.acceptCodeowners
          ? codeownersOwnersFor(codeowners.entries, file.path)
          : [];
        if (owners.length > 0) continue;
        if (await hasFileAnnotation(context, file)) continue;

        const firstAdded = file.hunks.flatMap((h) => h.lines).find((l) => l.type === "added");
        const startLine = file.hunks[0]?.newStart ?? 1;
        const matchedPattern =
          filter.include.find((p) => matchesAny(file.path, [p])) ?? "(configured)";
        const evidence: Evidence[] = [
          {
            file: file.path,
            startLine,
            ...(firstAdded ? { snippet: firstAdded.content.trim().slice(0, 200) } : {}),
            explanation: `Protected path changed (${file.status}), matching "${matchedPattern}"`,
            source: "diff",
          },
          {
            file: file.path,
            explanation:
              'No "policyguard: reviewed-by <name>" annotation in the file or commit messages',
            source: "policy",
          },
          {
            file: codeowners.file ?? "CODEOWNERS",
            explanation: options.acceptCodeowners
              ? codeowners.file
                ? `No CODEOWNERS entry in ${codeowners.file} covers ${file.path}`
                : "No CODEOWNERS file found (checked CODEOWNERS, .github/CODEOWNERS, docs/CODEOWNERS)"
              : "CODEOWNERS is not accepted by this policy",
            source: "repository",
          },
        ];
        findings.push(
          createFinding({
            ruleId: RULE_ID,
            policy,
            title: "Protected path changed without review annotation",
            message: `${file.path} is a protected path and has no reviewer annotation or CODEOWNERS entry.`,
            file: file.path,
            startLine,
            evidence,
            confidence: "high",
            key: file.status,
            remediation:
              policy.remediation?.trim() ??
              "Add a CODEOWNERS entry, or annotate the change: policyguard: reviewed-by <name>.",
          }),
        );
      }
    }
    return { findings, errors: [] };
  },
};

async function loadCodeowners(
  context: RuleContext,
): Promise<{ file?: string; entries: readonly CodeownersEntry[] }> {
  for (const location of CODEOWNERS_LOCATIONS) {
    const content = await context.headReader.readFile(location);
    if (content !== undefined) return { file: location, entries: parseCodeowners(content) };
  }
  return { entries: [] };
}

function commitReviewedBy(messages: readonly string[]): string | undefined {
  for (const message of messages) {
    const match = REVIEWED_BY.exec(message);
    if (match) return match[1];
  }
  return undefined;
}

async function hasFileAnnotation(context: RuleContext, file: ChangedFile): Promise<boolean> {
  if (file.status === "deleted" || file.isBinary) return false;
  const lines = await headLines(context, file.path);
  return lines?.some((line) => REVIEWED_BY.test(line)) ?? false;
}
