import type { Evidence, Finding } from "../../core/types";
import {
  analyzeMigration,
  isRollbackFile,
  siblingDownPath,
} from "../../indexing/migration-indexer";
import type { MigrationInfo } from "../../indexing/types";
import { isScriptFile } from "../../utils/path";
import { policiesForRule } from "../../policies/policy-context";
import { matchesAny } from "../../utils/glob";
import type { RuleContext } from "../rule-context";
import type { PolicyRuleImplementation, RuleResult } from "../rule-result";
import {
  commitMessageAnnotations,
  createFinding,
  filesInScope,
  findReasonAnnotations,
  headLines,
  snippet,
} from "../rule-utils";

const RULE_ID = "migration-requires-rollback";
const JUSTIFICATION = "migration-justified";

/** Analyzes a file the index did not classify as a migration (e.g. a policy path override). */
async function analyzeOnDemand(
  context: RuleContext,
  filePath: string,
): Promise<MigrationInfo | undefined> {
  if (!filePath.endsWith(".sql") && !isScriptFile(filePath)) return undefined;
  const content = await context.headReader.readFile(filePath);
  if (content === undefined) return undefined;
  return analyzeMigration(
    filePath,
    content,
    context.indexedRepository.getFileIndex(filePath)?.migrationFacts,
  );
}

export const migrationRequiresRollback: PolicyRuleImplementation = {
  id: RULE_ID,
  title: "Migration requires rollback or justification",
  description:
    "New migrations need a rollback step; destructive operations need a documented safety justification.",
  category: "migrations",
  defaultSeverity: "error",
  supportedLanguages: ["any"],

  async run(context: RuleContext): Promise<RuleResult> {
    const findings: Finding[] = [];
    const changedPaths = new Set(context.changedFiles.map((f) => f.path));
    const commitJustified =
      commitMessageAnnotations(context.commitMessages, JUSTIFICATION).length > 0;

    for (const policy of policiesForRule(context.policies, RULE_ID)) {
      const files = filesInScope(context, policy, context.config.paths.migrations, {
        statuses: ["added"],
      });
      for (const file of files) {
        const info =
          context.indexedRepository.migrations.get(file.path) ??
          (await analyzeOnDemand(context, file.path));
        if (!info) continue;
        if (isRollbackFile(file.path) || matchesAny(file.path, context.config.paths.tests))
          continue;

        const lines = await headLines(context, file.path);
        const sibling = siblingDownPath(file.path);
        const hasSiblingDown =
          sibling !== undefined &&
          (context.indexedRepository.hasFile(sibling) || changedPaths.has(sibling));
        const missingRollback =
          !info.hasRollback && !info.forwardOnlyByConvention && !hasSiblingDown;
        const destructive = info.destructive;
        if (!missingRollback && destructive.length === 0) continue;

        const annotation = lines ? findReasonAnnotations(lines, JUSTIFICATION)[0] : undefined;
        if (annotation?.reason || commitJustified) continue;

        const evidence: Evidence[] = [
          {
            file: file.path,
            startLine: 1,
            explanation: `Added ${info.kind} migration ${file.path}`,
            source: "diff",
          },
        ];
        for (const statement of destructive) {
          evidence.push({
            file: file.path,
            startLine: statement.line,
            endLine: statement.line,
            ...(snippet(lines, statement.line)
              ? { snippet: snippet(lines, statement.line) as string }
              : {}),
            explanation: `Destructive operation: ${statement.operation}`,
            source: "diff",
          });
        }
        if (missingRollback) {
          evidence.push({
            file: file.path,
            explanation: "No down/rollback step or reversible change() found",
            source: "repository",
          });
        }
        evidence.push({
          file: file.path,
          explanation: annotation
            ? `The "policyguard: ${JUSTIFICATION}" annotation has no reason`
            : `No "policyguard: ${JUSTIFICATION} reason=..." annotation or commit trailer found`,
          source: "policy",
        });

        const title =
          destructive.length > 0 && missingRollback
            ? "Destructive migration has no rollback"
            : destructive.length > 0
              ? "Destructive migration needs a safety justification"
              : "Migration has no rollback";
        const operations = [...new Set(destructive.map((d) => d.operation))];
        findings.push(
          createFinding({
            ruleId: RULE_ID,
            policy,
            title,
            message:
              destructive.length > 0
                ? `${file.path} performs ${operations.join(", ")}${missingRollback ? " and cannot be rolled back" : ""} without a documented justification.`
                : `${file.path} is a new migration without a rollback step or justification.`,
            file: file.path,
            startLine: destructive[0]?.line ?? 1,
            evidence,
            confidence: destructive.length > 0 ? "high" : "medium",
            key: title,
            remediation:
              policy.remediation?.trim() ??
              `Add a down/rollback step, or document why it is safe: policyguard: ${JUSTIFICATION} reason="..."`,
          }),
        );
      }
    }
    return { findings, errors: [] };
  },
};
