import { Command, Option } from "commander";
import { TOOL_NAME, TOOL_VERSION } from "../core/constants";
import type { OutputFormat, ReviewOptions, Severity } from "../core/types";
import { SEVERITIES } from "../utils/severity";
import { runExplain } from "./commands/explain";
import { runInit } from "./commands/init";
import { runPolicies } from "./commands/policies";
import { runReviewCommand } from "./commands/review";
import { runValidate } from "./commands/validate";
import { processIo, type CliIo } from "./io";

export interface ProgramEnvironment {
  readonly cwd: string;
  readonly io: CliIo;
  /** Receives the exit code of the executed command. */
  readonly setExitCode: (code: number) => void;
}

function defaultEnvironment(): ProgramEnvironment {
  return {
    cwd: process.cwd(),
    io: processIo,
    setExitCode: (code) => {
      process.exitCode = code;
    },
  };
}

/** Builds the CLI definition. Commands are registered here so tests can parse argv without side effects. */
export function buildProgram(env: ProgramEnvironment = defaultEnvironment()): Command {
  const program = new Command();
  program
    .name(TOOL_NAME)
    .description(
      "Evidence-linked, policy-as-code review engine for AI-assisted software development.",
    )
    .version(TOOL_VERSION, "-v, --version", "print the PolicyGuard version")
    .showHelpAfterError();

  program
    .command("init")
    .description("create .policyguard/ with starter policies and configuration")
    .option("--force", "overwrite existing files", false)
    .action(async (options: { force: boolean }) => {
      env.setExitCode(await runInit({ cwd: env.cwd, force: options.force, io: env.io }));
    });

  program
    .command("validate")
    .description("validate all policy files and the configuration")
    .option("--config <path>", "path to a configuration file")
    .action(async (options: { config?: string }) => {
      env.setExitCode(
        await runValidate({
          cwd: env.cwd,
          io: env.io,
          ...(options.config === undefined ? {} : { configPath: options.config }),
        }),
      );
    });

  program
    .command("policies")
    .description("list loaded policies")
    .option("--config <path>", "path to a configuration file")
    .action(async (options: { config?: string }) => {
      env.setExitCode(
        await runPolicies({
          cwd: env.cwd,
          io: env.io,
          ...(options.config === undefined ? {} : { configPath: options.config }),
        }),
      );
    });

  program
    .command("review")
    .description("review the diff between a base ref and HEAD against your policies")
    .option("--base <ref>", "base ref (default: review.defaultBase, origin/main, main, master)")
    .option("--head <ref>", "head ref", "HEAD")
    .addOption(
      new Option("--format <format>", "output format (default: terminal)").choices([
        "terminal",
        "json",
        "sarif",
      ]),
    )
    .option("--strict", "fail on warnings and on analysis errors", false)
    .option("--ai", "enable AI-assisted contextual analysis")
    .option("--no-ai", "disable AI-assisted analysis")
    .option("--config <path>", "path to a configuration file")
    .option("--output <path>", "write the report to a file instead of stdout")
    .addOption(
      new Option("--fail-on <severity>", "lowest blocking severity (default: error)").choices([
        ...SEVERITIES,
      ]),
    )
    .option("--github-annotations", "print GitHub Actions annotations (automatic in Actions)")
    .option("--no-color", "disable colored output")
    .option("--no-cache", "do not read or write the index cache")
    .option("-V, --verbose", "print debug information to stderr")
    .action(async (flags: ReviewFlags) => {
      const options: ReviewOptions = {
        head: flags.head,
        strict: flags.strict,
        ...(flags.base === undefined ? {} : { base: flags.base }),
        ...(flags.format === undefined ? {} : { format: flags.format }),
        ...(flags.ai === undefined ? {} : { ai: flags.ai }),
        ...(flags.config === undefined ? {} : { configPath: flags.config }),
        ...(flags.output === undefined ? {} : { outputPath: flags.output }),
        ...(flags.failOn === undefined ? {} : { failOn: flags.failOn }),
      };
      env.setExitCode(
        await runReviewCommand({
          cwd: env.cwd,
          io: env.io,
          options,
          color: flags.color,
          useCache: flags.cache,
          ...(flags.verbose === undefined ? {} : { verbose: flags.verbose }),
          ...(flags.githubAnnotations === undefined
            ? {}
            : { githubAnnotations: flags.githubAnnotations }),
        }),
      );
    });

  program
    .command("explain <finding-id>")
    .description("explain a finding from the last review")
    .option("--config <path>", "path to a configuration file")
    .action(async (findingId: string, flags: { config?: string }) => {
      env.setExitCode(
        await runExplain({
          cwd: env.cwd,
          io: env.io,
          findingId,
          ...(flags.config === undefined ? {} : { configPath: flags.config }),
        }),
      );
    });

  return program;
}

interface ReviewFlags {
  readonly base?: string;
  readonly head: string;
  readonly format?: OutputFormat;
  readonly strict: boolean;
  readonly ai?: boolean;
  readonly config?: string;
  readonly output?: string;
  readonly failOn?: Severity;
  readonly githubAnnotations?: boolean;
  readonly color: boolean;
  readonly cache: boolean;
  readonly verbose?: boolean;
}
