import { scanLine } from "../rules/built-in/secret-detected-in-source";

/** Paths whose contents are never sent to a model. */
const NEVER_SEND = [
  /(^|\/)\.env(\.|$)/,
  /(^|\/)\.(npmrc|netrc|pypirc)$/,
  /\.(pem|key|p12|pfx|jks|keystore)$/i,
  /(^|\/)id_(rsa|dsa|ecdsa|ed25519)(\.pub)?$/,
  /(^|\/)(credentials?|secrets?)(\.|\/|$)/i,
];

/** True when the file must never be included in a prompt. */
export function isNeverSendPath(filePath: string): boolean {
  return NEVER_SEND.some((pattern) => pattern.test(filePath));
}

const INSTRUCTION_PATTERNS: readonly RegExp[] = [
  /ignore\s+(?:all\s+|any\s+|the\s+)?(?:previous|prior|above|earlier)\s+(?:instructions?|rules?|prompts?|messages?)/i,
  /disregard\s+(?:all\s+|any\s+|the\s+)?(?:previous|prior|above|earlier|these|those)?\s*(?:instructions?|rules?|polic(?:y|ies))/i,
  /you\s+are\s+(?:now|no\s+longer)\b/i,
  /^\s*(?:\/\/|\/\*|#|\*|--)?\s*(?:system|assistant|developer)\s*:/i,
  /\bnew\s+instructions?\s*:/i,
  /\b(?:do\s+not|don'?t|never)\s+(?:report|flag|mention|raise)\b/i,
  /\b(?:disable|turn\s+off|skip|suppress|bypass)\s+(?:the\s+|this\s+|all\s+)?(?:rules?|polic(?:y|ies)|checks?|findings?)\b/i,
  /<\/?(?:system|instructions?|assistant|prompt)>/i,
  /\boverride\b.*\b(?:rules?|polic(?:y|ies)|instructions?)\b/i,
  /\brespond\s+with\b.*\{\s*"findings"\s*:\s*\[\s*\]/i,
];

const MAX_LINE_LENGTH = 400;

export interface SanitizedText {
  readonly text: string;
  /** Lines that looked like instructions and were defanged. */
  readonly neutralizedLines: number;
  /** Lines dropped because they looked like secrets. */
  readonly redactedLines: number;
}

/** Control characters and invisible/bidi overrides that can hide or reorder text. */
function isStrippedCodePoint(code: number): boolean {
  return (
    code <= 0x08 ||
    code === 0x0b ||
    code === 0x0c ||
    (code >= 0x0e && code <= 0x1f) ||
    code === 0x7f ||
    (code >= 0x200b && code <= 0x200f) ||
    (code >= 0x202a && code <= 0x202e) ||
    (code >= 0x2066 && code <= 0x2069)
  );
}

/**
 * Prepares untrusted repository text for inclusion in a prompt: strips control characters,
 * truncates long lines, defangs instruction-like lines, and removes likely secrets and
 * private-key blocks. The text is still data, never instructions; callers must fence it.
 */
export function sanitizeUntrusted(
  input: string,
  options: { redactSecrets: boolean } = { redactSecrets: true },
): SanitizedText {
  let neutralized = 0;
  let redacted = 0;
  let inPrivateKey = false;
  const output: string[] = [];

  for (const raw of input.split(/\r?\n/)) {
    let line = [...raw].filter((ch) => !isStrippedCodePoint(ch.codePointAt(0) ?? 0)).join("");
    if (line.length > MAX_LINE_LENGTH) line = `${line.slice(0, MAX_LINE_LENGTH)} [truncated]`;

    if (options.redactSecrets) {
      if (/-----BEGIN [A-Z ]*PRIVATE KEY(?: BLOCK)?-----/.test(line)) inPrivateKey = true;
      if (inPrivateKey) {
        redacted += 1;
        output.push("[line removed: possible private key]");
        if (/-----END [A-Z ]*PRIVATE KEY(?: BLOCK)?-----/.test(line)) inPrivateKey = false;
        continue;
      }
      if (scanLine(line)) {
        redacted += 1;
        output.push("[line removed: possible secret]");
        continue;
      }
    }

    if (INSTRUCTION_PATTERNS.some((pattern) => pattern.test(line))) {
      neutralized += 1;
      line = `[instruction-like text, treated as data] ${line}`;
    }
    // Break up fence-like markers so content cannot imitate the prompt structure.
    output.push(line.replace(/={5,}/g, "====").replace(/`{3,}/g, "``"));
  }
  return { text: output.join("\n"), neutralizedLines: neutralized, redactedLines: redacted };
}

/** Wraps untrusted text in unforgeable delimiters; `nonce` is random per request. */
export function fenceUntrusted(label: string, text: string, nonce: string): string {
  const safe = text.split(nonce).join("");
  return `=====BEGIN UNTRUSTED ${label} [${nonce}]=====\n${safe}\n=====END UNTRUSTED ${label} [${nonce}]=====`;
}
