import type { ChangedFile, Confidence, Evidence } from "../core/types";
import type { LoadedPolicy } from "../policies/policy-schema";
import { addedLines } from "../rules/rule-utils";
import { normalizeRepoPath } from "../utils/path";
import type { LlmCandidateFinding } from "./response-schema";

export interface ValidationContext {
  /** File contents at the head commit; undefined when the file does not exist. */
  readonly readFile: (filePath: string) => Promise<string | undefined>;
  readonly changedFiles: readonly ChangedFile[];
  /** Policies that allow AI analysis, keyed by rule id. */
  readonly policiesByRule: ReadonlyMap<string, LoadedPolicy>;
  /** True when the policy targets the file (path/language scope). */
  readonly inPolicyScope: (policy: LoadedPolicy, filePath: string) => boolean;
}

export type ValidationResult =
  | {
      readonly ok: true;
      readonly policy: LoadedPolicy;
      /** Evidence rebuilt from real file content; model-provided snippets are never trusted. */
      readonly evidence: readonly Evidence[];
      readonly confidence: Confidence;
    }
  | { readonly ok: false; readonly reasons: readonly string[] };

const MAX_SNIPPET_LINES = 5;
const RANK: Record<Confidence, number> = { low: 1, medium: 2, high: 3 };
const BY_RANK: Record<number, Confidence> = { 1: "low", 2: "medium", 3: "high" };

function isSafePath(filePath: string): boolean {
  const normalized = normalizeRepoPath(filePath);
  return (
    normalized.length > 0 &&
    !normalized.startsWith("/") &&
    !/^[A-Za-z]:/.test(normalized) &&
    !normalized.split("/").includes("..") &&
    !normalized.includes("\0")
  );
}

/**
 * Confidence scoring: starts from the model's claim and is reduced when the cited code
 * does not touch the diff or when only one piece of evidence supports the finding.
 */
export function scoreConfidence(
  claimed: Confidence,
  signals: { touchesDiff: boolean; evidenceCount: number },
): Confidence {
  let score = RANK[claimed];
  if (!signals.touchesDiff) score -= 1;
  if (signals.evidenceCount < 2) score -= 1;
  // Model-only judgment is never "high": a deterministic rule would have said so.
  score = Math.min(score, 2);
  return BY_RANK[Math.max(1, score)] as Confidence;
}

/**
 * Validates an LLM candidate against the real repository. Rejects fabricated files,
 * out-of-range lines, unknown rules, and evidence unrelated to the diff or the policy.
 */
export async function validateCandidate(
  candidate: LlmCandidateFinding,
  context: ValidationContext,
): Promise<ValidationResult> {
  const reasons: string[] = [];

  const policy = context.policiesByRule.get(candidate.ruleId);
  if (!policy) reasons.push(`rule "${candidate.ruleId}" is not enabled for AI-assisted analysis`);

  const changed = new Map(context.changedFiles.map((f) => [f.path, f]));
  const primaryPath = normalizeRepoPath(candidate.file);
  if (!isSafePath(candidate.file))
    reasons.push(`primary file "${candidate.file}" is not a valid repository path`);
  else if (!changed.has(primaryPath) || changed.get(primaryPath)?.status === "deleted") {
    reasons.push(`primary file "${candidate.file}" is not a changed file in this diff`);
  }
  if (candidate.endLine < candidate.startLine)
    reasons.push("primary location has endLine before startLine");

  const items = [
    {
      file: candidate.file,
      startLine: candidate.startLine,
      endLine: candidate.endLine,
      explanation: candidate.message,
      primary: true,
    },
    ...candidate.evidence.map((e) => ({ ...e, primary: false })),
  ];

  const evidence: Evidence[] = [];
  let touchesDiff = false;
  for (const item of items) {
    const label = item.primary ? "primary location" : `evidence for "${item.file}"`;
    if (!isSafePath(item.file)) {
      reasons.push(`${label}: invalid path`);
      continue;
    }
    const filePath = normalizeRepoPath(item.file);
    const content = await context.readFile(filePath);
    if (content === undefined) {
      reasons.push(`${label}: file "${filePath}" does not exist`);
      continue;
    }
    const lines = content.split(/\r?\n/);
    const total = lines.at(-1) === "" ? lines.length - 1 : lines.length;
    const start = item.startLine;
    const end = item.endLine ?? item.startLine;
    if (start !== undefined) {
      if (start > total || (end !== undefined && end > total)) {
        reasons.push(`${label}: lines ${start}-${end} are outside ${filePath} (${total} lines)`);
        continue;
      }
      if (end !== undefined && end < start) {
        reasons.push(`${label}: endLine is before startLine`);
        continue;
      }
    }

    const changedFile = changed.get(filePath);
    const relevant =
      changedFile !== undefined ||
      (policy !== undefined && context.inPolicyScope(policy, filePath));
    if (!relevant) {
      reasons.push(`${label}: "${filePath}" is neither part of the diff nor in the policy's scope`);
      continue;
    }
    if (changedFile && start !== undefined) {
      const rangeEnd = end ?? start;
      if (
        changedFile.status === "added" ||
        addedLines(changedFile).some((l) => l.line >= start && l.line <= rangeEnd)
      ) {
        touchesDiff = true;
      }
    }

    const snippetLines =
      start === undefined
        ? []
        : lines.slice(start - 1, Math.min(end ?? start, start - 1 + MAX_SNIPPET_LINES));
    const snippet = snippetLines.join("\n").trim();
    evidence.push({
      file: filePath,
      ...(start === undefined ? {} : { startLine: start }),
      ...(end === undefined || start === undefined ? {} : { endLine: end }),
      ...(snippet ? { snippet } : {}),
      explanation: item.explanation,
      source: changedFile ? "diff" : "repository",
    });
  }

  if (reasons.length > 0 || !policy) return { ok: false, reasons };
  if (evidence.length === 0) return { ok: false, reasons: ["no usable evidence"] };
  return {
    ok: true,
    policy,
    evidence,
    confidence: scoreConfidence(candidate.confidence, {
      touchesDiff,
      evidenceCount: evidence.length,
    }),
  };
}
