import type { Finding, Severity } from "../core/types";
import { isSuppressed } from "../policies/suppression";
import type { ReviewOutcome } from "../review/review-engine";
import { compareSeverityDesc } from "../utils/severity";

/** GitHub caps displayed annotations per step; stay below the cap and summarize the rest. */
export const DEFAULT_MAX_ANNOTATIONS = 45;

type AnnotationLevel = "error" | "warning" | "notice";

function level(severity: Severity): AnnotationLevel {
  switch (severity) {
    case "critical":
    case "error":
      return "error";
    case "warning":
      return "warning";
    default:
      return "notice";
  }
}

/** Escapes message data for a workflow command (`::level::data`). */
export function escapeData(value: string): string {
  return value.replace(/%/g, "%25").replace(/\r/g, "%0D").replace(/\n/g, "%0A");
}

/** Escapes a command property value (`file=`, `title=`). */
export function escapeProperty(value: string): string {
  return escapeData(value).replace(/:/g, "%3A").replace(/,/g, "%2C");
}

/** Converts one finding into a GitHub Actions workflow command. */
export function toAnnotation(finding: Finding): string {
  const properties = [
    `file=${escapeProperty(finding.file)}`,
    ...(finding.startLine === undefined ? [] : [`line=${finding.startLine}`]),
    ...(finding.endLine === undefined ? [] : [`endLine=${finding.endLine}`]),
    `title=${escapeProperty(`${finding.title} [${finding.ruleId}]`)}`,
  ];
  const body = [
    finding.message,
    ...(finding.remediation ? [`Remediation: ${finding.remediation.trim()}`] : []),
  ].join("\n");
  return `::${level(finding.severity)} ${properties.join(",")}::${escapeData(body)}`;
}

/** Workflow commands for all active findings, worst first, capped at `max`. */
export function toAnnotations(
  outcome: ReviewOutcome,
  max: number = DEFAULT_MAX_ANNOTATIONS,
): string[] {
  const active = outcome.result.findings
    .filter((f) => !isSuppressed(f))
    .sort((a, b) => compareSeverityDesc(a.severity, b.severity));
  const lines = active.slice(0, max).map(toAnnotation);
  if (active.length > max) {
    lines.push(
      `::notice title=PolicyGuard::${escapeData(`${active.length - max} more finding(s) not annotated; see the full report.`)}`,
    );
  }
  return lines;
}

/** Markdown for `$GITHUB_STEP_SUMMARY`. */
export function renderStepSummary(outcome: ReviewOutcome): string {
  const { summary } = outcome.result;
  const lines = [
    "## PolicyGuard review",
    "",
    `Base \`${outcome.result.baseRef}\` ... head \`${outcome.result.headRef}\`, ${outcome.filesChanged} file(s) changed.`,
    "",
    "| Critical | Error | Warning | Info | Suppressed |",
    "| --- | --- | --- | --- | --- |",
    `| ${summary.bySeverity.critical} | ${summary.bySeverity.error} | ${summary.bySeverity.warning} | ${summary.bySeverity.info} | ${summary.suppressed} |`,
    "",
  ];
  const active = outcome.result.findings.filter((f) => !isSuppressed(f));
  if (active.length > 0) {
    lines.push("| Severity | Finding | Location | Rule |", "| --- | --- | --- | --- |");
    for (const finding of active) {
      const where =
        finding.startLine === undefined ? finding.file : `${finding.file}:${finding.startLine}`;
      lines.push(
        `| ${finding.severity} | ${escapeCell(finding.title)} | \`${where}\` | \`${finding.ruleId}\` |`,
      );
    }
    lines.push("");
  }
  lines.push(
    outcome.blocking.length > 0
      ? `**Failed:** ${outcome.blocking.length} blocking finding(s).`
      : "**Passed:** no blocking findings.",
  );
  return `${lines.join("\n")}\n`;
}

function escapeCell(value: string): string {
  return value.replace(/\|/g, "\\|").replace(/\n/g, " ");
}
