import { readdir, readFile } from "node:fs/promises";
import path from "node:path";
import { parseDocument } from "yaml";
import { POLICIES_SUBDIR, POLICYGUARD_DIR } from "../core/constants";
import { PolicyError } from "../core/errors";
import { toPosix } from "../utils/path";
import { rejectDuplicateIds, validatePolicyDocument } from "./policy-validator";
import type { LoadedPolicy } from "./policy-schema";

export interface PolicyLoadResult {
  readonly policies: readonly LoadedPolicy[];
  readonly errors: readonly PolicyError[];
  /** Repository-relative POSIX paths of every policy file that was read. */
  readonly files: readonly string[];
  readonly policiesDir: string;
}

/**
 * Loads every `*.yaml` / `*.yml` file under `.policyguard/policies/` (or `policiesDir`),
 * validating each. Invalid files produce errors; valid policies are still returned.
 */
export async function loadPolicies(
  repositoryPath: string,
  knownRuleIds: ReadonlySet<string>,
  policiesDir: string = path.join(repositoryPath, POLICYGUARD_DIR, POLICIES_SUBDIR),
): Promise<PolicyLoadResult> {
  let fileNames: string[];
  try {
    fileNames = await listPolicyFiles(policiesDir);
  } catch (cause) {
    const missing = (cause as NodeJS.ErrnoException).code === "ENOENT";
    return {
      policies: [],
      files: [],
      policiesDir,
      errors: [
        new PolicyError(
          "policy-invalid",
          missing
            ? `Policy directory not found: ${policiesDir}`
            : `Cannot read policy directory: ${policiesDir}`,
          { cause, suggestion: "Run `policyguard init` to create starter policies." },
        ),
      ],
    };
  }

  if (fileNames.length === 0) {
    return {
      policies: [],
      files: [],
      policiesDir,
      errors: [
        new PolicyError(
          "policy-invalid",
          `No policy files (*.yaml, *.yml) found in ${policiesDir}`,
          {
            suggestion: "Run `policyguard init` to create starter policies.",
          },
        ),
      ],
    };
  }

  const collected: LoadedPolicy[] = [];
  const errors: PolicyError[] = [];
  const files: string[] = [];

  for (const absolute of fileNames) {
    const relative = toPosix(path.relative(repositoryPath, absolute));
    files.push(relative);
    const result = await loadPolicyFile(absolute, relative, knownRuleIds);
    collected.push(...result.policies);
    errors.push(...result.errors);
  }

  const deduped = rejectDuplicateIds(collected);
  return {
    policies: deduped.policies,
    errors: [...errors, ...deduped.errors],
    files,
    policiesDir,
  };
}

async function listPolicyFiles(dir: string): Promise<string[]> {
  const entries = await readdir(dir, { withFileTypes: true });
  const found: string[] = [];
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) found.push(...(await listPolicyFiles(full)));
    else if (/\.ya?ml$/i.test(entry.name)) found.push(full);
  }
  return found.sort();
}

async function loadPolicyFile(
  absolute: string,
  relative: string,
  knownRuleIds: ReadonlySet<string>,
): Promise<{ policies: readonly LoadedPolicy[]; errors: readonly PolicyError[] }> {
  let text: string;
  try {
    text = await readFile(absolute, "utf8");
  } catch (cause) {
    return {
      policies: [],
      errors: [
        new PolicyError("policy-invalid", `Cannot read policy file ${relative}`, {
          file: relative,
          cause,
        }),
      ],
    };
  }

  const document = parseDocument(text);
  if (document.errors.length > 0) {
    return {
      policies: [],
      errors: document.errors.map((error) => {
        const line = error.linePos?.[0]?.line;
        return new PolicyError(
          "policy-yaml",
          `Invalid YAML${line === undefined ? "" : ` at line ${line}`}: ${error.message.split("\n")[0]}`,
          { file: relative, suggestion: "Fix the YAML syntax (check indentation and quoting)." },
        );
      }),
    };
  }

  return validatePolicyDocument(document.toJS() as unknown, relative, knownRuleIds);
}
