import { z } from "zod";
import { severitySchema, suppressionEntrySchema } from "../core/config";

const policyPathsSchema = z
  .object({
    include: z.array(z.string()).default([]),
    exclude: z.array(z.string()).default([]),
  })
  .strict();

/** Suppression scoped to one policy; the rule is implied by the policy. */
const policySuppressionSchema = suppressionEntrySchema.omit({ ruleId: true });

export const policySchema = z
  .object({
    id: z
      .string()
      .regex(/^[a-z0-9][a-z0-9-]*$/, "id must be lowercase letters, digits, and hyphens"),
    title: z.string().trim().min(1),
    description: z.string().optional(),
    category: z
      .string()
      .trim()
      .min(1)
      .regex(/^[a-z][a-z0-9-]*$/, "category must be lowercase (e.g. security)"),
    severity: severitySchema,
    enabled: z.boolean().default(true),
    languages: z.array(z.string().min(1)).min(1).default(["typescript"]),
    paths: policyPathsSchema.prefault({}),
    rule: z.string().min(1),
    options: z.record(z.string(), z.unknown()).default({}),
    remediation: z.string().optional(),
    evidence: z
      .object({ required: z.literal(true, "evidence.required cannot be disabled") })
      .strict()
      .prefault({ required: true }),
    ai: z
      .object({ allowed: z.boolean().default(false) })
      .strict()
      .prefault({}),
    suppressions: z.array(policySuppressionSchema).default([]),
    documentationUrl: z.url().optional(),
  })
  .strict();

/** One policy definition after validation and defaulting. */
export type PolicyDefinition = z.infer<typeof policySchema>;

export const policyFileSchema = z
  .object({
    version: z.number().int(),
    policies: z.array(policySchema).min(1, "a policy file must define at least one policy"),
  })
  .strict();

export type PolicyFile = z.infer<typeof policyFileSchema>;

/** A validated policy together with the file it came from. */
export interface LoadedPolicy extends PolicyDefinition {
  readonly sourceFile: string;
}
