import { toPolicyGuardError, RuleError, type PolicyGuardError } from "../core/errors";
import type { Finding } from "../core/types";
import { policiesForRule } from "../policies/policy-context";
import { compareSeverityDesc } from "../utils/severity";
import { dependencyWithoutLockfileUpdate } from "./built-in/dependency-without-lockfile-update";
import { deletedTestRequiresJustification } from "./built-in/deleted-test-requires-justification";
import { migrationRequiresRollback } from "./built-in/migration-requires-rollback";
import { newRouteRequiresAuthorization } from "./built-in/new-route-requires-authorization";
import { noDirectDbAccessInUi } from "./built-in/no-direct-db-access-in-ui";
import { protectedPathRequiresReviewAnnotation } from "./built-in/protected-path-requires-review-annotation";
import { publicApiBreakingChange } from "./built-in/public-api-breaking-change";
import { secretDetectedInSource } from "./built-in/secret-detected-in-source";
import type { RuleContext } from "./rule-context";
import type { PolicyRuleImplementation } from "./rule-result";

/** Registry of available rule implementations, keyed by rule id. */
export class RuleRegistry {
  private readonly rules = new Map<string, PolicyRuleImplementation>();

  register(rule: PolicyRuleImplementation): this {
    if (this.rules.has(rule.id)) throw new RuleError(`Rule "${rule.id}" is already registered`);
    this.rules.set(rule.id, rule);
    return this;
  }

  get(id: string): PolicyRuleImplementation | undefined {
    return this.rules.get(id);
  }

  has(id: string): boolean {
    return this.rules.has(id);
  }

  ids(): ReadonlySet<string> {
    return new Set(this.rules.keys());
  }

  all(): readonly PolicyRuleImplementation[] {
    return [...this.rules.values()];
  }
}

/** Registry containing the eight built-in rules. */
export function createDefaultRegistry(): RuleRegistry {
  return new RuleRegistry()
    .register(newRouteRequiresAuthorization)
    .register(migrationRequiresRollback)
    .register(noDirectDbAccessInUi)
    .register(deletedTestRequiresJustification)
    .register(protectedPathRequiresReviewAnnotation)
    .register(secretDetectedInSource)
    .register(dependencyWithoutLockfileUpdate)
    .register(publicApiBreakingChange);
}

export interface RuleRunOutput {
  readonly findings: readonly Finding[];
  readonly errors: readonly PolicyGuardError[];
  readonly executedRules: readonly string[];
  readonly skippedRules: readonly { readonly ruleId: string; readonly reason: string }[];
}

/**
 * Runs every registered rule that at least one enabled policy references.
 * A rule that throws is reported as an error and never aborts the others.
 */
export async function runRules(
  registry: RuleRegistry,
  context: RuleContext,
): Promise<RuleRunOutput> {
  const findings = new Map<string, Finding>();
  const errors: PolicyGuardError[] = [];
  const executedRules: string[] = [];
  const skippedRules: { ruleId: string; reason: string }[] = [];

  for (const rule of registry.all()) {
    if (policiesForRule(context.policies, rule.id).length === 0) {
      skippedRules.push({ ruleId: rule.id, reason: "no enabled policy references this rule" });
      continue;
    }
    try {
      const result = await rule.run(context);
      if (result.skipped) {
        skippedRules.push({ ruleId: rule.id, reason: result.skipReason ?? "skipped" });
        continue;
      }
      executedRules.push(rule.id);
      for (const finding of result.findings) findings.set(finding.id, finding);
      errors.push(...result.errors);
    } catch (cause) {
      errors.push(
        new RuleError(`Rule "${rule.id}" failed: ${toPolicyGuardError(cause).message}`, { cause }),
      );
    }
  }

  return { findings: sortFindings([...findings.values()]), errors, executedRules, skippedRules };
}

/** Orders findings by severity (worst first), then file and line. */
export function sortFindings(findings: readonly Finding[]): Finding[] {
  return [...findings].sort(
    (a, b) =>
      compareSeverityDesc(a.severity, b.severity) ||
      a.file.localeCompare(b.file) ||
      (a.startLine ?? 0) - (b.startLine ?? 0) ||
      a.id.localeCompare(b.id),
  );
}
