import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";
import { INDEXER_VERSION, type FileIndex } from "./types";

interface CacheFile {
  readonly version: number;
  readonly entries: Record<string, FileIndex>;
}

/** Content-hash keyed cache of per-file indexes, persisted as a single JSON file. */
export class IndexCache {
  private readonly entries = new Map<string, FileIndex>();
  private dirty = false;

  /** Key combining indexer version, content hash, and path (indexes embed the path). */
  static key(filePath: string, hash: string): string {
    return `${INDEXER_VERSION}:${hash}:${filePath}`;
  }

  get(key: string): FileIndex | undefined {
    return this.entries.get(key);
  }

  set(key: string, value: FileIndex): void {
    this.entries.set(key, value);
    this.dirty = true;
  }

  get size(): number {
    return this.entries.size;
  }

  /** Loads a cache file. A missing, corrupt, or outdated file yields an empty cache. */
  static async load(filePath: string): Promise<IndexCache> {
    const cache = new IndexCache();
    try {
      const parsed = JSON.parse(await readFile(filePath, "utf8")) as Partial<CacheFile>;
      if (parsed.version === INDEXER_VERSION && parsed.entries) {
        for (const [key, value] of Object.entries(parsed.entries)) cache.entries.set(key, value);
      }
    } catch {
      // Cache is an optimization only.
    }
    return cache;
  }

  /** Persists only entries for `liveKeys`, dropping stale content. Failures are ignored. */
  async save(filePath: string, liveKeys: ReadonlySet<string>): Promise<void> {
    if (!this.dirty) return;
    const entries: Record<string, FileIndex> = {};
    for (const key of liveKeys) {
      const value = this.entries.get(key);
      if (value) entries[key] = value;
    }
    try {
      await mkdir(path.dirname(filePath), { recursive: true });
      const temp = `${filePath}.${process.pid}.tmp`;
      await writeFile(
        temp,
        JSON.stringify({ version: INDEXER_VERSION, entries } satisfies CacheFile),
      );
      await rename(temp, filePath);
      this.dirty = false;
    } catch {
      // Ignore: read-only checkouts must still be reviewable.
    }
  }
}
