import path from "node:path";

/** Converts Windows separators to POSIX separators. */
export function toPosix(value: string): string {
  return value.split(path.sep).join("/").replace(/\\/g, "/");
}

const LANGUAGE_BY_EXTENSION: Record<string, string> = {
  ".ts": "typescript",
  ".tsx": "typescript",
  ".mts": "typescript",
  ".cts": "typescript",
  ".js": "javascript",
  ".jsx": "javascript",
  ".mjs": "javascript",
  ".cjs": "javascript",
  ".json": "json",
  ".yaml": "yaml",
  ".yml": "yaml",
  ".md": "markdown",
  ".sql": "sql",
  ".prisma": "prisma",
};

/** Detects a language label from a file path, or undefined when unknown. */
export function detectLanguage(filePath: string): string | undefined {
  return LANGUAGE_BY_EXTENSION[path.posix.extname(filePath).toLowerCase()];
}

/** True for TypeScript/JavaScript source that ts-morph can parse. */
export function isScriptFile(filePath: string): boolean {
  const language = detectLanguage(filePath);
  return language === "typescript" || language === "javascript";
}

/** Normalizes a repository-relative path to POSIX form without a leading `./`. */
export function normalizeRepoPath(value: string): string {
  return toPosix(value).replace(/^\.\//, "");
}
