import { spawn, type ChildProcessWithoutNullStreams } from "node:child_process";
import { GitError } from "../core/errors";
import type { GitClient } from "./git-client";

/** Read-only view of repository files at a fixed point in history. */
export interface RepositoryReader {
  /** Human-readable ref label (for diagnostics). */
  readonly label: string;
  /** Repository-relative POSIX paths of all files. */
  listFiles(): Promise<readonly string[]>;
  /** File contents as UTF-8, or undefined when missing, binary, or too large. */
  readFile(filePath: string): Promise<string | undefined>;
  /** Batch read; missing files are omitted from the map. */
  readFiles(filePaths: readonly string[]): Promise<ReadonlyMap<string, string>>;
  /** Releases resources (child processes). Safe to call more than once. */
  close?(): Promise<void>;
}

/** Files larger than this are skipped by the reader. */
export const MAX_READ_BYTES = 1024 * 1024;

interface CatFileObject {
  readonly type: string;
  readonly content: Buffer;
}

interface PendingRequest {
  readonly resolve: (value: CatFileObject | undefined) => void;
  readonly reject: (error: Error) => void;
}

/**
 * One long-lived `git cat-file --batch` process. Requests are pipelined and answered
 * in order, so reading hundreds of files costs a single process spawn.
 */
class CatFileProcess {
  private readonly child: ChildProcessWithoutNullStreams;
  private readonly pending: PendingRequest[] = [];
  private buffer: Buffer = Buffer.alloc(0);
  private failure: Error | undefined;
  private stderr = "";

  private readonly exited: Promise<void>;

  constructor(cwd: string) {
    this.child = spawn("git", ["cat-file", "--batch"], { cwd, windowsHide: true });
    this.exited = new Promise((resolve) => {
      this.child.once("close", () => resolve());
      this.child.once("error", () => resolve());
    });
    this.child.stdout.on("data", (chunk: Buffer) => {
      this.buffer = Buffer.concat([this.buffer, chunk]);
      this.drain();
    });
    this.child.stderr.on("data", (chunk: Buffer) => {
      this.stderr += chunk.toString("utf8");
    });
    this.child.on("error", (cause) =>
      this.fail(new GitError("git-failure", "Failed to start git cat-file", { cause })),
    );
    this.child.on("close", (code) => {
      if (this.pending.length > 0) {
        this.fail(
          new GitError("git-failure", `git cat-file exited with ${code}: ${this.stderr.trim()}`),
        );
      }
    });
    this.child.stdin.on("error", () => {
      // Reported through the close handler.
    });
  }

  request(spec: string): Promise<CatFileObject | undefined> {
    if (this.failure) return Promise.reject(this.failure);
    return new Promise((resolve, reject) => {
      this.pending.push({ resolve, reject });
      this.child.stdin.write(`${spec}\n`);
    });
  }

  /** Ends the process and waits for it to exit so the repository directory is released. */
  async close(): Promise<void> {
    this.child.stdin.end();
    const timer = setTimeout(() => this.child.kill(), 5000);
    await this.exited;
    clearTimeout(timer);
  }

  private fail(error: Error): void {
    this.failure = error;
    for (const request of this.pending.splice(0)) request.reject(error);
  }

  private drain(): void {
    while (this.pending.length > 0) {
      const newline = this.buffer.indexOf(0x0a);
      if (newline === -1) return;
      const header = this.buffer.subarray(0, newline).toString("utf8");
      const match = /^[0-9a-f]+ (\w+) (\d+)$/.exec(header);
      if (!match) {
        // "<spec> missing" or "<spec> ambiguous": no body follows.
        this.buffer = this.buffer.subarray(newline + 1);
        this.pending.shift()?.resolve(undefined);
        continue;
      }
      const size = Number(match[2]);
      const end = newline + 1 + size;
      if (this.buffer.length < end + 1) return; // wait for the full body and trailing newline
      const content = Buffer.from(this.buffer.subarray(newline + 1, end));
      this.buffer = this.buffer.subarray(end + 1);
      this.pending.shift()?.resolve({ type: match[1] as string, content });
    }
  }
}

/** Reads files straight from Git objects at a commit, independent of the working tree. */
export class GitObjectReader implements RepositoryReader {
  private files: Promise<readonly string[]> | undefined;
  private process: CatFileProcess | undefined;
  private readonly cache = new Map<string, Promise<string | undefined>>();

  constructor(
    private readonly client: GitClient,
    private readonly commit: string,
    readonly label: string = commit,
  ) {}

  listFiles(): Promise<readonly string[]> {
    this.files ??= this.client.listFiles(this.commit);
    return this.files;
  }

  readFile(filePath: string): Promise<string | undefined> {
    let result = this.cache.get(filePath);
    if (!result) {
      this.process ??= new CatFileProcess(this.client.repositoryPath);
      result = this.process.request(`${this.commit}:${filePath}`).then(toText);
      this.cache.set(filePath, result);
    }
    return result;
  }

  async readFiles(filePaths: readonly string[]): Promise<ReadonlyMap<string, string>> {
    const entries = await Promise.all(
      filePaths.map(async (filePath) => [filePath, await this.readFile(filePath)] as const),
    );
    const result = new Map<string, string>();
    for (const [filePath, content] of entries)
      if (content !== undefined) result.set(filePath, content);
    return result;
  }

  async close(): Promise<void> {
    const active = this.process;
    this.process = undefined;
    await active?.close();
  }
}

function toText(object: CatFileObject | undefined): string | undefined {
  if (!object || object.type !== "blob") return undefined;
  if (object.content.length > MAX_READ_BYTES || object.content.includes(0)) return undefined;
  return object.content.toString("utf8");
}
