import { DEFAULT_HEAD_REF, FALLBACK_BASE_REFS } from "../core/constants";
import { GitError } from "../core/errors";
import { err, ok, type Result } from "../core/result";
import type { ResolvedRef } from "./git-client";

/** Minimal ref resolver so branch logic is testable without Git. */
export interface RefResolver {
  resolveRef(ref: string): Promise<string | undefined>;
}

export type RefSource = "cli" | "config" | "fallback" | "default";

export interface ResolvedRefChoice extends ResolvedRef {
  readonly source: RefSource;
}

export interface BaseRefResolution {
  readonly ref: ResolvedRefChoice;
  /** Non-fatal notes, e.g. the configured base was missing so a fallback was used. */
  readonly warnings: readonly string[];
}

export interface BaseRefInput {
  readonly explicit?: string;
  readonly configured?: string;
}

/**
 * Resolves the base ref in priority order: `--base`, `review.defaultBase`,
 * `origin/main`, `main`, `master`. An explicit `--base` that does not resolve
 * is a hard error; a missing configured default falls through with a warning.
 */
export async function resolveBaseRef(
  resolver: RefResolver,
  input: BaseRefInput,
): Promise<Result<BaseRefResolution, GitError>> {
  const warnings: string[] = [];

  if (input.explicit !== undefined) {
    const sha = await resolver.resolveRef(input.explicit);
    if (!sha) return err(refNotFound("base", input.explicit));
    return ok({ ref: { name: input.explicit, sha, source: "cli" }, warnings });
  }

  if (input.configured !== undefined) {
    const sha = await resolver.resolveRef(input.configured);
    if (sha) return ok({ ref: { name: input.configured, sha, source: "config" }, warnings });
    warnings.push(
      `Configured review.defaultBase "${input.configured}" was not found; trying fallbacks.`,
    );
  }

  for (const candidate of FALLBACK_BASE_REFS) {
    const sha = await resolver.resolveRef(candidate);
    if (sha) return ok({ ref: { name: candidate, sha, source: "fallback" }, warnings });
  }

  return err(
    new GitError(
      "ref-not-found",
      `Could not resolve a base ref (tried ${[input.configured, ...FALLBACK_BASE_REFS].filter(Boolean).join(", ")}).`,
      {
        suggestion:
          "Pass --base <ref>, set review.defaultBase, or fetch the base branch (in CI use actions/checkout with fetch-depth: 0).",
      },
    ),
  );
}

/** Resolves the head ref: `--head` or `HEAD`. */
export async function resolveHeadRef(
  resolver: RefResolver,
  explicit?: string,
): Promise<Result<ResolvedRefChoice, GitError>> {
  const name = explicit ?? DEFAULT_HEAD_REF;
  const sha = await resolver.resolveRef(name);
  if (!sha) return err(refNotFound("head", name));
  return ok({ name, sha, source: explicit === undefined ? "default" : "cli" });
}

function refNotFound(kind: "base" | "head", name: string): GitError {
  return new GitError("ref-not-found", `Cannot resolve ${kind} ref "${name}".`, {
    suggestion: `Check the ref name with \`git rev-parse --verify ${name}\` or fetch it first.`,
  });
}
