import { LlmError, toPolicyGuardError } from "../core/errors";
import type { ReviewInput } from "../review/review-engine";
import { analyzeWithLlm } from "./context-analyzer";
import type { LlmClient } from "./llm-client";
import { OpenAiCompatibleClient } from "./openai-compatible-client";

export interface AiStageOptions {
  readonly env: NodeJS.ProcessEnv;
  /** Replaces the provider client (tests, custom providers). */
  readonly client?: LlmClient;
}

/**
 * Creates the `extraFindings` hook for the review engine. The hook is a no-op unless AI is
 * enabled by `--ai` or `review.ai.enabled`; `--no-ai` always wins.
 */
export function createAiStage(options: AiStageOptions): NonNullable<ReviewInput["extraFindings"]> {
  return async (context, deterministic) => {
    const ai = context.config.review.ai;
    const enabled = context.options.ai ?? ai.enabled;
    if (!enabled) return { findings: [], errors: [] };

    let client = options.client;
    if (!client) {
      const apiKey = options.env[ai.apiKeyEnvVar];
      if (!apiKey) {
        return {
          findings: [],
          errors: [
            new LlmError(
              "llm-failure",
              `AI analysis is enabled but ${ai.apiKeyEnvVar} is not set.`,
              {
                suggestion: `Export ${ai.apiKeyEnvVar} in the environment (never put API keys in configuration files), or run with --no-ai.`,
              },
            ),
          ],
        };
      }
      try {
        client = new OpenAiCompatibleClient({
          model: ai.model,
          apiKey,
          ...(ai.baseUrl === undefined ? {} : { baseUrl: ai.baseUrl }),
        });
      } catch (cause) {
        return { findings: [], errors: [toPolicyGuardError(cause, "llm-failure")] };
      }
    }

    const result = await analyzeWithLlm({ context, deterministic, client, ai });
    return { findings: result.findings, errors: result.errors, notes: result.notes };
  };
}
