import type { z } from "zod";
import { RuleError } from "../core/errors";
import type {
  ChangedFile,
  Confidence,
  DiffFileStatus,
  Evidence,
  Finding,
  Severity,
} from "../core/types";
import type { LoadedPolicy } from "../policies/policy-schema";
import { policyCoversLanguage } from "../policies/policy-context";
import { sha256 } from "../utils/hash";
import { matchesPathFilter, type PathFilter } from "../utils/glob";
import { severityRank } from "../utils/severity";
import type { RuleContext } from "./rule-context";

// ------------------------------------------------------------- findings

/** Stable finding id derived from the rule, location, and a discriminating key. */
export function findingId(
  ruleId: string,
  file: string,
  line: number | undefined,
  key: string,
): string {
  return `pg-${sha256([ruleId, file, String(line ?? 0), key].join("\0")).slice(0, 10)}`;
}

export interface FindingInput {
  readonly ruleId: string;
  readonly policy: LoadedPolicy;
  readonly title: string;
  readonly message: string;
  readonly file: string;
  readonly startLine?: number;
  readonly endLine?: number;
  readonly evidence: readonly Evidence[];
  readonly confidence: Confidence;
  /** Seed that distinguishes several findings at the same location. */
  readonly key?: string;
  /** Lowers (never raises) the policy severity, e.g. for uncertain results. */
  readonly severityCap?: Severity;
  readonly remediation?: string;
  readonly suggestedPatch?: string;
}

/**
 * Builds a deterministic finding. Severity comes from the policy (the user's override);
 * a finding without evidence is a programming error and throws.
 */
export function createFinding(input: FindingInput): Finding {
  if (input.evidence.length === 0) {
    throw new RuleError(`Rule ${input.ruleId} produced a finding without evidence`);
  }
  const severity =
    input.severityCap !== undefined &&
    severityRank(input.severityCap) < severityRank(input.policy.severity)
      ? input.severityCap
      : input.policy.severity;
  const remediation = input.remediation ?? input.policy.remediation?.trim();
  return {
    id: findingId(input.ruleId, input.file, input.startLine, input.key ?? input.title),
    ruleId: input.ruleId,
    policyId: input.policy.id,
    title: input.title,
    message: input.message,
    severity,
    confidence: input.confidence,
    source: "deterministic",
    file: input.file,
    ...(input.startLine === undefined ? {} : { startLine: input.startLine }),
    ...(input.endLine === undefined ? {} : { endLine: input.endLine }),
    evidence: input.evidence,
    ...(remediation ? { remediation } : {}),
    ...(input.suggestedPatch === undefined ? {} : { suggestedPatch: input.suggestedPatch }),
    ...(input.policy.documentationUrl ? { documentationUrl: input.policy.documentationUrl } : {}),
  };
}

// --------------------------------------------------------------- options

/** Validates a policy's free-form `options` against a rule-specific schema. */
export function parseOptions<S extends z.ZodType>(policy: LoadedPolicy, schema: S): z.output<S> {
  const parsed = schema.safeParse(policy.options);
  if (!parsed.success) {
    const detail = parsed.error.issues
      .map((issue) => `${issue.path.join(".") || "(options)"}: ${issue.message}`)
      .join("; ");
    throw new RuleError(`Invalid options for policy "${policy.id}": ${detail}`, {
      file: policy.sourceFile,
      suggestion: "Fix the policy's options block; see docs/policy-format.md.",
    });
  }
  return parsed.data;
}

// ----------------------------------------------------------------- scope

/** Policy path filter, falling back to configuration paths when the policy sets no `include`. */
export function effectiveFilter(
  policy: LoadedPolicy,
  configDefaults: readonly string[],
): PathFilter {
  return {
    include: policy.paths.include.length > 0 ? policy.paths.include : configDefaults,
    exclude: policy.paths.exclude,
  };
}

export interface ScopeOptions {
  readonly statuses?: readonly DiffFileStatus[];
  /** Skip binary files (default true). */
  readonly includeBinary?: boolean;
}

/** Changed files that the policy targets (language, include/exclude, status). */
export function filesInScope(
  context: RuleContext,
  policy: LoadedPolicy,
  configDefaults: readonly string[] | undefined,
  options: ScopeOptions = {},
): ChangedFile[] {
  const filter =
    configDefaults === undefined
      ? effectiveFilter(policy, [])
      : effectiveFilter(policy, configDefaults);
  return context.changedFiles.filter((file) => {
    if (file.isBinary && !options.includeBinary) return false;
    if (options.statuses && !options.statuses.includes(file.status)) return false;
    return policyCoversLanguage(policy, file.path) && matchesPathFilter(file.path, filter);
  });
}

// ------------------------------------------------------------------ diffs

export interface DiffLineRef {
  readonly line: number;
  readonly content: string;
}

/** Added lines with head-side line numbers. */
export function addedLines(file: ChangedFile): DiffLineRef[] {
  return file.hunks.flatMap((hunk) =>
    hunk.lines.flatMap((line) =>
      line.type === "added" && line.newLineNumber !== undefined
        ? [{ line: line.newLineNumber, content: line.content }]
        : [],
    ),
  );
}

/** Removed lines with base-side line numbers. */
export function removedLines(file: ChangedFile): DiffLineRef[] {
  return file.hunks.flatMap((hunk) =>
    hunk.lines.flatMap((line) =>
      line.type === "removed" && line.oldLineNumber !== undefined
        ? [{ line: line.oldLineNumber, content: line.content }]
        : [],
    ),
  );
}

/** True when any line in `[start, end]` (head side) was added. */
export function rangeTouchesAdded(file: ChangedFile, start: number, end: number): boolean {
  if (file.status === "added") return true;
  return addedLines(file).some((added) => added.line >= start && added.line <= end);
}

/** Maps a base-side line to the nearest head-side line within the diff (best effort). */
export function mapOldToNewLine(file: ChangedFile, oldLine: number): number {
  for (const hunk of file.hunks) {
    for (const line of hunk.lines) {
      if (line.oldLineNumber === oldLine) {
        if (line.newLineNumber !== undefined) return line.newLineNumber;
        return Math.max(1, hunk.newStart);
      }
    }
  }
  return 1;
}

// ------------------------------------------------------------ annotations

export interface ReasonAnnotation {
  readonly line: number;
  /** Trimmed reason, or undefined when the annotation has none. */
  readonly reason?: string;
}

/** Finds `policyguard: <name> reason="..."` annotations (in any comment syntax). */
export function findReasonAnnotations(lines: readonly string[], name: string): ReasonAnnotation[] {
  const pattern = new RegExp(
    `policyguard:\\s*${escapeRegExp(name)}\\b(?:\\s+reason="([^"]*)")?`,
    "i",
  );
  const found: ReasonAnnotation[] = [];
  lines.forEach((text, index) => {
    const match = pattern.exec(text);
    if (!match) return;
    const reason = match[1]?.trim();
    found.push({ line: index + 1, ...(reason ? { reason } : {}) });
  });
  return found;
}

/** Annotations with a non-empty reason found in commit messages. */
export function commitMessageAnnotations(
  messages: readonly string[],
  name: string,
): ReasonAnnotation[] {
  return messages.flatMap((message) =>
    findReasonAnnotations(message.split("\n"), name).filter((a) => a.reason !== undefined),
  );
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// -------------------------------------------------------------- file text

const headLinesCache = new WeakMap<RuleContext, Map<string, readonly string[] | undefined>>();
const baseLinesCache = new WeakMap<RuleContext, Map<string, readonly string[] | undefined>>();

async function cachedLines(
  cache: WeakMap<RuleContext, Map<string, readonly string[] | undefined>>,
  context: RuleContext,
  filePath: string,
  read: (path: string) => Promise<string | undefined>,
): Promise<readonly string[] | undefined> {
  let perContext = cache.get(context);
  if (!perContext) {
    perContext = new Map();
    cache.set(context, perContext);
  }
  if (perContext.has(filePath)) return perContext.get(filePath);
  const content = await read(filePath);
  const lines = content === undefined ? undefined : content.split(/\r?\n/);
  perContext.set(filePath, lines);
  return lines;
}

/** Lines of a file at the head commit, memoized per context. */
export function headLines(
  context: RuleContext,
  filePath: string,
): Promise<readonly string[] | undefined> {
  return cachedLines(headLinesCache, context, filePath, (p) => context.headReader.readFile(p));
}

/** Lines of a file at the merge base, memoized per context. */
export function baseLines(
  context: RuleContext,
  filePath: string,
): Promise<readonly string[] | undefined> {
  return cachedLines(baseLinesCache, context, filePath, (p) => context.baseReader.readFile(p));
}

/** Single-line snippet for evidence, truncated. */
export function snippet(
  lines: readonly string[] | undefined,
  start: number,
  end: number = start,
): string | undefined {
  if (!lines) return undefined;
  const text = lines
    .slice(Math.max(0, start - 1), Math.max(start, end))
    .map((line) => line.trimEnd())
    .join("\n")
    .trim();
  if (!text) return undefined;
  return text.length > 400 ? `${text.slice(0, 400)}...` : text;
}
