import {
  JSON_REPORT_SCHEMA_VERSION,
  SUPPORTED_POLICY_VERSION,
  TOOL_NAME,
  TOOL_VERSION,
} from "../core/constants";
import type { PolicyGuardErrorJson } from "../core/errors";
import type { Finding, ReviewSummary, Severity } from "../core/types";
import type { ReviewOutcome } from "../review/review-engine";

/** Stable, versioned machine-readable report (`review --format json`). */
export interface JsonReport {
  readonly schemaVersion: string;
  readonly tool: { readonly name: string; readonly version: string };
  readonly policyVersion: number;
  readonly repositoryPath: string;
  readonly baseRef: string;
  readonly headRef: string;
  readonly startedAt: string;
  readonly completedAt: string;
  readonly durationMs: number;
  readonly filesChanged: number;
  readonly policiesLoaded: number;
  readonly failOn: Severity;
  readonly strict: boolean;
  /** True when no blocking findings exist (the CLI exits 0). */
  readonly passed: boolean;
  readonly summary: ReviewSummary;
  readonly findings: readonly Finding[];
  readonly errors: readonly PolicyGuardErrorJson[];
  readonly warnings: readonly string[];
}

/** Builds the JSON report object with a fixed key order. */
export function buildJsonReport(outcome: ReviewOutcome): JsonReport {
  const { result } = outcome;
  return {
    schemaVersion: JSON_REPORT_SCHEMA_VERSION,
    tool: { name: TOOL_NAME, version: TOOL_VERSION },
    policyVersion: SUPPORTED_POLICY_VERSION,
    repositoryPath: result.repositoryPath,
    baseRef: result.baseRef,
    headRef: result.headRef,
    startedAt: result.startedAt,
    completedAt: result.completedAt,
    durationMs: result.durationMs,
    filesChanged: outcome.filesChanged,
    policiesLoaded: outcome.policiesLoaded,
    failOn: outcome.failOn,
    strict: outcome.strict,
    passed: outcome.blocking.length === 0,
    summary: result.summary,
    findings: result.findings,
    errors: result.errors.map((error) => error.toJSON()),
    warnings: outcome.warnings,
  };
}

/** Serializes the report as pretty-printed JSON followed by a newline. */
export function renderJsonReport(outcome: ReviewOutcome): string {
  return `${JSON.stringify(buildJsonReport(outcome), null, 2)}\n`;
}
