import {
  Node,
  SyntaxKind,
  type CallExpression,
  type ClassDeclaration,
  type SourceFile,
} from "ts-morph";
import { resolveModulePath } from "./import-graph";
import type { FileIndex, HttpMethod, ImportInfo, MiddlewareUsage, RouteDefinition } from "./types";

const HTTP_METHODS: Readonly<Record<string, HttpMethod>> = {
  get: "GET",
  post: "POST",
  put: "PUT",
  patch: "PATCH",
  delete: "DELETE",
  all: "ALL",
  head: "HEAD",
  options: "OPTIONS",
};

const NEST_DECORATORS: Readonly<Record<string, HttpMethod>> = {
  Get: "GET",
  Post: "POST",
  Put: "PUT",
  Patch: "PATCH",
  Delete: "DELETE",
  All: "ALL",
  Head: "HEAD",
  Options: "OPTIONS",
};

/** Receivers that look like HTTP clients rather than servers. */
const CLIENT_RECEIVERS = new Set([
  "axios",
  "http",
  "https",
  "got",
  "ky",
  "superagent",
  "request",
  "supertest",
  "agent",
  "fetch",
  "client",
  "httpClient",
]);

const FASTIFY_HOOK_PROPS = [
  "preHandler",
  "onRequest",
  "preValidation",
  "preParsing",
  "preSerialization",
];
const MAX_HANDLER_SOURCE = 3000;
const MAX_ARG_TEXT = 200;

export interface RouteExtraction {
  readonly routes: readonly RouteDefinition[];
  readonly middlewareUsages: readonly MiddlewareUsage[];
}

/** Extracts Express, Fastify, and NestJS routes plus middleware mounting from a parsed file. */
export function extractRoutes(
  sourceFile: SourceFile,
  filePath: string,
  imports: readonly ImportInfo[],
): RouteExtraction {
  const framework = detectFramework(imports);
  const routes: RouteDefinition[] = [];
  const middlewareUsages: MiddlewareUsage[] = [];

  for (const call of sourceFile.getDescendantsOfKind(SyntaxKind.CallExpression)) {
    const usage = readMiddlewareUsage(call);
    if (usage) {
      middlewareUsages.push(usage);
      continue;
    }
    const route =
      readRouteCall(call, filePath, framework) ?? readFastifyRouteObject(call, filePath);
    if (route) routes.push(route);
  }

  for (const cls of sourceFile.getClasses()) routes.push(...readNestController(cls, filePath));
  return { routes, middlewareUsages };
}

function detectFramework(imports: readonly ImportInfo[]): "express" | "fastify" {
  const modules = new Set(imports.map((i) => i.moduleSpecifier));
  return modules.has("fastify") || [...modules].some((m) => m.startsWith("@fastify/"))
    ? "fastify"
    : "express";
}

function staticString(node: Node | undefined): string | undefined {
  if (!node) return undefined;
  if (Node.isStringLiteral(node) || Node.isNoSubstitutionTemplateLiteral(node)) {
    return node.getLiteralText();
  }
  if (Node.isTemplateExpression(node)) return node.getText().slice(1, -1);
  return undefined;
}

function short(node: Node): string {
  const text = node.getText().replace(/\s+/g, " ");
  return text.length > MAX_ARG_TEXT ? `${text.slice(0, MAX_ARG_TEXT)}...` : text;
}

function isFunctionLike(node: Node): boolean {
  return Node.isArrowFunction(node) || Node.isFunctionExpression(node);
}

/** References and calls that can be middleware or handlers (not literals). */
function isHandlerReference(node: Node): boolean {
  if (Node.isArrayLiteralExpression(node)) {
    return node.getElements().every((e) => isHandlerReference(e) || isFunctionLike(e));
  }
  return (
    Node.isIdentifier(node) ||
    Node.isPropertyAccessExpression(node) ||
    Node.isCallExpression(node) ||
    Node.isAwaitExpression(node)
  );
}

/** Flattens `[a, b]` arrays into their elements. */
function flatten(node: Node): Node[] {
  return Node.isArrayLiteralExpression(node) ? node.getElements().flatMap(flatten) : [node];
}

function receiverName(expression: Node): string | undefined {
  if (Node.isIdentifier(expression)) return expression.getText();
  if (Node.isPropertyAccessExpression(expression)) return expression.getText();
  if (Node.isThisExpression(expression)) return "this";
  return undefined;
}

function readMiddlewareUsage(call: CallExpression): MiddlewareUsage | undefined {
  const callee = call.getExpression();
  if (!Node.isPropertyAccessExpression(callee)) return undefined;
  const name = callee.getName();
  const receiver = receiverName(callee.getExpression());
  if (receiver === undefined || CLIENT_RECEIVERS.has(receiver)) return undefined;
  const args = call.getArguments();

  if (name === "use" && args.length > 0) {
    const first = staticString(args[0]);
    const rest = first === undefined ? args : args.slice(1);
    return {
      receiver,
      kind: "use",
      ...(first === undefined ? {} : { path: first }),
      args: rest.flatMap(flatten).map(short),
      line: call.getStartLineNumber(),
    };
  }
  if (name === "addHook" && args.length >= 2 && staticString(args[0])) {
    return {
      receiver,
      kind: "hook",
      path: staticString(args[0]) as string,
      args: args.slice(1).flatMap(flatten).map(short),
      line: call.getStartLineNumber(),
    };
  }
  return undefined;
}

function readRouteCall(
  call: CallExpression,
  filePath: string,
  framework: "express" | "fastify",
): RouteDefinition | undefined {
  const callee = call.getExpression();
  if (!Node.isPropertyAccessExpression(callee)) return undefined;
  const method = HTTP_METHODS[callee.getName()];
  if (!method) return undefined;

  const owner = callee.getExpression();
  const args = call.getArguments();
  let routePath: string | undefined;
  let handlerArgs: Node[];
  let receiver: string | undefined;

  if (Node.isCallExpression(owner)) {
    // app.route("/x").get(handler)
    const inner = owner.getExpression();
    if (!(Node.isPropertyAccessExpression(inner) && inner.getName() === "route")) return undefined;
    routePath = staticString(owner.getArguments()[0]);
    handlerArgs = args;
    receiver = receiverName(inner.getExpression());
  } else {
    receiver = receiverName(owner);
    if (receiver === undefined || CLIENT_RECEIVERS.has(receiver)) return undefined;
    if (args.length < 2) return undefined; // Map#get, config.get(...) and similar
    routePath = staticString(args[0]);
    if (routePath === undefined && !Node.isIdentifier(args[0] as Node)) return undefined;
    if (routePath !== undefined && !(routePath.startsWith("/") || routePath === "*"))
      return undefined;
    handlerArgs = args.slice(1);
  }

  const middleware: string[] = [];
  let handler: Node | undefined;
  for (const arg of handlerArgs) {
    if (Node.isObjectLiteralExpression(arg)) {
      middleware.push(...readFastifyOptions(arg));
    } else if (isFunctionLike(arg)) {
      handler = arg;
    } else if (isHandlerReference(arg)) {
      middleware.push(...flatten(arg).map(short));
    } else {
      return undefined; // literals and other expressions are not route handlers
    }
  }
  if (handler === undefined && middleware.length === 0) return undefined;
  if (!handler) {
    // The last non-options argument is the handler when it is a plain identifier/reference.
    const last = handlerArgs[handlerArgs.length - 1];
    if (last && !Node.isObjectLiteralExpression(last)) middleware.pop();
  }

  return {
    framework,
    method,
    path: routePath ?? "<dynamic>",
    file: filePath,
    line: call.getStartLineNumber(),
    endLine: call.getEndLineNumber(),
    ...(receiver === undefined ? {} : { receiver }),
    middleware,
    decorators: [],
    ...(handler ? { handlerSource: handler.getText().slice(0, MAX_HANDLER_SOURCE) } : {}),
  };
}

function readFastifyOptions(options: Node): string[] {
  if (!Node.isObjectLiteralExpression(options)) return [];
  const found: string[] = [];
  for (const name of FASTIFY_HOOK_PROPS) {
    const property = options.getProperty(name);
    if (property && Node.isPropertyAssignment(property)) {
      const initializer = property.getInitializer();
      if (initializer) found.push(...flatten(initializer).map(short));
    } else if (property && Node.isShorthandPropertyAssignment(property)) {
      found.push(property.getName());
    }
  }
  return found;
}

/** `fastify.route({ method: "POST", url: "/x", preHandler, handler })` */
function readFastifyRouteObject(
  call: CallExpression,
  filePath: string,
): RouteDefinition | undefined {
  const callee = call.getExpression();
  if (!(Node.isPropertyAccessExpression(callee) && callee.getName() === "route")) return undefined;
  const arg = call.getArguments()[0];
  if (!arg || !Node.isObjectLiteralExpression(arg)) return undefined;

  const readString = (name: string): string | undefined => {
    const property = arg.getProperty(name);
    return property && Node.isPropertyAssignment(property)
      ? staticString(property.getInitializer())
      : undefined;
  };
  const methodText = readString("method")?.toLowerCase();
  const method = methodText ? HTTP_METHODS[methodText] : undefined;
  const url = readString("url") ?? readString("path");
  if (!method || url === undefined) return undefined;

  const handlerProp = arg.getProperty("handler");
  const handlerNode =
    handlerProp && Node.isPropertyAssignment(handlerProp)
      ? handlerProp.getInitializer()
      : undefined;
  const receiver = receiverName(callee.getExpression());
  return {
    framework: "fastify",
    method,
    path: url,
    file: filePath,
    line: call.getStartLineNumber(),
    endLine: call.getEndLineNumber(),
    ...(receiver === undefined ? {} : { receiver }),
    middleware: readFastifyOptions(arg),
    decorators: [],
    ...(handlerNode ? { handlerSource: handlerNode.getText().slice(0, MAX_HANDLER_SOURCE) } : {}),
  };
}

function readNestController(cls: ClassDeclaration, filePath: string): RouteDefinition[] {
  const controller = cls.getDecorator("Controller");
  if (!controller) return [];
  const prefix = staticString(controller.getArguments()[0]) ?? "";
  const classDecorators = cls
    .getDecorators()
    .map((d) => d.getText().replace(/^@/, "").replace(/\s+/g, " "));

  const routes: RouteDefinition[] = [];
  for (const method of cls.getMethods()) {
    const methodDecorators = method.getDecorators();
    for (const decorator of methodDecorators) {
      const httpMethod = NEST_DECORATORS[decorator.getName()];
      if (!httpMethod) continue;
      const sub = staticString(decorator.getArguments()[0]) ?? "";
      const joined = `/${[prefix, sub]
        .map((p) => p.replace(/^\/+|\/+$/g, ""))
        .filter(Boolean)
        .join("/")}`;
      routes.push({
        framework: "nest",
        method: httpMethod,
        path: joined,
        file: filePath,
        line: method.getStartLineNumber(),
        endLine: method.getEndLineNumber(),
        middleware: [],
        decorators: [
          ...classDecorators,
          ...methodDecorators.map((d) => d.getText().replace(/^@/, "").replace(/\s+/g, " ")),
        ],
        handlerSource: method.getText().slice(0, MAX_HANDLER_SOURCE),
      });
    }
  }
  return routes;
}

export interface MountedMiddleware {
  /** File containing the `app.use(...)` call that mounts the router. */
  readonly file: string;
  readonly line: number;
  readonly path?: string;
  /** Middleware passed alongside the router in the mounting call. */
  readonly middleware: readonly string[];
}

const REQUIRE_ARG = /^require\(\s*["'](.+?)["']\s*\)$/;

/**
 * Finds `app.use("/x", auth, router)` calls in other files that mount the router
 * exported from `routeFile`, returning the middleware applied at mount time.
 */
export function findMountedMiddleware(
  routeFile: string,
  indexes: ReadonlyMap<string, FileIndex>,
  files: ReadonlySet<string>,
): MountedMiddleware[] {
  const mounts: MountedMiddleware[] = [];
  for (const [file, index] of indexes) {
    if (file === routeFile) continue;
    const localToModule = new Map<string, string>();
    for (const imported of index.imports) {
      for (const binding of imported.bindings) {
        localToModule.set(binding.local, imported.moduleSpecifier);
      }
    }
    for (const usage of index.middlewareUsages) {
      if (usage.kind !== "use") continue;
      const routerArg = usage.args.find((arg) => {
        const specifier = REQUIRE_ARG.exec(arg)?.[1] ?? localToModule.get(arg);
        return specifier !== undefined && resolveModulePath(file, specifier, files) === routeFile;
      });
      if (routerArg === undefined) continue;
      mounts.push({
        file,
        line: usage.line,
        ...(usage.path === undefined ? {} : { path: usage.path }),
        middleware: usage.args.filter((arg) => arg !== routerArg),
      });
    }
  }
  return mounts;
}
