import { z } from "zod";
import { LlmError } from "../core/errors";
import type { Confidence, Severity } from "../core/types";

const severitySchema = z.enum(["info", "warning", "error", "critical"]);
const confidenceSchema = z.enum(["low", "medium", "high"]);

const evidenceSchema = z
  .object({
    file: z.string().min(1).max(500),
    startLine: z.number().int().positive().optional(),
    endLine: z.number().int().positive().optional(),
    explanation: z.string().trim().min(1).max(1000),
  })
  .strict();

/** One finding proposed by the model; untrusted until validated. */
export const candidateFindingSchema = z
  .object({
    ruleId: z.string().min(1).max(100),
    title: z.string().trim().min(1).max(200),
    message: z.string().trim().min(1).max(2000),
    severity: severitySchema,
    confidence: confidenceSchema,
    file: z.string().min(1).max(500),
    startLine: z.number().int().positive(),
    endLine: z.number().int().positive(),
    evidence: z.array(evidenceSchema).min(1).max(10),
    remediation: z.string().max(2000).optional(),
  })
  .strict();

/** The only response shape accepted from the model. Unknown keys are rejected. */
export const llmResponseSchema = z
  .object({ findings: z.array(candidateFindingSchema).max(20) })
  .strict();

export interface LlmCandidateFinding {
  ruleId: string;
  title: string;
  message: string;
  severity: Severity;
  confidence: Confidence;
  file: string;
  startLine: number;
  endLine: number;
  evidence: Array<{ file: string; startLine?: number; endLine?: number; explanation: string }>;
  remediation?: string;
}

/** Extracts a JSON document from model text, tolerating a surrounding code fence. */
function extractJson(text: string): string {
  const trimmed = text.trim();
  const fenced = /^```(?:json)?\s*([\s\S]*?)\s*```$/.exec(trimmed);
  return fenced ? (fenced[1] as string) : trimmed;
}

/** Parses and strictly validates a model response. Throws {@link LlmError} on any deviation. */
export function parseLlmResponse(content: string): LlmCandidateFinding[] {
  let json: unknown;
  try {
    json = JSON.parse(extractJson(content));
  } catch (cause) {
    throw new LlmError("llm-invalid-response", "LLM response is not valid JSON", { cause });
  }
  const parsed = llmResponseSchema.safeParse(json);
  if (!parsed.success) {
    const detail = parsed.error.issues
      .slice(0, 3)
      .map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`)
      .join("; ");
    throw new LlmError(
      "llm-invalid-response",
      `LLM response does not match the required schema (${detail})`,
    );
  }
  return parsed.data.findings as LlmCandidateFinding[];
}
