import type { ExportInfo, FileIndex, SymbolInfo } from "./types";

export interface SymbolLocation {
  readonly file: string;
  readonly symbol: SymbolInfo;
}

/** Repository-wide lookup of declared symbols by name. */
export class SymbolTable {
  private readonly byName = new Map<string, SymbolLocation[]>();

  constructor(private readonly indexes: ReadonlyMap<string, FileIndex>) {
    for (const [file, index] of indexes) {
      for (const symbol of index.symbols) {
        const list = this.byName.get(symbol.name) ?? [];
        list.push({ file, symbol });
        this.byName.set(symbol.name, list);
      }
    }
  }

  /** All declarations of `name` across the repository. */
  lookup(name: string): readonly SymbolLocation[] {
    return this.byName.get(name) ?? [];
  }

  /** Exported API of a single file. */
  exportsOf(file: string): readonly ExportInfo[] {
    return this.indexes.get(file)?.exports ?? [];
  }

  get size(): number {
    return this.byName.size;
  }
}
