import { z } from "zod";
import type { ChangedFile, Evidence, Finding } from "../../core/types";
import { resolveModulePath } from "../../indexing/import-graph";
import type { ClassMemberInfo, ExportDetail, FileIndex, ParameterInfo } from "../../indexing/types";
import { policiesForRule } from "../../policies/policy-context";
import type { LoadedPolicy } from "../../policies/policy-schema";
import { matchesPathFilter } from "../../utils/glob";
import type { RuleContext } from "../rule-context";
import type { PolicyRuleImplementation, RuleResult } from "../rule-result";
import {
  baseLines,
  createFinding,
  headLines,
  mapOldToNewLine,
  parseOptions,
  snippet,
} from "../rule-utils";

const RULE_ID = "public-api-breaking-change";
const MAX_REEXPORT_DEPTH = 6;

const optionsSchema = z
  .object({ entryPoints: z.array(z.string().min(1)).default(["src/index.ts"]) })
  .strict();

/** One exported symbol with its resolved definition. */
export interface ApiSymbol {
  readonly name: string;
  readonly detail: ExportDetail;
  readonly definedIn: string;
  readonly line: number;
  /** False when the declaration could not be resolved statically. */
  readonly certain: boolean;
}

export interface PublicApi {
  readonly symbols: ReadonlyMap<string, ApiSymbol>;
  /** Every file that contributes to the API (entry point and re-exported modules). */
  readonly files: ReadonlySet<string>;
}

export type FileIndexLoader = (filePath: string) => Promise<FileIndex | undefined>;

/** Resolves the exported surface of `entry`, following `export *` and named re-exports. */
export async function collectPublicApi(
  entry: string,
  load: FileIndexLoader,
  fileSet: ReadonlySet<string>,
): Promise<PublicApi> {
  const files = new Set<string>();

  async function visit(
    file: string,
    depth: number,
    stack: ReadonlySet<string>,
  ): Promise<Map<string, ApiSymbol>> {
    const result = new Map<string, ApiSymbol>();
    if (depth > MAX_REEXPORT_DEPTH || stack.has(file)) return result;
    const index = await load(file);
    if (!index) return result;
    files.add(file);
    const nextStack = new Set(stack).add(file);

    const stars: string[] = [];
    for (const exported of index.exports) {
      const detail = exported.detail;
      if (detail.kind === "star-reexport") {
        stars.push(detail.from);
      } else if (detail.kind === "reexport") {
        const target = resolveModulePath(file, detail.from, fileSet);
        if (!target && detail.from.startsWith(".")) continue; // re-export of a missing local module
        const resolved =
          target && detail.imported !== "*"
            ? (await visit(target, depth + 1, nextStack)).get(detail.imported)
            : undefined;
        result.set(
          exported.name,
          resolved
            ? { ...resolved, name: exported.name }
            : {
                name: exported.name,
                detail: { kind: "unknown" },
                definedIn: file,
                line: exported.line,
                certain: false,
              },
        );
      } else {
        result.set(exported.name, {
          name: exported.name,
          detail,
          definedIn: file,
          line: exported.line,
          certain: detail.kind !== "unknown",
        });
      }
    }
    for (const from of stars) {
      const target = resolveModulePath(file, from, fileSet);
      if (!target) continue;
      for (const [name, symbol] of await visit(target, depth + 1, nextStack)) {
        if (name !== "default" && !result.has(name)) result.set(name, symbol);
      }
    }
    return result;
  }

  const symbols = await visit(entry, 0, new Set());
  return { symbols, files };
}

export interface ApiChange {
  readonly name: string;
  readonly title: string;
  readonly message: string;
  /** False when compatibility cannot be decided statically. */
  readonly certain: boolean;
}

const normalize = (text: string | undefined): string => (text ?? "").replace(/\s+/g, " ").trim();

function kindLabel(detail: ExportDetail): string {
  switch (detail.kind) {
    case "function":
      return "function";
    case "class":
      return "class";
    case "interface":
      return "interface";
    case "type":
      return "type";
    case "enum":
      return "enum";
    case "variable":
      return "constant";
    default:
      return "export";
  }
}

/** Compares two APIs and lists potentially breaking changes. */
export function compareApis(
  base: ReadonlyMap<string, ApiSymbol>,
  head: ReadonlyMap<string, ApiSymbol>,
): ApiChange[] {
  const changes: ApiChange[] = [];
  for (const [name, before] of base) {
    const after = head.get(name);
    if (!after) {
      changes.push({
        name,
        title: `Exported ${kindLabel(before.detail)} removed`,
        message: `Exported ${kindLabel(before.detail)} "${name}" is no longer exported.`,
        certain: before.certain,
      });
      continue;
    }
    changes.push(...compareSymbol(name, before.detail, after.detail));
  }
  return changes;
}

function compareSymbol(name: string, before: ExportDetail, after: ExportDetail): ApiChange[] {
  if (before.kind === "unknown" || after.kind === "unknown") return [];
  if (before.kind !== after.kind) {
    return [
      {
        name,
        title: "Exported symbol changed kind",
        message: `"${name}" changed from a ${kindLabel(before)} to a ${kindLabel(after)}.`,
        certain: false,
      },
    ];
  }
  if (before.kind === "function" && after.kind === "function") {
    return compareParameters(name, "function", before.parameters, after.parameters);
  }
  if (before.kind === "interface" && after.kind === "interface")
    return compareInterface(name, before, after);
  if (before.kind === "enum" && after.kind === "enum") {
    return before.members
      .filter((member) => !after.members.includes(member))
      .map((member) => ({
        name,
        title: "Enum member removed",
        message: `Enum member "${name}.${member}" was removed.`,
        certain: true,
      }));
  }
  if (before.kind === "class" && after.kind === "class")
    return compareClass(name, before.members, after.members);
  return [];
}

function compareParameters(
  name: string,
  what: string,
  before: readonly ParameterInfo[],
  after: readonly ParameterInfo[],
): ApiChange[] {
  const changes: ApiChange[] = [];
  if (after.length < before.length) {
    const removed = before.slice(after.length);
    changes.push({
      name,
      title: "Function parameter removed",
      message: `${what} "${name}" no longer accepts parameter(s): ${removed.map((p) => p.name).join(", ")}.`,
      certain: removed.some((p) => !p.optional && !p.rest),
    });
  }
  const shared = Math.min(before.length, after.length);
  for (let i = 0; i < shared; i += 1) {
    const b = before[i] as ParameterInfo;
    const a = after[i] as ParameterInfo;
    if (b.optional && !a.optional && !a.rest) {
      changes.push({
        name,
        title: "Function parameter became required",
        message: `Parameter "${a.name}" of ${what} "${name}" is now required.`,
        certain: true,
      });
    } else if (
      b.type !== undefined &&
      a.type !== undefined &&
      normalize(b.type) !== normalize(a.type)
    ) {
      changes.push({
        name,
        title: "Function parameter type changed",
        message: `Parameter "${a.name}" of ${what} "${name}" changed type from \`${normalize(b.type)}\` to \`${normalize(a.type)}\`.`,
        certain: false,
      });
    }
  }
  for (const added of after.slice(before.length)) {
    if (!added.optional && !added.rest) {
      changes.push({
        name,
        title: "Required function parameter added",
        message: `${what} "${name}" gained required parameter "${added.name}".`,
        certain: true,
      });
    }
  }
  return changes;
}

function compareInterface(
  name: string,
  before: Extract<ExportDetail, { kind: "interface" }>,
  after: Extract<ExportDetail, { kind: "interface" }>,
): ApiChange[] {
  const changes: ApiChange[] = [];
  for (const property of before.properties) {
    const next = after.properties.find((p) => p.name === property.name);
    if (!next) {
      changes.push({
        name,
        title: property.optional
          ? "Optional interface property removed"
          : "Required interface property removed",
        message: `Property "${property.name}" was removed from interface "${name}".`,
        certain: !property.optional,
      });
    } else if (!property.optional && next.optional) {
      changes.push({
        name,
        title: "Interface property became optional",
        message: `Required property "${name}.${property.name}" is now optional, so consumers may see undefined.`,
        certain: false,
      });
    } else if (
      !property.optional &&
      property.type !== undefined &&
      next.type !== undefined &&
      normalize(property.type) !== normalize(next.type)
    ) {
      changes.push({
        name,
        title: "Interface property type changed",
        message: `Required property "${name}.${property.name}" changed type from \`${normalize(property.type)}\` to \`${normalize(next.type)}\`.`,
        certain: false,
      });
    }
  }
  for (const parent of before.extends) {
    if (!after.extends.includes(parent)) {
      changes.push({
        name,
        title: "Interface no longer extends a type",
        message: `Interface "${name}" no longer extends ${parent}.`,
        certain: false,
      });
    }
  }
  return changes;
}

function compareClass(
  name: string,
  before: readonly ClassMemberInfo[],
  after: readonly ClassMemberInfo[],
): ApiChange[] {
  const changes: ApiChange[] = [];
  for (const member of before) {
    const next = after.find((m) => m.name === member.name && m.isStatic === member.isStatic);
    if (!next) {
      changes.push({
        name,
        title: "Public class member removed",
        message: `Public ${member.kind} "${name}.${member.name}" was removed.`,
        certain: true,
      });
    } else if (member.parameters && next.parameters) {
      changes.push(
        ...compareParameters(
          name,
          member.kind === "constructor" ? "constructor of class" : `method ${member.name} of class`,
          member.parameters,
          next.parameters,
        ),
      );
    }
  }
  return changes;
}

function signature(detail: ExportDetail): string | undefined {
  if (detail.kind !== "function") return undefined;
  const params = detail.parameters
    .map(
      (p) =>
        `${p.rest ? "..." : ""}${p.name}${p.optional ? "?" : ""}${p.type ? `: ${p.type}` : ""}`,
    )
    .join(", ");
  return `(${params})${detail.returnType ? `: ${detail.returnType}` : ""}`;
}

export const publicApiBreakingChange: PolicyRuleImplementation = {
  id: RULE_ID,
  title: "Public API breaking change",
  description:
    "Detects removed or incompatibly changed exports of the package's public entry points.",
  category: "architecture",
  defaultSeverity: "warning",
  supportedLanguages: ["typescript"],

  async run(context: RuleContext): Promise<RuleResult> {
    const findings: Finding[] = [];
    const repo = context.indexedRepository;
    const headFiles = new Set(repo.files.keys());
    const baseFiles = new Set(await context.baseReader.listFiles());
    const touched = new Set(
      context.changedFiles.flatMap((f) => (f.previousPath ? [f.path, f.previousPath] : [f.path])),
    );

    const baseCache = new Map<string, Promise<FileIndex | undefined>>();
    const loadBase: FileIndexLoader = (filePath) => {
      let cached = baseCache.get(filePath);
      if (!cached) {
        cached = context.baseReader
          .readFile(filePath)
          .then((content) =>
            content === undefined ? undefined : context.indexer.indexContent(filePath, content),
          );
        baseCache.set(filePath, cached);
      }
      return cached;
    };
    const loadHead: FileIndexLoader = async (filePath) => repo.getFileIndex(filePath);

    for (const policy of policiesForRule(context.policies, RULE_ID)) {
      const options = parseOptions(policy, optionsSchema);
      for (const entry of options.entryPoints) {
        if (!matchesPathFilter(entry, policy.paths)) continue;
        const [baseApi, headApi] = await Promise.all([
          collectPublicApi(entry, loadBase, baseFiles),
          collectPublicApi(entry, loadHead, headFiles),
        ]);
        if (baseApi.symbols.size === 0) continue; // new or unreadable entry point
        const closure = [...baseApi.files, ...headApi.files];
        if (!closure.some((file) => touched.has(file))) continue;

        for (const change of compareApis(baseApi.symbols, headApi.symbols)) {
          findings.push(await buildFinding(context, policy, entry, change, baseApi, headApi));
        }
      }
    }
    return { findings, errors: [] };
  },
};

async function buildFinding(
  context: RuleContext,
  policy: LoadedPolicy,
  entry: string,
  change: ApiChange,
  baseApi: PublicApi,
  headApi: PublicApi,
): Promise<Finding> {
  const before = baseApi.symbols.get(change.name);
  const after = headApi.symbols.get(change.name);
  const anchor = after ?? before;
  const file = anchor?.definedIn ?? entry;
  const changedFile: ChangedFile | undefined = context.changedFiles.find(
    (f) => f.path === file || f.previousPath === file,
  );

  let line = after?.line ?? 1;
  let codeLines: readonly string[] | undefined;
  let evidenceFile = file;
  if (after) {
    codeLines = await headLines(context, file);
  } else if (before) {
    codeLines = await baseLines(context, before.definedIn);
    evidenceFile = before.definedIn;
    line = changedFile ? mapOldToNewLine(changedFile, before.line) : 1;
  }

  const evidence: Evidence[] = [];
  const beforeSignature = before ? signature(before.detail) : undefined;
  const afterSignature = after ? signature(after.detail) : undefined;
  const code = before && !after ? snippet(codeLines, before.line) : snippet(codeLines, line);
  evidence.push({
    file: evidenceFile,
    startLine: before && !after ? before.line : line,
    ...(code ? { snippet: code } : {}),
    explanation: change.message,
    source: "diff",
  });
  evidence.push({
    file: entry,
    explanation:
      beforeSignature && afterSignature && beforeSignature !== afterSignature
        ? `Public signature changed: ${change.name}${beforeSignature} -> ${change.name}${afterSignature}`
        : `"${change.name}" is part of the public API exported from ${entry}`,
    source: "repository",
  });

  return createFinding({
    ruleId: RULE_ID,
    policy,
    title: change.title,
    message: `${change.message} This may break consumers of ${entry}.`,
    file,
    startLine: line,
    evidence,
    confidence: change.certain ? "high" : "low",
    key: `${change.name}:${change.title}`,
    ...(change.certain ? {} : { severityCap: "warning" as const }),
    remediation:
      policy.remediation?.trim() ??
      "Keep the old export (deprecate it), make the change additive, or bump the major version and document the migration.",
  });
}
