import { matchesPathFilter } from "../utils/glob";
import { detectLanguage } from "../utils/path";
import type { LoadedPolicy } from "./policy-schema";

/** Enabled policies that target `ruleId`. */
export function policiesForRule(
  policies: readonly LoadedPolicy[],
  ruleId: string,
): readonly LoadedPolicy[] {
  return policies.filter((policy) => policy.enabled && policy.rule === ruleId);
}

/**
 * True when the policy's language list covers the file. "any" matches everything;
 * "typescript" also covers JavaScript sources, which TypeScript tooling analyzes.
 */
export function policyCoversLanguage(policy: LoadedPolicy, filePath: string): boolean {
  if (policy.languages.includes("any")) return true;
  const language = detectLanguage(filePath);
  if (language === undefined) return false;
  if (policy.languages.includes(language)) return true;
  return language === "javascript" && policy.languages.includes("typescript");
}

/** True when the policy's language and path filters both accept the file. */
export function policyAppliesToFile(policy: LoadedPolicy, filePath: string): boolean {
  return policyCoversLanguage(policy, filePath) && matchesPathFilter(filePath, policy.paths);
}

/** True when the policy allows AI-assisted analysis. */
export function policyAllowsAi(policy: LoadedPolicy): boolean {
  return policy.enabled && policy.ai.allowed;
}
