import { z } from "zod";
import type { Evidence, Finding } from "../../core/types";
import { resolveModulePath } from "../../indexing/import-graph";
import { policiesForRule } from "../../policies/policy-context";
import { matchesAny } from "../../utils/glob";
import type { RuleContext } from "../rule-context";
import type { PolicyRuleImplementation, RuleResult } from "../rule-result";
import {
  addedLines,
  createFinding,
  filesInScope,
  headLines,
  parseOptions,
  snippet,
} from "../rule-utils";

const RULE_ID = "no-direct-db-access-in-ui";

const DEFAULT_FORBIDDEN = [
  "pg",
  "mysql2",
  "mongoose",
  "prisma",
  "@prisma/client",
  "knex",
  "typeorm",
  "sequelize",
];

const optionsSchema = z
  .object({
    forbiddenModules: z.array(z.string()).default(DEFAULT_FORBIDDEN),
    allowedModules: z.array(z.string()).default([]),
    allowedImportPaths: z.array(z.string()).default(["src/services/**"]),
  })
  .strict();

function matchesModule(specifier: string, modules: readonly string[]): string | undefined {
  return modules.find((m) => specifier === m || specifier.startsWith(`${m}/`));
}

export const noDirectDbAccessInUi: PolicyRuleImplementation = {
  id: RULE_ID,
  title: "No direct database access in UI code",
  description:
    "UI modules must not import database clients, ORMs, or query builders, directly or via data-access modules.",
  category: "architecture",
  defaultSeverity: "error",
  supportedLanguages: ["typescript"],

  async run(context: RuleContext): Promise<RuleResult> {
    const findings: Finding[] = [];
    const repo = context.indexedRepository;
    const fileSet = new Set(repo.files.keys());

    for (const policy of policiesForRule(context.policies, RULE_ID)) {
      const options = parseOptions(policy, optionsSchema);
      const files = filesInScope(context, policy, context.config.paths.ui, {
        statuses: ["added", "modified", "renamed"],
      });

      for (const file of files) {
        const index = repo.getFileIndex(file.path);
        if (!index) continue;
        const added = new Set(
          file.status === "added" ? undefined : addedLines(file).map((l) => l.line),
        );
        const lines = await headLines(context, file.path);

        for (const imported of index.imports) {
          if (imported.isTypeOnly) continue;
          if (file.status !== "added" && !added.has(imported.line)) continue; // only newly introduced imports
          const specifier = imported.moduleSpecifier;
          if (matchesModule(specifier, options.allowedModules)) continue;

          const forbidden = matchesModule(specifier, options.forbiddenModules);
          let via: string | undefined;
          let confidence: "high" | "medium" = "high";

          if (!forbidden) {
            // One hop: a local data-access module that itself imports a forbidden client.
            const target = resolveModulePath(file.path, specifier, fileSet);
            if (!target || matchesAny(target, options.allowedImportPaths)) continue;
            const targetIndex = repo.getFileIndex(target);
            const inner = targetIndex?.imports.find(
              (i) => !i.isTypeOnly && matchesModule(i.moduleSpecifier, options.forbiddenModules),
            );
            if (!inner) continue;
            via = `${target} imports "${inner.moduleSpecifier}"`;
            confidence = "medium";
          }

          const evidence: Evidence[] = [
            {
              file: file.path,
              startLine: imported.line,
              ...(snippet(lines, imported.line)
                ? { snippet: snippet(lines, imported.line) as string }
                : {}),
              explanation: via
                ? `UI code imports "${specifier}", a data-access module (${via})`
                : `UI code imports the database module "${specifier}"`,
              source: "diff",
            },
            {
              file: file.path,
              explanation: `${file.path} is a UI path (${(policy.paths.include.length > 0 ? policy.paths.include : context.config.paths.ui).join(", ")})`,
              source: "configuration",
            },
          ];
          findings.push(
            createFinding({
              ruleId: RULE_ID,
              policy,
              title: "UI code accesses the database directly",
              message: `${file.path} imports "${specifier}", which gives UI code direct database access.`,
              file: file.path,
              startLine: imported.line,
              evidence,
              confidence,
              key: specifier,
              remediation:
                policy.remediation?.trim() ??
                "Move the data access into a service module and import that service instead.",
            }),
          );
        }
      }
    }
    return { findings, errors: [] };
  },
};
