import { z } from "zod";
import type { Finding } from "../../core/types";
import { policiesForRule } from "../../policies/policy-context";
import { matchesAny } from "../../utils/glob";
import type { RuleContext } from "../rule-context";
import type { PolicyRuleImplementation, RuleResult } from "../rule-result";
import { addedLines, createFinding, filesInScope, parseOptions } from "../rule-utils";

const RULE_ID = "secret-detected-in-source";

const optionsSchema = z
  .object({
    /** Regular expressions; a changed line matching any of them is never reported. */
    allowlistPatterns: z.array(z.string()).default([]),
    /** Report secrets in test, fixture, and documentation files too. */
    reportTestFixtures: z.boolean().default(false),
  })
  .strict();

const FIXTURE_PATHS = [
  "**/*.test.*",
  "**/*.spec.*",
  "**/__tests__/**",
  "**/__mocks__/**",
  "**/fixtures/**",
  "**/__fixtures__/**",
  "**/*.md",
  "**/*.mdx",
  "**/*.example",
  "**/.env.example",
  "**/.env.sample",
];

/** Substrings that mark a value as obviously fake or documentation-only. */
const FAKE_MARKERS =
  /example|fake|dummy|placeholder|changeme|change-me|your[_-]|xxxx|redacted|sample|not[_-]?a[_-]?real|insert[_-]|todo|<[^>]+>|\$\{|\{\{|process\.env|import\.meta|env\./i;

/** Values that are generic words rather than credentials. */
const PLACEHOLDER_VALUE =
  /^(password|passwd|pass|secret|changeit|admin|root|postgres|user|username|token|key)$/i;

interface Detector {
  readonly id: string;
  readonly label: string;
  readonly pattern: RegExp;
  /** Capture group holding the secret value; 0 = whole match. */
  readonly group: number;
  readonly minEntropy?: number;
}

const DETECTORS: readonly Detector[] = [
  {
    id: "private-key",
    label: "Private key",
    pattern: /-----BEGIN (?:RSA |EC |DSA |OPENSSH |PGP |ENCRYPTED )?PRIVATE KEY(?: BLOCK)?-----/,
    group: 0,
  },
  {
    id: "aws-access-key",
    label: "AWS access key ID",
    pattern: /\b((?:AKIA|ASIA)[0-9A-Z]{16})\b/,
    group: 1,
  },
  {
    id: "github-token",
    label: "GitHub token",
    pattern: /\b(gh[pousr]_[A-Za-z0-9]{36,}|github_pat_[A-Za-z0-9_]{22,})\b/,
    group: 1,
  },
  {
    id: "anthropic-key",
    label: "Anthropic API key",
    pattern: /\b(sk-ant-[A-Za-z0-9_-]{20,})\b/,
    group: 1,
  },
  {
    id: "openai-key",
    label: "OpenAI API key",
    pattern: /\b(sk-(?:proj-)?[A-Za-z0-9_-]{32,})\b/,
    group: 1,
  },
  {
    id: "google-api-key",
    label: "Google API key",
    pattern: /\b(AIza[0-9A-Za-z_-]{35})\b/,
    group: 1,
  },
  {
    id: "slack-token",
    label: "Slack token",
    pattern: /\b(xox[abprs]-[A-Za-z0-9-]{10,})\b/,
    group: 1,
  },
  {
    id: "stripe-key",
    label: "Stripe live key",
    pattern: /\b((?:sk|rk)_live_[A-Za-z0-9]{16,})\b/,
    group: 1,
  },
  {
    id: "connection-string",
    label: "Database connection string with credentials",
    pattern:
      /\b(?:postgres(?:ql)?|mysql|mariadb|mongodb(?:\+srv)?|redis|amqps?):\/\/[^\s:@/'"`]+:([^\s@/'"`]{3,})@[^\s'"`]+/i,
    group: 1,
  },
  {
    id: "jwt-secret",
    label: "JWT signing secret",
    pattern: /\bjwt[_-]?secret(?:[_-]?key)?\b\s*[:=]\s*(["'`])([^"'`\n]{8,})\1/i,
    group: 2,
    minEntropy: 2.5,
  },
  {
    id: "hardcoded-credential",
    label: "Hard-coded credential",
    pattern:
      /\b[A-Za-z0-9_]*(?:secret|passwd|password|token|api[_-]?key|private[_-]?key|client[_-]?secret)\b["']?\s*[:=]\s*(["'`])([^"'`\n]{10,})\1/i,
    group: 2,
    minEntropy: 3,
  },
];

/** Shannon entropy in bits per character. */
export function shannonEntropy(value: string): number {
  if (value.length === 0) return 0;
  const counts = new Map<string, number>();
  for (const char of value) counts.set(char, (counts.get(char) ?? 0) + 1);
  let entropy = 0;
  for (const count of counts.values()) {
    const p = count / value.length;
    entropy -= p * Math.log2(p);
  }
  return entropy;
}

export interface SecretMatch {
  readonly detector: string;
  readonly label: string;
  /** The matched value, redacted. */
  readonly redacted: string;
}

/** Redacts a secret to its first four characters. */
export function redact(value: string): string {
  return value.length <= 4
    ? "****"
    : `${value.slice(0, 4)}${"*".repeat(Math.min(12, value.length - 4))}`;
}

/** Scans one line for a likely secret. Conservative: obvious placeholders are ignored. */
export function scanLine(line: string, allowlist: readonly RegExp[] = []): SecretMatch | undefined {
  if (allowlist.some((pattern) => pattern.test(line))) return undefined;
  for (const detector of DETECTORS) {
    const match = detector.pattern.exec(line);
    if (!match) continue;
    const value = match[detector.group] ?? match[0];
    if (FAKE_MARKERS.test(value) || PLACEHOLDER_VALUE.test(value)) continue;
    if (detector.minEntropy !== undefined && shannonEntropy(value) < detector.minEntropy) continue;
    if (/^(.)\1+$/.test(value)) continue;
    return { detector: detector.id, label: detector.label, redacted: redact(value) };
  }
  return undefined;
}

export const secretDetectedInSource: PolicyRuleImplementation = {
  id: RULE_ID,
  title: "Secret detected in source",
  description: "Changed lines must not contain likely credentials.",
  category: "security",
  defaultSeverity: "critical",
  supportedLanguages: ["any"],

  run(context: RuleContext): RuleResult {
    const findings: Finding[] = [];
    for (const policy of policiesForRule(context.policies, RULE_ID)) {
      const options = parseOptions(policy, optionsSchema);
      const allowlist = options.allowlistPatterns.map((source) => new RegExp(source));
      const files = filesInScope(context, policy, undefined, {
        statuses: ["added", "modified", "renamed"],
      });

      for (const file of files) {
        if (!options.reportTestFixtures && matchesAny(file.path, FIXTURE_PATHS)) continue;
        for (const added of addedLines(file)) {
          if (added.content.length > 2000) continue; // minified or generated content
          const hit = scanLine(added.content, allowlist);
          if (!hit) continue;
          findings.push(
            createFinding({
              ruleId: RULE_ID,
              policy,
              title: `${hit.label} in source`,
              message: `A likely ${hit.label.toLowerCase()} was added to ${file.path}.`,
              file: file.path,
              startLine: added.line,
              evidence: [
                {
                  file: file.path,
                  startLine: added.line,
                  endLine: added.line,
                  snippet: redactLine(added.content, hit),
                  explanation: `Added line matches the ${hit.detector} detector (value ${hit.redacted})`,
                  source: "diff",
                },
              ],
              confidence: hit.detector === "hardcoded-credential" ? "medium" : "high",
              key: hit.detector,
              remediation:
                policy.remediation?.trim() ??
                "Remove the secret, rotate it, and load it from the environment or a secret manager.",
            }),
          );
        }
      }
    }
    return { findings, errors: [] };
  },
};

/** Masks the secret value inside the evidence snippet so reports never leak it. */
function redactLine(line: string, match: SecretMatch): string {
  const prefix = match.redacted.replace(/\*+$/, "");
  const text = line.trim().slice(0, 300);
  const start = prefix.length > 0 ? text.indexOf(prefix) : -1;
  if (start === -1) return text.replace(/(["'`])[^"'`]{8,}\1/g, '"****"');
  const secretEnd = text.slice(start).search(/["'`\s,;)]/);
  const end = secretEnd === -1 ? text.length : start + secretEnd;
  return `${text.slice(0, start)}${match.redacted}${text.slice(end)}`;
}
