import type { Severity } from "../core/types";

export const SEVERITIES: readonly Severity[] = ["info", "warning", "error", "critical"];

const RANK: Record<Severity, number> = { info: 0, warning: 1, error: 2, critical: 3 };

/** Numeric rank of a severity (higher is worse). */
export function severityRank(severity: Severity): number {
  return RANK[severity];
}

/** Orders severities from most to least severe. */
export function compareSeverityDesc(a: Severity, b: Severity): number {
  return RANK[b] - RANK[a];
}

/** True when `severity` is at least as severe as `threshold`. */
export function meetsThreshold(severity: Severity, threshold: Severity): boolean {
  return RANK[severity] >= RANK[threshold];
}

export function isSeverity(value: string): value is Severity {
  return (SEVERITIES as readonly string[]).includes(value);
}

/** Returns an empty severity counter. */
export function emptySeverityCounts(): Record<Severity, number> {
  return { info: 0, warning: 0, error: 0, critical: 0 };
}
