import path from "node:path";
import type { PolicyGuardConfig } from "../core/config";
import { IndexError, type PolicyGuardError } from "../core/errors";
import type { RepositoryReader } from "../git/repository-reader";
import { matchesAny } from "../utils/glob";
import { detectLanguage, isScriptFile } from "../utils/path";
import { IndexedRepository } from "./indexed-repository";
import { IndexCache } from "./index-cache";
import { analyzeMigration } from "./migration-indexer";
import { TypeScriptIndexer } from "./typescript-indexer";
import type { FileEntry, FileIndex, FileKind, MigrationInfo, PackageManifest } from "./types";

const LOCKFILES = new Set([
  "pnpm-lock.yaml",
  "package-lock.json",
  "yarn.lock",
  "npm-shrinkwrap.json",
]);
const IGNORED_SEGMENTS = new Set([
  "node_modules",
  "dist",
  "build",
  "coverage",
  ".next",
  "out",
  "vendor",
  ".git",
]);
const CI_FILES = new Set([".gitlab-ci.yml", "Jenkinsfile", "azure-pipelines.yml"]);
const READ_CHUNK = 400;

/** Upper bound on indexed script files; changed files are always indexed first. */
export const MAX_INDEXED_FILES = 5000;

/** Classifies a file for rules and for sensitive-path detection. */
export function classifyFile(filePath: string, config: PolicyGuardConfig): FileEntry {
  return {
    path: filePath,
    kind: fileKind(filePath, config),
    sensitive: isSensitive(filePath, config),
  };
}

function fileKind(filePath: string, config: PolicyGuardConfig): FileKind {
  const base = path.posix.basename(filePath);
  const language = detectLanguage(filePath);
  if (LOCKFILES.has(base)) return "lockfile";
  if (base === "package.json") return "manifest";
  if (filePath.startsWith(".github/workflows/") || CI_FILES.has(base)) return "ci";
  const migratable = language === "sql" || isScriptFile(filePath);
  if (migratable && matchesAny(filePath, config.paths.migrations)) return "migration";
  if (isScriptFile(filePath) && matchesAny(filePath, config.paths.tests)) return "test";
  if (isScriptFile(filePath)) return "source";
  if (language === "markdown") return "docs";
  if (
    language === "json" ||
    language === "yaml" ||
    /^\.env/.test(base) ||
    /\.config\./.test(base)
  ) {
    return "config";
  }
  return "other";
}

function isSensitive(filePath: string, config: PolicyGuardConfig): boolean {
  return (
    matchesAny(filePath, config.paths.protected) ||
    /(^|\/)\.env(\.|$)/.test(filePath) ||
    /\.(pem|key|p12|pfx)$/i.test(filePath) ||
    /(^|\/)(secrets?|credentials?)(\/|\.|$)/i.test(filePath)
  );
}

export function isIgnoredPath(filePath: string): boolean {
  return filePath.split("/").some((segment) => IGNORED_SEGMENTS.has(segment));
}

/** Parses a package.json body; returns undefined for invalid JSON. */
export function parsePackageManifest(
  filePath: string,
  content: string,
): PackageManifest | undefined {
  try {
    const json = JSON.parse(content) as Record<string, unknown>;
    const read = (key: string): Record<string, string> => {
      const value = json[key];
      if (typeof value !== "object" || value === null) return {};
      return Object.fromEntries(
        Object.entries(value as Record<string, unknown>).filter(
          (entry): entry is [string, string] => typeof entry[1] === "string",
        ),
      );
    };
    return {
      path: filePath,
      ...(typeof json["name"] === "string" ? { name: json["name"] } : {}),
      dependencies: read("dependencies"),
      devDependencies: read("devDependencies"),
      peerDependencies: read("peerDependencies"),
      optionalDependencies: read("optionalDependencies"),
    };
  } catch {
    return undefined;
  }
}

export interface BuildIndexOptions {
  readonly reader: RepositoryReader;
  readonly config: PolicyGuardConfig;
  /** Paths changed in the diff; indexed first so the size cap never drops them. */
  readonly changedPaths?: readonly string[];
  /** Persistent cache file; omit to use an in-memory cache only. */
  readonly cacheFile?: string;
}

/** Builds the semantic index of the repository at the reader's commit. */
export async function buildIndexedRepository(
  options: BuildIndexOptions,
): Promise<IndexedRepository> {
  const { reader, config } = options;
  const errors: PolicyGuardError[] = [];

  const allPaths = await reader.listFiles();
  const files = new Map<string, FileEntry>();
  for (const filePath of allPaths) files.set(filePath, classifyFile(filePath, config));

  const cache = options.cacheFile ? await IndexCache.load(options.cacheFile) : new IndexCache();
  const indexer = new TypeScriptIndexer(cache);

  const changed = new Set(options.changedPaths ?? []);
  const scriptPaths = prioritize(
    allPaths.filter((p) => isScriptFile(p) && !isIgnoredPath(p) && !p.endsWith(".d.ts")),
    changed,
  );
  if (scriptPaths.length > MAX_INDEXED_FILES) {
    errors.push(
      new IndexError(
        `Repository has ${scriptPaths.length} script files; indexing the first ${MAX_INDEXED_FILES} (changed files first).`,
        { suggestion: "Results for unindexed files may be incomplete." },
      ),
    );
    scriptPaths.length = MAX_INDEXED_FILES;
  }

  const fileIndexes = new Map<string, FileIndex>();
  for (const chunk of chunks(scriptPaths, READ_CHUNK)) {
    let contents: ReadonlyMap<string, string>;
    try {
      contents = await reader.readFiles(chunk);
    } catch (cause) {
      errors.push(new IndexError(`Failed to read ${chunk.length} files for indexing`, { cause }));
      continue;
    }
    for (const [filePath, content] of contents) {
      try {
        const index = indexer.indexContent(filePath, content);
        fileIndexes.set(filePath, index);
        if (!index.extractionOk) {
          errors.push(
            new IndexError(`Could not fully index ${filePath}; analysis may be partial.`, {
              file: filePath,
            }),
          );
        }
      } catch (cause) {
        errors.push(new IndexError(`Failed to index ${filePath}`, { file: filePath, cause }));
      }
    }
  }

  const manifests = await readManifests(reader, allPaths, errors);
  const migrations = await analyzeMigrations(reader, files, fileIndexes, errors);

  if (options.cacheFile) await cache.save(options.cacheFile, indexer.touchedKeys);
  const cacheHits = indexer.cacheHits;

  return new IndexedRepository({
    reader,
    files,
    fileIndexes,
    manifests,
    migrations,
    errors,
    cacheHits,
  });
}

function prioritize(paths: readonly string[], changed: ReadonlySet<string>): string[] {
  return [...paths.filter((p) => changed.has(p)), ...paths.filter((p) => !changed.has(p))];
}

function chunks<T>(items: readonly T[], size: number): T[][] {
  const result: T[][] = [];
  for (let i = 0; i < items.length; i += size) result.push(items.slice(i, i + size));
  return result;
}

async function readManifests(
  reader: RepositoryReader,
  allPaths: readonly string[],
  errors: PolicyGuardError[],
): Promise<Map<string, PackageManifest>> {
  const manifests = new Map<string, PackageManifest>();
  const manifestPaths = allPaths.filter(
    (p) => path.posix.basename(p) === "package.json" && !isIgnoredPath(p),
  );
  if (manifestPaths.length === 0) return manifests;
  const contents = await reader.readFiles(manifestPaths);
  for (const [filePath, content] of contents) {
    const manifest = parsePackageManifest(filePath, content);
    if (manifest) manifests.set(filePath, manifest);
    else errors.push(new IndexError(`Invalid JSON in ${filePath}`, { file: filePath }));
  }
  return manifests;
}

async function analyzeMigrations(
  reader: RepositoryReader,
  files: ReadonlyMap<string, FileEntry>,
  fileIndexes: ReadonlyMap<string, FileIndex>,
  errors: PolicyGuardError[],
): Promise<Map<string, MigrationInfo>> {
  const migrations = new Map<string, MigrationInfo>();
  const paths = [...files.values()].filter((f) => f.kind === "migration").map((f) => f.path);
  if (paths.length === 0) return migrations;
  try {
    const contents = await reader.readFiles(paths);
    for (const [filePath, content] of contents) {
      migrations.set(
        filePath,
        analyzeMigration(filePath, content, fileIndexes.get(filePath)?.migrationFacts),
      );
    }
  } catch (cause) {
    errors.push(new IndexError("Failed to analyze migrations", { cause }));
  }
  return migrations;
}
