import { readFile } from "node:fs/promises";
import path from "node:path";
import pc from "picocolors";
import { stringify } from "yaml";
import { CACHE_SUBDIR, EXIT_CODES, POLICYGUARD_DIR } from "../../core/constants";
import type { Finding } from "../../core/types";
import type { JsonReport } from "../../reporting/json-reporter";
import { createDefaultRegistry } from "../../rules/rule-registry";
import { formatError, loadProjectSetup } from "../context";
import { findProjectRoot, type CliIo } from "../io";
import { LAST_REVIEW_FILE } from "./review";

export interface ExplainOptions {
  readonly cwd: string;
  readonly io: CliIo;
  readonly findingId: string;
  readonly configPath?: string;
}

/** How each built-in rule can be satisfied or justified. */
const RULE_GUIDANCE: Readonly<Record<string, string>> = {
  "new-route-requires-authorization":
    'Apply authorization middleware/guards, check authorization in the handler, or mark the route public:\n  // policyguard: public-route reason="health check"',
  "migration-requires-rollback":
    'Add a down()/rollback step, or document the risk:\n  -- policyguard: migration-justified reason="table unused since v2"',
  "no-direct-db-access-in-ui":
    "Move data access into a service module (default allowed path: src/services/**) and import that instead. Configure options.allowedModules / allowedImportPaths if needed.",
  "deleted-test-requires-justification":
    'Restore the test, or justify it in a commit message or next to the test:\n  // policyguard: test-change-justified reason="moved to e2e suite"',
  "protected-path-requires-review-annotation":
    "Add a CODEOWNERS entry for the path, or annotate the change:\n  # policyguard: reviewed-by <name>",
  "secret-detected-in-source":
    "Remove the secret, rotate it, and read it from the environment or a secret manager. Never store it in config files.",
  "dependency-without-lockfile-update":
    "Run your package manager's install command and commit the updated lockfile (pnpm-lock.yaml, package-lock.json, or yarn.lock).",
  "public-api-breaking-change":
    "Keep the old export (deprecate it), make the change additive, or bump the major version and document the migration.",
};

/** Looks up a finding by exact id or unique prefix. */
export function findFinding(
  findings: readonly Finding[],
  query: string,
): { finding?: Finding; candidates: readonly Finding[] } {
  const exact = findings.find((f) => f.id === query);
  if (exact) return { finding: exact, candidates: [exact] };
  const matches = findings.filter((f) => f.id.startsWith(query));
  return matches.length === 1
    ? { finding: matches[0] as Finding, candidates: matches }
    : { candidates: matches };
}

/** Runs `policyguard explain <finding-id>`. Returns the process exit code. */
export async function runExplain(options: ExplainOptions): Promise<number> {
  const { io } = options;
  const root = await findProjectRoot(options.cwd);
  const reportPath = path.join(root, POLICYGUARD_DIR, CACHE_SUBDIR, LAST_REVIEW_FILE);

  let report: JsonReport;
  try {
    report = JSON.parse(await readFile(reportPath, "utf8")) as JsonReport;
  } catch {
    io.err(
      pc.red("No review result found. Run `policyguard review` first, then explain a finding id."),
    );
    return EXIT_CODES.failure;
  }

  const { finding, candidates } = findFinding(report.findings, options.findingId);
  if (!finding) {
    io.err(
      pc.red(
        candidates.length > 1
          ? `"${options.findingId}" is ambiguous: ${candidates.map((f) => f.id).join(", ")}`
          : `No finding with id "${options.findingId}" in the last review.`,
      ),
    );
    if (candidates.length === 0 && report.findings.length > 0) {
      io.err(`Known ids: ${report.findings.map((f) => f.id).join(", ")}`);
    }
    return EXIT_CODES.failure;
  }

  const setup = await loadProjectSetup(root, options.configPath);
  for (const error of setup.errors) io.err(formatError(error));
  const policy = setup.policies?.policies.find((p) => p.id === finding.policyId);
  const rule = createDefaultRegistry().get(finding.ruleId);

  const lines: string[] = [];
  lines.push(pc.bold(`${finding.title}`), "");
  lines.push(`Finding:    ${finding.id}`);
  lines.push(`Severity:   ${finding.severity}`);
  lines.push(`Confidence: ${finding.confidence}`);
  lines.push(`Source:     ${finding.source}`);
  lines.push(
    `Location:   ${finding.file}${finding.startLine === undefined ? "" : `:${finding.startLine}${finding.endLine && finding.endLine !== finding.startLine ? `-${finding.endLine}` : ""}`}`,
  );
  lines.push(`Policy:     ${finding.policyId ?? "(none)"}`);
  lines.push(`Rule:       ${finding.ruleId}`, "");
  lines.push(finding.message, "");

  lines.push(pc.bold("Evidence:"));
  for (const evidence of finding.evidence) {
    const where = `${evidence.file}${evidence.startLine === undefined ? "" : `:${evidence.startLine}`}`;
    lines.push(`  - [${evidence.source}] ${evidence.explanation} (${where})`);
    if (evidence.snippet)
      for (const line of evidence.snippet.split("\n")) lines.push(`      > ${line}`);
  }
  lines.push("");

  if (rule) {
    lines.push(pc.bold("Rule documentation:"));
    lines.push(`  ${rule.title} (${rule.category}, default severity ${rule.defaultSeverity})`);
    lines.push(`  ${rule.description}`);
    const guidance = RULE_GUIDANCE[rule.id];
    if (guidance) lines.push("", ...guidance.split("\n").map((l) => `  ${l}`));
    lines.push("");
  }

  if (policy) {
    lines.push(pc.bold(`Policy definition (${policy.sourceFile}):`));
    const definition = Object.fromEntries(
      Object.entries(policy).filter(([key]) => key !== "sourceFile"),
    );
    lines.push(
      ...stringify(definition)
        .trimEnd()
        .split("\n")
        .map((l) => `  ${l}`),
      "",
    );
  }

  if (finding.remediation) {
    lines.push(
      pc.bold("Remediation:"),
      `  ${finding.remediation.trim().replace(/\n/g, "\n  ")}`,
      "",
    );
  }

  lines.push(
    pc.bold("Suppression options (a reason is always required and recorded in the report):"),
  );
  lines.push(
    `  1. Inline, on or above the line:  // policyguard-ignore ${finding.ruleId} reason="..."`,
  );
  lines.push(
    `  2. Configuration (.policyguard/policyguard.config.json):\n     "suppressions": [{ "ruleId": "${finding.ruleId}", "paths": ["${finding.file}"], "reason": "...", "author": "you", "expiresAt": "2027-01-01" }]`,
  );
  lines.push(
    `  3. Policy exception (${policy?.sourceFile ?? "policy YAML"}), under the policy:\n     suppressions:\n       - paths: ["${finding.file}"]\n         reason: "..."`,
  );
  if (finding.suppression) {
    lines.push(
      "",
      `Current suppression: ${finding.suppression.status}${finding.suppression.reason ? ` - ${finding.suppression.reason}` : ""}`,
    );
  }

  io.out(lines.join("\n"));
  return EXIT_CODES.ok;
}
