import { DiffParseError } from "../core/errors";
import type { ChangedFile, DiffFileStatus, DiffHunk, DiffLine } from "../core/types";
import { detectLanguage } from "../utils/path";

export interface ParsedDiff {
  readonly files: readonly ChangedFile[];
  /** Per-file parse failures. A failure never aborts the rest of the diff. */
  readonly errors: readonly DiffParseError[];
}

const HUNK_HEADER = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/;

/**
 * Parses `git diff --unified=N --no-color --find-renames` output into structured files.
 * Files that cannot be parsed are reported in `errors` and skipped.
 */
export function parseUnifiedDiff(diffText: string): ParsedDiff {
  const files: ChangedFile[] = [];
  const errors: DiffParseError[] = [];
  for (const section of splitSections(diffText)) {
    try {
      const file = parseSection(section);
      if (file) files.push(file);
    } catch (cause) {
      const header = section[0] ?? "";
      errors.push(
        new DiffParseError(`Could not parse diff section "${header.slice(0, 120)}"`, {
          cause,
          suggestion: "Report this diff shape as a PolicyGuard bug; the file was skipped.",
        }),
      );
    }
  }
  return { files, errors };
}

function splitSections(diffText: string): string[][] {
  const sections: string[][] = [];
  let current: string[] | undefined;
  for (const rawLine of diffText.split("\n")) {
    const line = rawLine.endsWith("\r") ? rawLine.slice(0, -1) : rawLine;
    if (line.startsWith("diff --git ")) {
      current = [line];
      sections.push(current);
    } else if (current) {
      current.push(line);
    }
  }
  return sections;
}

interface HeaderState {
  oldPath?: string;
  newPath?: string;
  renameFrom?: string;
  renameTo?: string;
  isNew: boolean;
  isDeleted: boolean;
  isBinary: boolean;
}

function parseSection(lines: readonly string[]): ChangedFile | undefined {
  const first = lines[0];
  if (first === undefined) return undefined;
  const state: HeaderState = { isNew: false, isDeleted: false, isBinary: false };

  let index = 1;
  for (; index < lines.length; index += 1) {
    const line = lines[index] as string;
    if (line.startsWith("@@")) break;
    readHeaderLine(line, state);
  }

  const hunks = parseHunks(lines, index);
  const fallback = splitGitHeader(first.slice("diff --git ".length));
  const oldPath = state.renameFrom ?? state.oldPath ?? fallback?.oldPath;
  const newPath = state.renameTo ?? state.newPath ?? fallback?.newPath;
  const pathValue = state.isDeleted ? oldPath : (newPath ?? oldPath);
  if (pathValue === undefined) throw new Error("no file path found in diff header");

  const renamed = state.renameFrom !== undefined && state.renameTo !== undefined;
  const status: DiffFileStatus = renamed
    ? "renamed"
    : state.isNew
      ? "added"
      : state.isDeleted
        ? "deleted"
        : "modified";
  const language = detectLanguage(pathValue);

  return {
    path: pathValue,
    ...(renamed && oldPath !== undefined ? { previousPath: oldPath } : {}),
    status,
    ...(language === undefined ? {} : { language }),
    isBinary: state.isBinary,
    hunks,
  };
}

function readHeaderLine(line: string, state: HeaderState): void {
  if (line.startsWith("new file mode")) state.isNew = true;
  else if (line.startsWith("deleted file mode")) state.isDeleted = true;
  else if (line.startsWith("rename from ")) state.renameFrom = unquote(line.slice(12));
  else if (line.startsWith("rename to ")) state.renameTo = unquote(line.slice(10));
  else if (line.startsWith("Binary files ") || line.startsWith("GIT binary patch")) {
    state.isBinary = true;
    const match = /^Binary files (.+) and (.+) differ$/.exec(line);
    if (match) {
      const from = stripPrefix(unquote(match[1] as string), "a/");
      const to = stripPrefix(unquote(match[2] as string), "b/");
      if (from !== "/dev/null") state.oldPath = from;
      if (to !== "/dev/null") state.newPath = to;
    }
  } else if (line.startsWith("--- ")) {
    const value = unquote(line.slice(4));
    if (value !== "/dev/null") state.oldPath = stripPrefix(value, "a/");
  } else if (line.startsWith("+++ ")) {
    const value = unquote(line.slice(4));
    if (value !== "/dev/null") state.newPath = stripPrefix(value, "b/");
  }
}

function parseHunks(lines: readonly string[], startIndex: number): DiffHunk[] {
  const hunks: DiffHunk[] = [];
  let index = startIndex;
  while (index < lines.length) {
    const header = HUNK_HEADER.exec(lines[index] as string);
    if (!header) {
      index += 1;
      continue;
    }
    const oldStart = Number(header[1]);
    const oldLines = header[2] === undefined ? 1 : Number(header[2]);
    const newStart = Number(header[3]);
    const newLines = header[4] === undefined ? 1 : Number(header[4]);
    index += 1;

    const hunkLines: DiffLine[] = [];
    let oldCursor = oldStart;
    let newCursor = newStart;
    let oldSeen = 0;
    let newSeen = 0;

    while (index < lines.length && (oldSeen < oldLines || newSeen < newLines)) {
      const line = lines[index] as string;
      const marker = line[0];
      const content = line.slice(1);
      if (marker === "+") {
        hunkLines.push({ type: "added", newLineNumber: newCursor, content });
        newCursor += 1;
        newSeen += 1;
      } else if (marker === "-") {
        hunkLines.push({ type: "removed", oldLineNumber: oldCursor, content });
        oldCursor += 1;
        oldSeen += 1;
      } else if (marker === " " || line === "") {
        hunkLines.push({
          type: "context",
          oldLineNumber: oldCursor,
          newLineNumber: newCursor,
          content,
        });
        oldCursor += 1;
        newCursor += 1;
        oldSeen += 1;
        newSeen += 1;
      } else if (marker === "\\") {
        // "\ No newline at end of file" carries no line of its own.
      } else {
        break;
      }
      index += 1;
    }
    // Consume a trailing "\ No newline at end of file" marker.
    while (index < lines.length && (lines[index] as string).startsWith("\\")) index += 1;

    hunks.push({ oldStart, oldLines, newStart, newLines, lines: hunkLines });
  }
  return hunks;
}

function stripPrefix(value: string, prefix: string): string {
  return value.startsWith(prefix) ? value.slice(prefix.length) : value;
}

/** Removes Git's C-style quoting (`"a\tb"`, octal escapes) from a path, if present. */
export function unquote(value: string): string {
  const trimmed = value.replace(/\t.*$/, "");
  if (!(trimmed.startsWith('"') && trimmed.endsWith('"') && trimmed.length >= 2)) return trimmed;
  const inner = trimmed.slice(1, -1);
  const bytes: number[] = [];
  for (let i = 0; i < inner.length; i += 1) {
    const char = inner[i] as string;
    if (char !== "\\") {
      bytes.push(...Buffer.from(char, "utf8"));
      continue;
    }
    const next = inner[i + 1] as string;
    const octal = /^[0-7]{3}/.exec(inner.slice(i + 1));
    if (octal) {
      bytes.push(parseInt(octal[0], 8));
      i += 3;
      continue;
    }
    const simple: Record<string, number> = {
      n: 10,
      t: 9,
      r: 13,
      '"': 34,
      "\\": 92,
      a: 7,
      b: 8,
      f: 12,
      v: 11,
    };
    bytes.push(simple[next] ?? next.charCodeAt(0));
    i += 1;
  }
  return Buffer.from(bytes).toString("utf8");
}

/** Splits the remainder of a `diff --git a/x b/y` line into old/new paths, if unambiguous. */
function splitGitHeader(rest: string): { oldPath: string; newPath: string } | undefined {
  if (rest.startsWith('"')) {
    const match = /^("(?:[^"\\]|\\.)*") ("(?:[^"\\]|\\.)*"|\S.*)$/.exec(rest);
    if (match) {
      return {
        oldPath: stripPrefix(unquote(match[1] as string), "a/"),
        newPath: stripPrefix(unquote(match[2] as string), "b/"),
      };
    }
    return undefined;
  }
  // Same path on both sides: "a/<p> b/<p>".
  const half = (rest.length - 3) / 2;
  if (Number.isInteger(half) && half > 0) {
    const left = rest.slice(0, half + 2);
    const right = rest.slice(half + 3);
    if (left.startsWith("a/") && right.startsWith("b/") && left.slice(2) === right.slice(2)) {
      return { oldPath: left.slice(2), newPath: right.slice(2) };
    }
  }
  const match = /^a\/(\S+) b\/(\S+)$/.exec(rest);
  return match ? { oldPath: match[1] as string, newPath: match[2] as string } : undefined;
}
