import pc from "picocolors";

export type LogLevel = "silent" | "error" | "warn" | "info" | "debug";

/** Minimal leveled logger. Writes to stderr so stdout stays machine-readable. */
export interface Logger {
  error(message: string): void;
  warn(message: string): void;
  info(message: string): void;
  debug(message: string): void;
}

const LEVEL_ORDER: Record<LogLevel, number> = {
  silent: 0,
  error: 1,
  warn: 2,
  info: 3,
  debug: 4,
};

export interface LoggerOptions {
  readonly level?: LogLevel;
  readonly write?: (line: string) => void;
}

/** Creates a logger that filters by level and writes through `options.write`. */
export function createLogger(options: LoggerOptions = {}): Logger {
  const threshold = LEVEL_ORDER[options.level ?? "info"];
  const write = options.write ?? ((line: string) => process.stderr.write(`${line}\n`));
  const emit = (level: Exclude<LogLevel, "silent">, label: string, message: string): void => {
    if (LEVEL_ORDER[level] <= threshold) write(`${label} ${message}`);
  };
  return {
    error: (message) => emit("error", pc.red("error:"), message),
    warn: (message) => emit("warn", pc.yellow("warn:"), message),
    info: (message) => emit("info", pc.cyan("info:"), message),
    debug: (message) => emit("debug", pc.gray("debug:"), message),
  };
}

/** Logger that discards everything. */
export const silentLogger: Logger = createLogger({ level: "silent" });
