import { execFile } from "node:child_process";
import { simpleGit } from "simple-git";
import { GitError } from "../core/errors";
import { err, ok, type Result } from "../core/result";
import { parseUnifiedDiff, type ParsedDiff } from "./diff-parser";

/** Runs a Git command in `cwd` and returns stdout. Throws on failure. */
export type GitExecutor = (args: readonly string[], cwd: string) => Promise<string>;

const MAX_BUFFER_BYTES = 512 * 1024 * 1024;

function execGitDirect(args: readonly string[], cwd: string): Promise<string> {
  return new Promise((resolve, reject) => {
    execFile(
      "git",
      ["-c", "core.quotepath=false", ...args],
      { cwd, maxBuffer: MAX_BUFFER_BYTES, windowsHide: true, encoding: "utf8" },
      (error, stdout, stderr) => {
        if (error) reject(new Error(stderr.trim() || error.message));
        else resolve(stdout);
      },
    );
  });
}

/**
 * Default executor: simple-git first, then a direct Git CLI call. The fallback
 * covers simple-git argument restrictions and surfaces the raw Git stderr.
 */
export function createDefaultExecutor(): GitExecutor {
  return async (args, cwd) => {
    try {
      const git = simpleGit({ baseDir: cwd, config: ["core.quotepath=false"] });
      return await git.raw([...args]);
    } catch {
      return execGitDirect(args, cwd);
    }
  };
}

/** A resolved ref: the symbolic name given and the commit it points to. */
export interface ResolvedRef {
  readonly name: string;
  readonly sha: string;
}

/** Result of reading a diff from Git. */
export interface DiffResult extends ParsedDiff {
  readonly baseRef: ResolvedRef;
  readonly headRef: ResolvedRef;
  /** Merge base of base and head; the commit the diff is relative to. */
  readonly mergeBase: string;
  readonly rawDiff: string;
}

/** Thin, testable wrapper over the Git CLI. */
export class GitClient {
  private constructor(
    readonly repositoryPath: string,
    private readonly exec: GitExecutor,
  ) {}

  /**
   * Opens the repository containing `cwd`.
   * Fails with `not-a-repository` when `cwd` is not inside a Git work tree.
   */
  static async open(
    cwd: string,
    exec: GitExecutor = createDefaultExecutor(),
  ): Promise<Result<GitClient, GitError>> {
    try {
      const top = (await exec(["rev-parse", "--show-toplevel"], cwd)).trim();
      if (!top) throw new Error("empty toplevel");
      return ok(new GitClient(top, exec));
    } catch (cause) {
      return err(
        new GitError("not-a-repository", `Not inside a Git repository: ${cwd}`, {
          cause,
          suggestion: "Run PolicyGuard from within a Git repository (try `git init`).",
        }),
      );
    }
  }

  /** Resolves `ref` to a commit SHA, or undefined when it does not exist. */
  async resolveRef(ref: string): Promise<string | undefined> {
    if (ref.startsWith("-")) return undefined;
    try {
      const out = await this.exec(
        ["rev-parse", "--verify", "--quiet", `${ref}^{commit}`],
        this.repositoryPath,
      );
      const sha = out.trim();
      return sha || undefined;
    } catch {
      return undefined;
    }
  }

  /** Merge base of two commits. Falls back to `base` when none exists (unrelated histories). */
  async mergeBase(base: string, head: string): Promise<string> {
    try {
      const out = await this.run(["merge-base", base, head]);
      return out.trim() || base;
    } catch {
      return base;
    }
  }

  /** Raw unified diff `base...head`. */
  async rawDiff(base: string, head: string): Promise<string> {
    return this.run([
      "diff",
      "--unified=3",
      "--no-color",
      "--no-ext-diff",
      "--find-renames",
      "--src-prefix=a/",
      "--dst-prefix=b/",
      `${base}...${head}`,
    ]);
  }

  /** Commit message bodies for commits reachable from head but not base. */
  async commitMessages(base: string, head: string): Promise<string[]> {
    try {
      const out = await this.run(["log", "--format=%B%x00", `${base}..${head}`]);
      return out
        .split("\0")
        .map((message) => message.trim())
        .filter((message) => message.length > 0);
    } catch {
      return [];
    }
  }

  /** Lists file paths in the tree of `commit`. */
  async listFiles(commit: string): Promise<string[]> {
    const out = await this.run(["ls-tree", "-r", "--name-only", commit]);
    return out.split("\n").filter((line) => line.length > 0);
  }

  /** Runs a Git command and wraps failures in a {@link GitError}. */
  async run(args: readonly string[]): Promise<string> {
    try {
      return await this.exec(args, this.repositoryPath);
    } catch (cause) {
      const detail = cause instanceof Error ? cause.message : String(cause);
      throw new GitError("git-failure", `git ${args.slice(0, 2).join(" ")} failed: ${detail}`, {
        cause,
      });
    }
  }

  /** Reads and parses the diff between two resolved refs. */
  async readDiff(base: ResolvedRef, head: ResolvedRef): Promise<DiffResult> {
    const [rawDiff, mergeBase] = await Promise.all([
      this.rawDiff(base.sha, head.sha),
      this.mergeBase(base.sha, head.sha),
    ]);
    const parsed = parseUnifiedDiff(rawDiff);
    return { ...parsed, baseRef: base, headRef: head, mergeBase, rawDiff };
  }
}
