import { existsSync } from "node:fs";
import { copyFile, mkdir, readFile, readdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import {
  CONFIG_FILE_NAME,
  EXIT_CODES,
  POLICIES_SUBDIR,
  POLICYGUARD_DIR,
} from "../../core/constants";
import { findProjectRoot, type CliIo } from "../io";

export interface InitOptions {
  readonly cwd: string;
  readonly force: boolean;
  readonly io: CliIo;
}

interface PackageJsonShape {
  readonly dependencies?: Record<string, string>;
  readonly devDependencies?: Record<string, string>;
  readonly packageManager?: string;
}

/** Locates the installed package root (the directory holding `policies/default`). */
export function findPackageRoot(
  startDir: string = path.dirname(fileURLToPath(import.meta.url)),
): string {
  let dir = startDir;
  for (;;) {
    if (existsSync(path.join(dir, "policies", "default"))) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) throw new Error("Cannot locate PolicyGuard default policies.");
    dir = parent;
  }
}

/** Creates `.policyguard/` with starter policies and configuration. Returns the exit code. */
export async function runInit(options: InitOptions): Promise<number> {
  const { io } = options;
  const root = await findProjectRoot(options.cwd);
  const policiesDir = path.join(root, POLICYGUARD_DIR, POLICIES_SUBDIR);
  await mkdir(policiesDir, { recursive: true });

  const created: string[] = [];
  const skipped: string[] = [];

  const templateDir = path.join(findPackageRoot(), "policies", "default");
  for (const name of (await readdir(templateDir)).filter((n) => n.endsWith(".yaml")).sort()) {
    const target = path.join(policiesDir, name);
    const label = path.posix.join(POLICYGUARD_DIR, POLICIES_SUBDIR, name);
    if (existsSync(target) && !options.force) {
      skipped.push(label);
      continue;
    }
    await copyFile(path.join(templateDir, name), target);
    created.push(label);
  }

  const configTarget = path.join(root, POLICYGUARD_DIR, CONFIG_FILE_NAME);
  const configLabel = path.posix.join(POLICYGUARD_DIR, CONFIG_FILE_NAME);
  if (existsSync(configTarget) && !options.force) {
    skipped.push(configLabel);
  } else {
    await writeFile(configTarget, `${JSON.stringify(await buildStarterConfig(root), null, 2)}\n`);
    created.push(configLabel);
  }

  for (const file of created) io.out(`created  ${file}`);
  for (const file of skipped) io.out(`skipped  ${file} (already exists; use --force to overwrite)`);
  io.out("\nNext: run `policyguard validate`, then `policyguard review --base origin/main`.");
  return EXIT_CODES.ok;
}

async function readPackageJson(root: string): Promise<PackageJsonShape | undefined> {
  try {
    return JSON.parse(await readFile(path.join(root, "package.json"), "utf8")) as PackageJsonShape;
  } catch {
    return undefined;
  }
}

/** Builds starter configuration tailored to the detected project type. */
export async function buildStarterConfig(root: string): Promise<Record<string, unknown>> {
  const pkg = await readPackageJson(root);
  const deps = { ...pkg?.dependencies, ...pkg?.devDependencies };

  const packageManager = existsSync(path.join(root, "pnpm-lock.yaml"))
    ? "pnpm"
    : existsSync(path.join(root, "yarn.lock"))
      ? "yarn"
      : existsSync(path.join(root, "package-lock.json"))
        ? "npm"
        : pkg?.packageManager?.split("@")[0];

  const api = ["src/routes/**", "src/api/**"];
  if ("@nestjs/core" in deps) api.push("src/**/*.controller.ts");

  return {
    version: 1,
    project: {
      languages: ["typescript"],
      ...(packageManager === "pnpm" || packageManager === "npm" || packageManager === "yarn"
        ? { packageManager }
        : {}),
    },
    review: {
      defaultBase: "origin/main",
      ai: {
        enabled: false,
        provider: "openai-compatible",
        model: "gpt-4.1-mini",
        maxFilesPerRequest: 10,
        redactSecrets: true,
      },
    },
    paths: {
      ui: ["src/app/**", "src/components/**", "src/pages/**", "src/ui/**"],
      api,
      migrations: ["migrations/**", "database/migrations/**", "src/migrations/**"],
      protected: [".github/workflows/**", "infra/**", "src/auth/**", "src/crypto/**"],
    },
    reporting: { format: "terminal", failOn: "error" },
  };
}
