import { TOOL_NAME, TOOL_VERSION } from "../core/constants";
import type { Evidence, Finding, Severity } from "../core/types";
import { isSuppressed } from "../policies/suppression";
import type { ReviewOutcome } from "../review/review-engine";
import { createDefaultRegistry, type RuleRegistry } from "../rules/rule-registry";

const SARIF_SCHEMA = "https://json.schemastore.org/sarif-2.1.0.json";

type SarifLevel = "error" | "warning" | "note";

/** SARIF `level` for a PolicyGuard severity. `critical` and `error` both map to `error`. */
export function sarifLevel(severity: Severity): SarifLevel {
  switch (severity) {
    case "critical":
    case "error":
      return "error";
    case "warning":
      return "warning";
    default:
      return "note";
  }
}

interface SarifRegion {
  startLine: number;
  endLine?: number;
  snippet?: { text: string };
}

function region(
  startLine: number | undefined,
  endLine: number | undefined,
  snippet?: string,
): SarifRegion {
  const start = Math.max(1, startLine ?? 1);
  return {
    startLine: start,
    ...(endLine !== undefined && endLine >= start ? { endLine } : {}),
    ...(snippet ? { snippet: { text: snippet } } : {}),
  };
}

function location(
  file: string,
  reg: SarifRegion,
  message?: string,
  id?: number,
): Record<string, unknown> {
  return {
    ...(id === undefined ? {} : { id }),
    physicalLocation: {
      artifactLocation: { uri: file, uriBaseId: "%SRCROOT%" },
      region: reg,
    },
    ...(message === undefined ? {} : { message: { text: message } }),
  };
}

function sarifResult(finding: Finding, ruleIndex: number): Record<string, unknown> {
  const primarySnippet = finding.evidence.find(
    (e) => e.file === finding.file && e.snippet !== undefined,
  )?.snippet;
  return {
    ruleId: finding.ruleId,
    ruleIndex,
    level: sarifLevel(finding.severity),
    message: { text: finding.message },
    locations: [location(finding.file, region(finding.startLine, finding.endLine, primarySnippet))],
    relatedLocations: finding.evidence.map((e: Evidence, index) =>
      location(e.file, region(e.startLine, e.endLine, e.snippet), e.explanation, index),
    ),
    partialFingerprints: { "policyguardFindingId/v1": finding.id },
    ...(isSuppressed(finding)
      ? {
          suppressions: [
            {
              kind: "inSource",
              status: "accepted",
              justification: finding.suppression?.reason ?? "",
            },
          ],
        }
      : {}),
    properties: {
      policyguardSeverity: finding.severity,
      confidence: finding.confidence,
      source: finding.source,
      ...(finding.policyId ? { policyId: finding.policyId } : {}),
      title: finding.title,
      ...(finding.remediation ? { remediation: finding.remediation } : {}),
    },
  };
}

/**
 * Builds a SARIF 2.1.0 log. Supported subset: tool.driver.rules, results with
 * physical locations, evidence as relatedLocations, partialFingerprints, and in-source
 * suppressions. See docs/architecture.md for what is intentionally omitted.
 */
export function buildSarifReport(
  outcome: ReviewOutcome,
  registry: RuleRegistry = createDefaultRegistry(),
): Record<string, unknown> {
  const { result } = outcome;
  const ruleIds = [...new Set(result.findings.map((f) => f.ruleId))].sort();
  const ruleIndex = new Map(ruleIds.map((id, index) => [id, index]));

  const rules = ruleIds.map((id) => {
    const rule = registry.get(id);
    return {
      id,
      name: rule?.title ?? id,
      shortDescription: { text: rule?.title ?? id },
      ...(rule ? { fullDescription: { text: rule.description } } : {}),
      defaultConfiguration: { level: sarifLevel(rule?.defaultSeverity ?? "warning") },
      properties: { category: rule?.category ?? "custom" },
    };
  });

  return {
    $schema: SARIF_SCHEMA,
    version: "2.1.0",
    runs: [
      {
        tool: { driver: { name: TOOL_NAME, version: TOOL_VERSION, rules } },
        invocations: [
          {
            executionSuccessful: result.errors.length === 0,
            startTimeUtc: result.startedAt,
            endTimeUtc: result.completedAt,
            toolExecutionNotifications: result.errors.map((error) => ({
              level: "warning",
              message: { text: error.message },
              ...(error.file
                ? { locations: [{ physicalLocation: { artifactLocation: { uri: error.file } } }] }
                : {}),
            })),
          },
        ],
        results: result.findings.map((finding) =>
          sarifResult(finding, ruleIndex.get(finding.ruleId) ?? 0),
        ),
      },
    ],
  };
}

export function renderSarifReport(outcome: ReviewOutcome, registry?: RuleRegistry): string {
  return `${JSON.stringify(buildSarifReport(outcome, registry), null, 2)}\n`;
}
