/** Semantic index data structures. Everything here is plain JSON so it can be cached on disk. */

/** Bump when the shape or extraction logic changes; invalidates cached entries. */
export const INDEXER_VERSION = 1;

export interface ImportBinding {
  /** Name in the importing file. */
  readonly local: string;
  /** Exported name in the source module ("default" for default imports, "*" for namespaces). */
  readonly imported: string;
}

export interface ImportInfo {
  readonly moduleSpecifier: string;
  readonly kind: "import" | "require" | "dynamic-import" | "export-from";
  readonly bindings: readonly ImportBinding[];
  readonly isTypeOnly: boolean;
  readonly line: number;
}

export interface ParameterInfo {
  readonly name: string;
  readonly type?: string;
  readonly optional: boolean;
  readonly rest: boolean;
}

export interface PropertyInfo {
  readonly name: string;
  readonly optional: boolean;
  readonly readonly: boolean;
  readonly type?: string;
}

export interface ClassMemberInfo {
  readonly name: string;
  readonly kind: "method" | "property" | "constructor" | "accessor";
  readonly isStatic: boolean;
  readonly parameters?: readonly ParameterInfo[];
}

export type ExportDetail =
  | {
      readonly kind: "function";
      readonly parameters: readonly ParameterInfo[];
      readonly returnType?: string;
    }
  | { readonly kind: "class"; readonly members: readonly ClassMemberInfo[] }
  | {
      readonly kind: "interface";
      readonly properties: readonly PropertyInfo[];
      readonly extends: readonly string[];
    }
  | { readonly kind: "type"; readonly text: string }
  | { readonly kind: "enum"; readonly members: readonly string[] }
  | { readonly kind: "variable"; readonly type?: string }
  | { readonly kind: "reexport"; readonly from: string; readonly imported: string }
  | { readonly kind: "star-reexport"; readonly from: string }
  | { readonly kind: "unknown" };

export interface ExportInfo {
  /** Exported name; "default" for default exports. */
  readonly name: string;
  readonly line: number;
  readonly detail: ExportDetail;
}

export type SymbolKind =
  "function" | "class" | "method" | "interface" | "type" | "enum" | "variable";

export interface SymbolInfo {
  readonly name: string;
  readonly kind: SymbolKind;
  readonly exported: boolean;
  readonly startLine: number;
  readonly endLine: number;
}

export type HttpMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE" | "ALL" | "HEAD" | "OPTIONS";

export interface RouteDefinition {
  readonly framework: "express" | "fastify" | "nest";
  readonly method: HttpMethod;
  /** Literal route path, or "<dynamic>" when it cannot be determined statically. */
  readonly path: string;
  readonly file: string;
  readonly line: number;
  readonly endLine: number;
  /** Identifier the route is registered on (e.g. `app`, `router`); express/fastify only. */
  readonly receiver?: string;
  /** Texts of middleware/preHandler/guard expressions attached directly to this route. */
  readonly middleware: readonly string[];
  /** NestJS decorators on the method and its controller class (decorator text without `@`). */
  readonly decorators: readonly string[];
  /** Handler source, truncated; used to detect explicit authorization checks. */
  readonly handlerSource?: string;
}

export interface MiddlewareUsage {
  /** Receiver the middleware is attached to (`app`, `router`, `fastify`). */
  readonly receiver: string;
  /** `use` for express-style mounting, `hook` for fastify hooks. */
  readonly kind: "use" | "hook";
  readonly path?: string;
  readonly args: readonly string[];
  readonly line: number;
}

export type TestModifier = "none" | "skip" | "todo" | "only" | "fixme";

export interface TestCase {
  readonly kind: "test" | "suite";
  readonly name: string;
  /** Names of enclosing suites joined with " > ", ending with this test. */
  readonly fullName: string;
  readonly modifier: TestModifier;
  readonly framework: "vitest-jest-mocha";
  readonly line: number;
  readonly endLine: number;
  /** Test body source, truncated; used to look for authorization assertions. */
  readonly source?: string;
}

export type MigrationKind = "sql" | "knex" | "typeorm" | "sequelize" | "prisma" | "unknown";

export interface DestructiveStatement {
  readonly operation: string;
  readonly line: number;
  readonly text: string;
}

export interface MigrationInfo {
  readonly path: string;
  readonly kind: MigrationKind;
  /** True when a down/rollback step (or a reversible `change`) was found. */
  readonly hasRollback: boolean;
  /** Prisma and plain `.up.sql` style migrations are forward-only by convention. */
  readonly forwardOnlyByConvention: boolean;
  readonly destructive: readonly DestructiveStatement[];
}

export interface MigrationFacts {
  /** A `down` function/method/property exists. */
  readonly hasDown: boolean;
  /** A reversible `change` function exists (Rails/Phinx style). */
  readonly hasChange: boolean;
  /** 1-based inclusive line range of the down body, excluded when scanning for destructive operations. */
  readonly downRange?: readonly [number, number];
}

export interface FileIndex {
  readonly path: string;
  readonly hash: string;
  readonly language: "typescript" | "javascript";
  /** False when extraction failed; the index is then partial. */
  readonly extractionOk: boolean;
  /** Number of syntax errors the parser recovered from. */
  readonly syntaxErrors: number;
  readonly imports: readonly ImportInfo[];
  readonly exports: readonly ExportInfo[];
  readonly symbols: readonly SymbolInfo[];
  readonly routes: readonly RouteDefinition[];
  readonly middlewareUsages: readonly MiddlewareUsage[];
  readonly tests: readonly TestCase[];
  /** Coarse text markers, e.g. "APP_GUARD", used by rules for global-config detection. */
  readonly markers: readonly string[];
  /** Facts used by the migration analyzer. */
  readonly migrationFacts: MigrationFacts;
}

export type FileKind =
  "source" | "test" | "migration" | "manifest" | "lockfile" | "config" | "ci" | "docs" | "other";

export interface FileEntry {
  readonly path: string;
  readonly kind: FileKind;
  /** Matches protected-path configuration or sensitive-name heuristics. */
  readonly sensitive: boolean;
}

export interface PackageManifest {
  readonly path: string;
  readonly name?: string;
  readonly dependencies: Readonly<Record<string, string>>;
  readonly devDependencies: Readonly<Record<string, string>>;
  readonly peerDependencies: Readonly<Record<string, string>>;
  readonly optionalDependencies: Readonly<Record<string, string>>;
}
