import path from "node:path";
import { z } from "zod";
import type { Evidence, Finding } from "../../core/types";
import { parsePackageManifest } from "../../indexing/file-indexer";
import type { PackageManifest } from "../../indexing/types";
import { policiesForRule } from "../../policies/policy-context";
import type { RuleContext } from "../rule-context";
import type { PolicyRuleImplementation, RuleResult } from "../rule-result";
import { addedLines, createFinding, filesInScope, parseOptions } from "../rule-utils";

const RULE_ID = "dependency-without-lockfile-update";

const optionsSchema = z
  .object({
    lockfiles: z.array(z.string()).default(["pnpm-lock.yaml", "package-lock.json", "yarn.lock"]),
  })
  .strict();

type Section = "dependencies" | "devDependencies" | "peerDependencies" | "optionalDependencies";
const SECTIONS: readonly Section[] = [
  "dependencies",
  "devDependencies",
  "peerDependencies",
  "optionalDependencies",
];

export interface DependencyChange {
  readonly name: string;
  readonly section: Section;
  readonly before?: string;
  readonly after?: string;
}

/** Differences between two manifests' dependency sections. */
export function diffDependencies(
  before: PackageManifest | undefined,
  after: PackageManifest,
): DependencyChange[] {
  const changes: DependencyChange[] = [];
  for (const section of SECTIONS) {
    const oldDeps = before?.[section] ?? {};
    const newDeps = after[section];
    for (const [name, version] of Object.entries(newDeps)) {
      if (oldDeps[name] !== version) {
        changes.push({
          name,
          section,
          ...(oldDeps[name] === undefined ? {} : { before: oldDeps[name] }),
          after: version,
        });
      }
    }
    for (const [name, version] of Object.entries(oldDeps)) {
      if (!(name in newDeps)) changes.push({ name, section, before: version });
    }
  }
  return changes;
}

function describeChange(change: DependencyChange): string {
  if (change.before === undefined)
    return `added ${change.name}@${change.after} (${change.section})`;
  if (change.after === undefined) return `removed ${change.name} (${change.section})`;
  return `changed ${change.name} ${change.before} -> ${change.after} (${change.section})`;
}

/** Directories from the manifest's directory up to the repository root. */
function ancestorDirs(manifestPath: string): string[] {
  const dirs: string[] = [];
  let dir = path.posix.dirname(manifestPath);
  for (;;) {
    dirs.push(dir === "." ? "" : dir);
    if (dir === "." || dir === "/" || dir === "") break;
    dir = path.posix.dirname(dir);
  }
  return dirs;
}

const join = (dir: string, name: string): string => (dir === "" ? name : `${dir}/${name}`);

export const dependencyWithoutLockfileUpdate: PolicyRuleImplementation = {
  id: RULE_ID,
  title: "Dependency changed without lockfile update",
  description: "Dependency changes in package.json must be accompanied by a lockfile update.",
  category: "security",
  defaultSeverity: "error",
  supportedLanguages: ["any"],

  async run(context: RuleContext): Promise<RuleResult> {
    const findings: Finding[] = [];
    const changedPaths = new Set(context.changedFiles.map((f) => f.path));

    for (const policy of policiesForRule(context.policies, RULE_ID)) {
      const options = parseOptions(policy, optionsSchema);
      const files = filesInScope(context, policy, undefined, {
        statuses: ["added", "modified", "renamed"],
      }).filter((f) => path.posix.basename(f.path) === "package.json");

      for (const file of files) {
        const headContent = await context.headReader.readFile(file.path);
        if (headContent === undefined) continue;
        const after = parsePackageManifest(file.path, headContent);
        if (!after) continue;
        const baseContent =
          file.status === "added"
            ? undefined
            : await context.baseReader.readFile(file.previousPath ?? file.path);
        const before =
          baseContent === undefined ? undefined : parsePackageManifest(file.path, baseContent);
        const changes = diffDependencies(before, after);
        if (changes.length === 0) continue;

        const candidates = ancestorDirs(file.path).flatMap((dir) =>
          options.lockfiles.map((name) => join(dir, name)),
        );
        const updated = candidates.find((candidate) => changedPaths.has(candidate));
        if (updated) continue;
        const existing = candidates.filter((candidate) =>
          context.indexedRepository.hasFile(candidate),
        );

        const added = addedLines(file);
        const evidence: Evidence[] = changes.slice(0, 5).map((change) => {
          const line = added.find((l) => l.content.includes(`"${change.name}"`));
          return {
            file: file.path,
            ...(line
              ? { startLine: line.line, endLine: line.line, snippet: line.content.trim() }
              : {}),
            explanation: `Dependency ${describeChange(change)}`,
            source: "diff" as const,
          };
        });
        if (changes.length > 5) {
          evidence.push({
            file: file.path,
            explanation: `${changes.length - 5} more dependency change(s)`,
            source: "diff",
          });
        }
        evidence.push({
          file: existing[0] ?? file.path,
          explanation:
            existing.length > 0
              ? `Lockfile ${existing.join(", ")} was not updated in this diff`
              : `No lockfile (${options.lockfiles.join(", ")}) exists next to or above ${file.path}`,
          source: "repository",
        });

        const firstLine = evidence.find((e) => e.startLine !== undefined)?.startLine;
        findings.push(
          createFinding({
            ruleId: RULE_ID,
            policy,
            title: "Dependencies changed without a lockfile update",
            message: `${file.path} changes ${changes.length} dependenc${changes.length === 1 ? "y" : "ies"} but no lockfile was updated.`,
            file: file.path,
            ...(firstLine === undefined ? {} : { startLine: firstLine }),
            evidence,
            confidence: "high",
            key: file.path,
            remediation:
              policy.remediation?.trim() ??
              "Run your package manager's install command and commit the updated lockfile.",
          }),
        );
      }
    }
    return { findings, errors: [] };
  },
};
