import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import pc from "picocolors";
import { createAiStage } from "../../ai/ai-stage";
import { EXIT_CODES } from "../../core/constants";
import { createLogger } from "../../core/logger";
import type { OutputFormat, ReviewOptions } from "../../core/types";
import { renderStepSummary, toAnnotations } from "../../reporting/github-annotations";
import { renderJsonReport } from "../../reporting/json-reporter";
import { renderSarifReport } from "../../reporting/sarif-reporter";
import { renderTerminalReport } from "../../reporting/terminal-reporter";
import {
  ensureCacheDir,
  runReview,
  type ReviewInput,
  type ReviewOutcome,
} from "../../review/review-engine";
import { formatError } from "../context";
import type { CliIo } from "../io";

/** File (inside `.policyguard/cache/`) holding the last review, read by `explain`. */
export const LAST_REVIEW_FILE = "last-review.json";

export interface ReviewCommandOptions {
  readonly cwd: string;
  readonly io: CliIo;
  readonly options: ReviewOptions;
  /** Print GitHub Actions annotations. Defaults to `env.GITHUB_ACTIONS === "true"`. */
  readonly githubAnnotations?: boolean;
  readonly color?: boolean;
  readonly useCache?: boolean;
  readonly verbose?: boolean;
  readonly env?: NodeJS.ProcessEnv;
  /** Extension point for the optional AI stage. */
  readonly extraFindings?: ReviewInput["extraFindings"];
  /** Appends to the step summary file; injectable for tests. */
  readonly appendFile?: (file: string, text: string) => Promise<void>;
}

/** Renders the report for `format`. */
export function renderReport(outcome: ReviewOutcome, format: OutputFormat, color: boolean): string {
  switch (format) {
    case "json":
      return renderJsonReport(outcome);
    case "sarif":
      return renderSarifReport(outcome);
    default:
      return renderTerminalReport(outcome, { color });
  }
}

/** Exit code for a finished review: 0 pass, 1 blocking findings, 2 strict-mode analysis errors. */
export function exitCodeFor(outcome: ReviewOutcome): number {
  if (outcome.blocking.length > 0) return EXIT_CODES.blockingFindings;
  if (outcome.strict && outcome.result.errors.length > 0) return EXIT_CODES.failure;
  return EXIT_CODES.ok;
}

/** Runs `policyguard review`. Returns the process exit code. */
export async function runReviewCommand(command: ReviewCommandOptions): Promise<number> {
  const { io, options } = command;
  const env = command.env ?? process.env;
  const logger = createLogger({
    level: command.verbose ? "debug" : "warn",
    write: (line) => io.err(line),
  });

  const reviewed = await runReview({
    cwd: command.cwd,
    options,
    logger,
    ...(command.useCache === undefined ? {} : { useCache: command.useCache }),
    extraFindings: command.extraFindings ?? createAiStage({ env }),
  });
  if (!reviewed.ok) {
    io.err(
      pc.red(`PolicyGuard could not complete the review (${reviewed.error.length} problem(s)):`),
    );
    for (const error of reviewed.error) io.err(formatError(error));
    return EXIT_CODES.failure;
  }
  const outcome = reviewed.value;

  const format = options.format ?? outcome.config.reporting.format;
  const writesFile = options.outputPath !== undefined;
  const color = !writesFile && (command.color ?? pc.isColorSupported);
  const report = renderReport(outcome, format, color);

  if (options.outputPath !== undefined) {
    const target = path.resolve(command.cwd, options.outputPath);
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, report);
    io.err(`PolicyGuard report (${format}) written to ${target}`);
  } else {
    io.out(report.replace(/\n$/, ""));
  }

  const annotate = command.githubAnnotations ?? env["GITHUB_ACTIONS"] === "true";
  if (annotate) {
    // Keep stdout clean when it carries a machine-readable report.
    const sink = !writesFile && format !== "terminal" ? io.err : io.out;
    for (const line of toAnnotations(outcome)) sink(line);
  }
  const summaryFile = env["GITHUB_STEP_SUMMARY"];
  if (summaryFile) {
    const { appendFile } = await import("node:fs/promises");
    await (command.appendFile ?? appendFile)(summaryFile, renderStepSummary(outcome)).catch(
      () => undefined,
    );
  }

  await saveLastReview(outcome);
  const aiFailed =
    options.ai === true && outcome.result.errors.some((e) => e.code.startsWith("llm-"));
  const code = exitCodeFor(outcome);
  return code === EXIT_CODES.ok && aiFailed ? EXIT_CODES.failure : code;
}

/** Persists the JSON report so `policyguard explain <id>` can look findings up. Best effort. */
export async function saveLastReview(outcome: ReviewOutcome): Promise<void> {
  const dir = await ensureCacheDir(outcome.result.repositoryPath);
  if (!dir) return;
  try {
    await writeFile(path.join(dir, LAST_REVIEW_FILE), renderJsonReport(outcome));
  } catch {
    // Read-only checkouts must still be reviewable.
  }
}
