import { LlmError } from "../core/errors";
import type { LlmClient, LlmRequest, LlmResponse } from "./llm-client";

export type FetchLike = (url: string, init: RequestInit) => Promise<Response>;

export interface OpenAiCompatibleOptions {
  readonly model: string;
  /** Base URL including version, e.g. https://api.openai.com/v1. */
  readonly baseUrl?: string;
  /** Read from the environment by the caller; never stored in configuration files. */
  readonly apiKey: string;
  readonly timeoutMs?: number;
  /** Injectable for tests. */
  readonly fetch?: FetchLike;
}

const DEFAULT_BASE_URL = "https://api.openai.com/v1";

/** Client for any server implementing the OpenAI chat-completions API. */
export class OpenAiCompatibleClient implements LlmClient {
  private readonly endpoint: string;
  private readonly fetchImpl: FetchLike;

  constructor(private readonly options: OpenAiCompatibleOptions) {
    const base = (options.baseUrl ?? DEFAULT_BASE_URL).replace(/\/+$/, "");
    const url = new URL(base);
    const local = ["localhost", "127.0.0.1", "[::1]"].includes(url.hostname);
    if (url.protocol !== "https:" && !local) {
      throw new LlmError(
        "llm-failure",
        `Refusing to send code to a non-HTTPS endpoint: ${url.origin}`,
        {
          suggestion: "Use an https:// baseUrl (plain http is only allowed for localhost).",
        },
      );
    }
    this.endpoint = `${base}/chat/completions`;
    this.fetchImpl = options.fetch ?? ((input, init) => fetch(input, init));
  }

  async complete(request: LlmRequest): Promise<LlmResponse> {
    let response: Response;
    try {
      response = await this.fetchImpl(this.endpoint, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          authorization: `Bearer ${this.options.apiKey}`,
        },
        body: JSON.stringify({
          model: this.options.model,
          temperature: request.temperature ?? 0,
          max_tokens: request.maxTokens ?? 2000,
          response_format: { type: "json_object" },
          messages: [
            { role: "system", content: request.system },
            { role: "user", content: request.user },
          ],
        }),
        signal: AbortSignal.timeout(this.options.timeoutMs ?? 60_000),
      });
    } catch (cause) {
      throw new LlmError("llm-failure", "LLM request failed (network error or timeout)", { cause });
    }

    if (!response.ok) {
      // The body is deliberately not echoed: it may contain request content.
      throw new LlmError("llm-failure", `LLM provider returned HTTP ${response.status}`, {
        suggestion:
          response.status === 401 || response.status === 403
            ? "Check the API key in the configured environment variable."
            : "Retry later or check the provider status and model name.",
      });
    }

    const body = (await response.json().catch(() => undefined)) as
      { choices?: Array<{ message?: { content?: unknown } }>; model?: unknown } | undefined;
    const content = body?.choices?.[0]?.message?.content;
    if (typeof content !== "string") {
      throw new LlmError("llm-invalid-response", "LLM provider response has no message content");
    }
    return { content, ...(typeof body?.model === "string" ? { model: body.model } : {}) };
  }
}
