import picomatch from "picomatch";

const MATCH_OPTIONS = { dot: true, nocase: false } as const;

/**
 * Returns a human-readable problem with a glob pattern, or undefined when it is valid.
 * Patterns are repository-relative POSIX globs.
 */
export function validateGlob(pattern: string): string | undefined {
  if (pattern.trim() === "") return "pattern is empty";
  if (pattern.startsWith("/") || /^[A-Za-z]:[\\/]/.test(pattern)) {
    return "pattern must be relative to the repository root, not absolute";
  }
  if (pattern.includes("\\")) return "use forward slashes (/) instead of backslashes";
  if (pattern.split("/").includes("..")) return 'pattern must not contain ".." segments';
  const unbalanced = findUnbalancedBracket(pattern);
  if (unbalanced) return `unbalanced "${unbalanced}"`;
  try {
    picomatch.makeRe(pattern, MATCH_OPTIONS);
  } catch (error) {
    return error instanceof Error ? error.message : "pattern cannot be compiled";
  }
  return undefined;
}

function findUnbalancedBracket(pattern: string): string | undefined {
  const pairs: Record<string, string> = { "[": "]", "{": "}", "(": ")" };
  const closers = new Set(Object.values(pairs));
  const stack: string[] = [];
  for (const char of pattern) {
    if (char in pairs) stack.push(pairs[char] as string);
    else if (closers.has(char)) {
      if (stack.pop() !== char) return char;
    }
  }
  const leftover = stack.pop();
  return leftover === undefined
    ? undefined
    : (Object.keys(pairs).find((open) => pairs[open] === leftover) as string);
}

/** Compiles patterns into a single predicate. An empty list matches nothing. */
export function createMatcher(patterns: readonly string[]): (filePath: string) => boolean {
  if (patterns.length === 0) return () => false;
  return picomatch([...patterns], MATCH_OPTIONS);
}

/** True when `filePath` matches at least one pattern. */
export function matchesAny(filePath: string, patterns: readonly string[]): boolean {
  return createMatcher(patterns)(filePath);
}

export interface PathFilter {
  readonly include: readonly string[];
  readonly exclude: readonly string[];
}

/** Applies include/exclude filters. An empty `include` list includes every file. */
export function matchesPathFilter(filePath: string, filter: PathFilter): boolean {
  const included = filter.include.length === 0 || matchesAny(filePath, filter.include);
  return included && !matchesAny(filePath, filter.exclude);
}
