import pc from "picocolors";
import { EXIT_CODES } from "../../core/constants";
import { findProjectRoot, type CliIo } from "../io";
import { formatError, loadProjectSetup } from "../context";

export interface ValidateOptions {
  readonly cwd: string;
  readonly configPath?: string;
  readonly io: CliIo;
}

/** Validates configuration and every policy file. Returns the process exit code. */
export async function runValidate(options: ValidateOptions): Promise<number> {
  const root = await findProjectRoot(options.cwd);
  const setup = await loadProjectSetup(root, options.configPath);
  const { io } = options;

  if (setup.config) {
    io.out(`Configuration: ${setup.config.sourcePath ?? "(none found, using defaults)"}`);
  }
  const files = setup.policies?.files ?? [];
  io.out(`Policy files: ${files.length}`);
  for (const file of files) io.out(`  - ${file}`);
  io.out(`Policies valid: ${setup.policies?.policies.length ?? 0}`);

  if (setup.errors.length > 0) {
    io.err(pc.red(`\n${setup.errors.length} problem(s) found:`));
    for (const error of setup.errors) io.err(formatError(error));
    return EXIT_CODES.failure;
  }
  io.out(pc.green("\nAll policies and configuration are valid."));
  return EXIT_CODES.ok;
}
