import { GitClient } from "../git/git-client";

/** Output sink so commands can be tested without touching process streams. */
export interface CliIo {
  out(text: string): void;
  err(text: string): void;
}

export const processIo: CliIo = {
  out: (text) => {
    process.stdout.write(`${text}\n`);
  },
  err: (text) => {
    process.stderr.write(`${text}\n`);
  },
};

/** Returns the Git repository root containing `cwd`, or `cwd` itself when not in a repository. */
export async function findProjectRoot(cwd: string): Promise<string> {
  const opened = await GitClient.open(cwd);
  return opened.ok ? opened.value.repositoryPath : cwd;
}
