import {
  Node,
  Project,
  ScriptTarget,
  SyntaxKind,
  type ArrowFunction,
  type ClassDeclaration,
  type ExportDeclaration,
  type FunctionDeclaration,
  type FunctionExpression,
  type InterfaceDeclaration,
  type SourceFile,
  type TypeAliasDeclaration,
  type EnumDeclaration,
  type VariableDeclaration,
  type ParameterDeclaration,
} from "ts-morph";
import { sha256 } from "../utils/hash";
import { detectLanguage } from "../utils/path";
import { IndexCache } from "./index-cache";
import { extractRoutes } from "./route-indexer";
import { extractTests } from "./test-indexer";
import type {
  ClassMemberInfo,
  ExportDetail,
  ExportInfo,
  FileIndex,
  ImportBinding,
  ImportInfo,
  MigrationFacts,
  ParameterInfo,
  PropertyInfo,
  SymbolInfo,
} from "./types";

const GLOBAL_MARKERS = ["APP_GUARD", "useGlobalGuards"] as const;

type ParameterLike = ParameterDeclaration;

/**
 * Builds a {@link FileIndex} from source text using ts-morph. Parsing is syntactic only
 * (no type checker), tolerant of broken code, and memoized by content hash.
 */
export class TypeScriptIndexer {
  private readonly project = new Project({
    useInMemoryFileSystem: true,
    skipAddingFilesFromTsConfig: true,
    skipFileDependencyResolution: true,
    compilerOptions: { allowJs: true, noResolve: true, target: ScriptTarget.ES2022 },
  });

  constructor(private readonly cache: IndexCache = new IndexCache()) {}

  /** Keys of every index produced or reused so far (used to prune the on-disk cache). */
  readonly touchedKeys = new Set<string>();

  /** Number of files served from the cache. */
  cacheHits = 0;

  /** Indexes one file. Never throws; a failure yields a partial index with `extractionOk: false`. */
  indexContent(filePath: string, content: string): FileIndex {
    const hash = sha256(content);
    const key = IndexCache.key(filePath, hash);
    this.touchedKeys.add(key);
    const cached = this.cache.get(key);
    if (cached) {
      this.cacheHits += 1;
      return cached;
    }

    const language = detectLanguage(filePath) === "javascript" ? "javascript" : "typescript";
    let index: FileIndex;
    try {
      index = this.extract(filePath, content, hash, language);
    } catch {
      index = emptyIndex(filePath, hash, language, false);
    }
    this.cache.set(key, index);
    return index;
  }

  private extract(
    filePath: string,
    content: string,
    hash: string,
    language: "typescript" | "javascript",
  ): FileIndex {
    const sourceFile = this.project.createSourceFile(`/${filePath}`, content, { overwrite: true });
    try {
      const imports = extractImports(sourceFile);
      const { routes, middlewareUsages } = safely(
        () => extractRoutes(sourceFile, filePath, imports),
        {
          routes: [],
          middlewareUsages: [],
        },
      );
      return {
        path: filePath,
        hash,
        language,
        extractionOk: true,
        syntaxErrors: countSyntaxErrors(sourceFile),
        imports,
        exports: safely(() => extractExports(sourceFile), []),
        symbols: safely(() => extractSymbols(sourceFile), []),
        routes,
        middlewareUsages,
        tests: safely(() => extractTests(sourceFile), []),
        markers: GLOBAL_MARKERS.filter((marker) => content.includes(marker)),
        migrationFacts: safely(() => extractMigrationFacts(sourceFile), {
          hasDown: false,
          hasChange: false,
        }),
      };
    } finally {
      sourceFile.forget();
    }
  }
}

function safely<T>(fn: () => T, fallback: T): T {
  try {
    return fn();
  } catch {
    return fallback;
  }
}

function emptyIndex(
  filePath: string,
  hash: string,
  language: "typescript" | "javascript",
  extractionOk: boolean,
): FileIndex {
  return {
    path: filePath,
    hash,
    language,
    extractionOk,
    syntaxErrors: 0,
    imports: [],
    exports: [],
    symbols: [],
    routes: [],
    middlewareUsages: [],
    tests: [],
    markers: [],
    migrationFacts: { hasDown: false, hasChange: false },
  };
}

/** `parseDiagnostics` is an internal TypeScript field; fall back to 0 if it disappears. */
function countSyntaxErrors(sourceFile: SourceFile): number {
  const node = sourceFile.compilerNode as unknown as { parseDiagnostics?: readonly unknown[] };
  return node.parseDiagnostics?.length ?? 0;
}

// ---------------------------------------------------------------- imports

function extractImports(sourceFile: SourceFile): ImportInfo[] {
  const imports: ImportInfo[] = [];

  for (const declaration of sourceFile.getImportDeclarations()) {
    const bindings: ImportBinding[] = [];
    const defaultImport = declaration.getDefaultImport();
    if (defaultImport) bindings.push({ local: defaultImport.getText(), imported: "default" });
    const namespaceImport = declaration.getNamespaceImport();
    if (namespaceImport) bindings.push({ local: namespaceImport.getText(), imported: "*" });
    for (const named of declaration.getNamedImports()) {
      bindings.push({
        local: named.getAliasNode()?.getText() ?? named.getName(),
        imported: named.getName(),
      });
    }
    imports.push({
      moduleSpecifier: declaration.getModuleSpecifierValue(),
      kind: "import",
      bindings,
      isTypeOnly: declaration.isTypeOnly(),
      line: declaration.getStartLineNumber(),
    });
  }

  for (const declaration of sourceFile.getExportDeclarations()) {
    const specifier = declaration.getModuleSpecifierValue();
    if (specifier === undefined) continue;
    imports.push({
      moduleSpecifier: specifier,
      kind: "export-from",
      bindings: declaration.getNamedExports().map((e) => ({
        local: e.getAliasNode()?.getText() ?? e.getName(),
        imported: e.getName(),
      })),
      isTypeOnly: declaration.isTypeOnly(),
      line: declaration.getStartLineNumber(),
    });
  }

  for (const call of sourceFile.getDescendantsOfKind(SyntaxKind.CallExpression)) {
    const callee = call.getExpression();
    const first = call.getArguments()[0];
    if (!first || !(Node.isStringLiteral(first) || Node.isNoSubstitutionTemplateLiteral(first)))
      continue;
    const isRequire = Node.isIdentifier(callee) && callee.getText() === "require";
    const isDynamic = callee.getKind() === SyntaxKind.ImportKeyword;
    if (!isRequire && !isDynamic) continue;
    imports.push({
      moduleSpecifier: first.getLiteralText(),
      kind: isRequire ? "require" : "dynamic-import",
      bindings: isRequire ? requireBindings(call.getParent()) : [],
      isTypeOnly: false,
      line: call.getStartLineNumber(),
    });
  }
  return imports;
}

function requireBindings(parent: Node | undefined): ImportBinding[] {
  if (!parent || !Node.isVariableDeclaration(parent)) return [];
  const nameNode = parent.getNameNode();
  if (Node.isIdentifier(nameNode)) return [{ local: nameNode.getText(), imported: "*" }];
  if (Node.isObjectBindingPattern(nameNode)) {
    return nameNode.getElements().map((element) => ({
      local: element.getName(),
      imported: element.getPropertyNameNode()?.getText() ?? element.getName(),
    }));
  }
  return [];
}

// ---------------------------------------------------------------- exports

function parameterInfo(parameter: ParameterLike): ParameterInfo {
  const type = parameter.getTypeNode()?.getText();
  return {
    name: parameter.getName(),
    ...(type === undefined ? {} : { type }),
    optional: parameter.hasQuestionToken() || parameter.hasInitializer(),
    rest: parameter.isRestParameter(),
  };
}

function functionDetail(
  fn: FunctionDeclaration | ArrowFunction | FunctionExpression,
): ExportDetail {
  const returnType = fn.getReturnTypeNode()?.getText();
  return {
    kind: "function",
    parameters: fn.getParameters().map(parameterInfo),
    ...(returnType === undefined ? {} : { returnType }),
  };
}

function classDetail(declaration: ClassDeclaration): ExportDetail {
  const members: ClassMemberInfo[] = [];
  for (const member of declaration.getMembers()) {
    if (Node.isScoped(member) && member.getScope() !== "public") continue;
    if (Node.isConstructorDeclaration(member)) {
      members.push({
        name: "constructor",
        kind: "constructor",
        isStatic: false,
        parameters: member.getParameters().map(parameterInfo),
      });
    } else if (Node.isMethodDeclaration(member)) {
      if (member.getName().startsWith("#")) continue;
      members.push({
        name: member.getName(),
        kind: "method",
        isStatic: member.isStatic(),
        parameters: member.getParameters().map(parameterInfo),
      });
    } else if (Node.isPropertyDeclaration(member)) {
      if (member.getName().startsWith("#")) continue;
      members.push({ name: member.getName(), kind: "property", isStatic: member.isStatic() });
    } else if (Node.isGetAccessorDeclaration(member) || Node.isSetAccessorDeclaration(member)) {
      members.push({ name: member.getName(), kind: "accessor", isStatic: member.isStatic() });
    }
  }
  return { kind: "class", members };
}

function interfaceDetail(declaration: InterfaceDeclaration): ExportDetail {
  const properties: PropertyInfo[] = [];
  for (const property of declaration.getProperties()) {
    const type = property.getTypeNode()?.getText();
    properties.push({
      name: property.getName(),
      optional: property.hasQuestionToken(),
      readonly: property.isReadonly(),
      ...(type === undefined ? {} : { type }),
    });
  }
  for (const method of declaration.getMethods()) {
    properties.push({
      name: method.getName(),
      optional: method.hasQuestionToken(),
      readonly: false,
      type: `(${method
        .getParameters()
        .map((p) => p.getText())
        .join(", ")}) => ${method.getReturnTypeNode()?.getText() ?? "unknown"}`,
    });
  }
  return {
    kind: "interface",
    properties,
    extends: declaration.getExtends().map((e) => e.getText()),
  };
}

function typeDetail(declaration: TypeAliasDeclaration): ExportDetail {
  return { kind: "type", text: declaration.getTypeNode()?.getText() ?? "unknown" };
}

function enumDetail(declaration: EnumDeclaration): ExportDetail {
  return { kind: "enum", members: declaration.getMembers().map((m) => m.getName()) };
}

function variableDetail(declaration: VariableDeclaration): ExportDetail {
  const initializer = declaration.getInitializer();
  if (
    initializer &&
    (Node.isArrowFunction(initializer) || Node.isFunctionExpression(initializer))
  ) {
    return functionDetail(initializer);
  }
  const type = declaration.getTypeNode()?.getText();
  return { kind: "variable", ...(type === undefined ? {} : { type }) };
}

function describeLocal(sourceFile: SourceFile, name: string): ExportDetail {
  const fn = sourceFile.getFunction(name);
  if (fn) return functionDetail(fn);
  const cls = sourceFile.getClass(name);
  if (cls) return classDetail(cls);
  const iface = sourceFile.getInterface(name);
  if (iface) return interfaceDetail(iface);
  const alias = sourceFile.getTypeAlias(name);
  if (alias) return typeDetail(alias);
  const enumeration = sourceFile.getEnum(name);
  if (enumeration) return enumDetail(enumeration);
  const variable = sourceFile.getVariableDeclaration(name);
  if (variable) return variableDetail(variable);
  return { kind: "unknown" };
}

function extractExports(sourceFile: SourceFile): ExportInfo[] {
  const result: ExportInfo[] = [];
  const add = (name: string, node: Node, detail: ExportDetail): void => {
    result.push({ name, line: node.getStartLineNumber(), detail });
  };

  for (const statement of sourceFile.getStatements()) {
    if (Node.isFunctionDeclaration(statement)) {
      if (!statement.isExported() || statement.isOverload()) continue;
      const name = statement.isDefaultExport() ? "default" : statement.getName();
      if (name) add(name, statement, functionDetail(statement));
    } else if (Node.isClassDeclaration(statement)) {
      if (!statement.isExported()) continue;
      const name = statement.isDefaultExport() ? "default" : statement.getName();
      if (name) add(name, statement, classDetail(statement));
    } else if (Node.isInterfaceDeclaration(statement)) {
      if (statement.isExported()) add(statement.getName(), statement, interfaceDetail(statement));
    } else if (Node.isTypeAliasDeclaration(statement)) {
      if (statement.isExported()) add(statement.getName(), statement, typeDetail(statement));
    } else if (Node.isEnumDeclaration(statement)) {
      if (statement.isExported()) add(statement.getName(), statement, enumDetail(statement));
    } else if (Node.isVariableStatement(statement)) {
      if (!statement.isExported()) continue;
      for (const declaration of statement.getDeclarations()) {
        add(declaration.getName(), declaration, variableDetail(declaration));
      }
    } else if (Node.isExportDeclaration(statement)) {
      readExportDeclaration(sourceFile, statement, add);
    } else if (Node.isExportAssignment(statement)) {
      const expression = statement.getExpression();
      const name = statement.isExportEquals() ? "export=" : "default";
      add(
        name,
        statement,
        Node.isIdentifier(expression)
          ? describeLocal(sourceFile, expression.getText())
          : { kind: "unknown" },
      );
    }
  }
  return result;
}

function readExportDeclaration(
  sourceFile: SourceFile,
  declaration: ExportDeclaration,
  add: (name: string, node: Node, detail: ExportDetail) => void,
): void {
  const from = declaration.getModuleSpecifierValue();
  const named = declaration.getNamedExports();

  if (from !== undefined && named.length === 0) {
    const namespaceName = declaration.getNamespaceExport()?.getName();
    if (namespaceName) add(namespaceName, declaration, { kind: "reexport", from, imported: "*" });
    else add("*", declaration, { kind: "star-reexport", from });
    return;
  }
  for (const specifier of named) {
    const exportedName = specifier.getAliasNode()?.getText() ?? specifier.getName();
    if (from !== undefined) {
      add(exportedName, specifier, { kind: "reexport", from, imported: specifier.getName() });
    } else {
      add(exportedName, specifier, describeLocal(sourceFile, specifier.getName()));
    }
  }
}

// ---------------------------------------------------------------- symbols

function extractSymbols(sourceFile: SourceFile): SymbolInfo[] {
  const symbols: SymbolInfo[] = [];
  const push = (name: string, kind: SymbolInfo["kind"], node: Node, exported: boolean): void => {
    symbols.push({
      name,
      kind,
      exported,
      startLine: node.getStartLineNumber(),
      endLine: node.getEndLineNumber(),
    });
  };

  for (const fn of sourceFile.getFunctions()) {
    const name = fn.getName();
    if (name && !fn.isOverload()) push(name, "function", fn, fn.isExported());
  }
  for (const cls of sourceFile.getClasses()) {
    const className = cls.getName();
    if (!className) continue;
    push(className, "class", cls, cls.isExported());
    for (const method of cls.getMethods()) {
      push(`${className}.${method.getName()}`, "method", method, cls.isExported());
    }
  }
  for (const iface of sourceFile.getInterfaces())
    push(iface.getName(), "interface", iface, iface.isExported());
  for (const alias of sourceFile.getTypeAliases())
    push(alias.getName(), "type", alias, alias.isExported());
  for (const enumeration of sourceFile.getEnums()) {
    push(enumeration.getName(), "enum", enumeration, enumeration.isExported());
  }
  for (const statement of sourceFile.getVariableStatements()) {
    for (const declaration of statement.getDeclarations()) {
      push(declaration.getName(), "variable", declaration, statement.isExported());
    }
  }
  return symbols;
}

// ------------------------------------------------------- migration facts

/** Finds `down`/`change` as functions, methods, object properties, variables, or `exports.down =`. */
function extractMigrationFacts(sourceFile: SourceFile): MigrationFacts {
  let hasDown = false;
  let hasChange = false;
  let downRange: readonly [number, number] | undefined;

  const consider = (name: string | undefined, body: Node): void => {
    if (name === "down") {
      hasDown = true;
      downRange ??= [body.getStartLineNumber(), body.getEndLineNumber()];
    } else if (name === "change") {
      hasChange = true;
    }
  };

  sourceFile.forEachDescendant((node) => {
    if (Node.isFunctionDeclaration(node) || Node.isMethodDeclaration(node)) {
      consider(node.getName(), node);
    } else if (Node.isPropertyAssignment(node)) {
      consider(node.getName(), node);
    } else if (Node.isShorthandPropertyAssignment(node)) {
      consider(node.getName(), node);
    } else if (Node.isVariableDeclaration(node)) {
      consider(node.getName(), node);
    } else if (
      Node.isBinaryExpression(node) &&
      node.getOperatorToken().getKind() === SyntaxKind.EqualsToken
    ) {
      const left = node.getLeft();
      if (Node.isPropertyAccessExpression(left)) consider(left.getName(), node);
    }
  });

  return { hasDown, hasChange, ...(downRange ? { downRange } : {}) };
}
