import Table from "cli-table3";
import pc from "picocolors";
import { EXIT_CODES } from "../../core/constants";
import type { Severity } from "../../core/types";
import { findProjectRoot, type CliIo } from "../io";
import { formatError, loadProjectSetup } from "../context";

export interface PoliciesOptions {
  readonly cwd: string;
  readonly configPath?: string;
  readonly io: CliIo;
}

const SEVERITY_COLOR: Record<Severity, (text: string) => string> = {
  info: pc.cyan,
  warning: pc.yellow,
  error: pc.red,
  critical: (text) => pc.bold(pc.red(text)),
};

/** Lists loaded policies. Returns the process exit code. */
export async function runPolicies(options: PoliciesOptions): Promise<number> {
  const root = await findProjectRoot(options.cwd);
  const setup = await loadProjectSetup(root, options.configPath);
  const { io } = options;

  const policies = setup.policies?.policies ?? [];
  if (policies.length > 0) {
    const configPaths = setup.config?.config.paths;
    const defaultTargets: Record<string, readonly string[] | undefined> = {
      "new-route-requires-authorization": configPaths?.api,
      "migration-requires-rollback": configPaths?.migrations,
      "no-direct-db-access-in-ui": configPaths?.ui,
      "protected-path-requires-review-annotation": configPaths?.protected,
      "deleted-test-requires-justification": configPaths?.tests,
    };
    const table = new Table({
      head: ["ID", "Severity", "Category", "Enabled", "Rule", "Target paths"],
    });
    for (const policy of policies) {
      const include =
        policy.paths.include.length > 0
          ? policy.paths.include
          : (defaultTargets[policy.rule] ?? ["(all files)"]);
      table.push([
        policy.id,
        SEVERITY_COLOR[policy.severity](policy.severity),
        policy.category,
        policy.enabled ? "yes" : "no",
        policy.rule,
        include.join("\n"),
      ]);
    }
    io.out(table.toString());
  }

  if (setup.errors.length > 0) {
    io.err(pc.red(`\n${setup.errors.length} problem(s) found:`));
    for (const error of setup.errors) io.err(formatError(error));
    return EXIT_CODES.failure;
  }
  return EXIT_CODES.ok;
}
