import { loadConfig, type LoadedConfig } from "../core/config";
import type { PolicyGuardError } from "../core/errors";
import { loadPolicies, type PolicyLoadResult } from "../policies/policy-loader";
import { BUILT_IN_RULE_IDS } from "../rules/rule-ids";

export interface ProjectSetup {
  readonly config?: LoadedConfig;
  readonly policies?: PolicyLoadResult;
  readonly errors: readonly PolicyGuardError[];
}

/** Loads configuration and policies, collecting every error instead of stopping at the first. */
export async function loadProjectSetup(
  repositoryPath: string,
  configPath?: string,
  knownRuleIds: ReadonlySet<string> = new Set(BUILT_IN_RULE_IDS),
): Promise<ProjectSetup> {
  const errors: PolicyGuardError[] = [];
  const configResult = await loadConfig(repositoryPath, configPath);
  if (!configResult.ok) errors.push(configResult.error);
  const policies = await loadPolicies(repositoryPath, knownRuleIds);
  errors.push(...policies.errors);
  return {
    ...(configResult.ok ? { config: configResult.value } : {}),
    policies,
    errors,
  };
}

/** Formats an error with its file and suggested fix for terminal output. */
export function formatError(error: PolicyGuardError): string {
  const lines = [`  ${error.file ? `${error.file}: ` : ""}${error.message}`];
  if (error.suggestion) lines.push(`    fix: ${error.suggestion}`);
  return lines.join("\n");
}
