import { Node, type CallExpression, type SourceFile } from "ts-morph";
import type { TestCase, TestModifier } from "./types";

const SUITE_ROOTS = new Set(["describe", "context", "suite", "xdescribe", "fdescribe"]);
const TEST_ROOTS = new Set(["it", "test", "specify", "xit", "xtest", "fit", "ftest"]);
const MAX_TEST_SOURCE = 2000;

interface TestCall {
  readonly kind: "test" | "suite";
  readonly modifier: TestModifier;
}

/** Extracts Vitest/Jest/Mocha suites and test cases with their modifiers (skip/todo/only). */
export function extractTests(sourceFile: SourceFile): TestCase[] {
  const found: TestCase[] = [];
  visit(sourceFile, [], found);
  return found;
}

function visit(node: Node, suiteStack: readonly string[], found: TestCase[]): void {
  let nextStack = suiteStack;
  if (Node.isCallExpression(node)) {
    const parsed = classifyCall(node);
    const name = parsed ? testName(node) : undefined;
    if (parsed && name !== undefined) {
      const fullName = [...suiteStack, name].join(" > ");
      found.push({
        kind: parsed.kind,
        name,
        fullName,
        modifier: parsed.modifier,
        framework: "vitest-jest-mocha",
        line: node.getStartLineNumber(),
        endLine: node.getEndLineNumber(),
        ...(parsed.kind === "test" ? { source: node.getText().slice(0, MAX_TEST_SOURCE) } : {}),
      });
      if (parsed.kind === "suite") nextStack = [...suiteStack, name];
    }
  }
  node.forEachChild((child) => visit(child, nextStack, found));
}

function classifyCall(call: CallExpression): TestCall | undefined {
  const callee = call.getExpression();
  let root: string;
  let modifierName: string | undefined;

  if (Node.isIdentifier(callee)) {
    root = callee.getText();
  } else if (Node.isPropertyAccessExpression(callee) && Node.isIdentifier(callee.getExpression())) {
    root = callee.getExpression().getText();
    modifierName = callee.getName();
  } else {
    return undefined;
  }

  const kind = SUITE_ROOTS.has(root) ? "suite" : TEST_ROOTS.has(root) ? "test" : undefined;
  if (!kind) return undefined;

  let modifier: TestModifier = "none";
  if (root.startsWith("x")) modifier = "skip";
  else if (root.startsWith("f") && root !== "fixme") modifier = "only";

  switch (modifierName) {
    case "skip":
      modifier = "skip";
      break;
    case "todo":
      modifier = "todo";
      break;
    case "only":
      modifier = "only";
      break;
    case "fixme":
      modifier = "fixme";
      break;
    case undefined:
    case "concurrent":
    case "sequential":
    case "each":
      break;
    default:
      return undefined;
  }
  return { kind, modifier };
}

function testName(call: CallExpression): string | undefined {
  const first = call.getArguments()[0];
  if (!first) return undefined;
  if (Node.isStringLiteral(first) || Node.isNoSubstitutionTemplateLiteral(first)) {
    return first.getLiteralText();
  }
  if (Node.isTemplateExpression(first)) return first.getText().slice(1, -1);
  return undefined;
}
