import type { PolicyGuardConfig } from "../core/config";
import type { Finding, Suppression } from "../core/types";
import { matchesAny } from "../utils/glob";
import type { LoadedPolicy } from "./policy-schema";

export type SuppressionOrigin = "config" | "policy" | "inline";

export interface SuppressionContext {
  readonly config: PolicyGuardConfig;
  readonly policies: readonly LoadedPolicy[];
  /** Returns the head-side lines of a file, used for inline `policyguard-ignore` comments. */
  readonly readLines?: (file: string) => readonly string[] | undefined;
  /** Injected for deterministic tests. */
  readonly now?: Date;
}

interface Candidate {
  readonly origin: SuppressionOrigin;
  readonly reason: string;
  readonly author?: string;
  readonly expiresAt?: string;
}

const INLINE_PATTERN = /policyguard-ignore\s+([a-z0-9-]+)(?:\s+reason="([^"]*)")?/i;

/**
 * Marks findings as suppressed when an explicit, reasoned, unexpired suppression applies.
 * Suppressed findings stay in the report for auditability but are never blocking.
 */
export function applySuppressions(
  findings: readonly Finding[],
  context: SuppressionContext,
): Finding[] {
  const now = context.now ?? new Date();
  return findings.map((finding) => {
    let expired: Suppression | undefined;
    for (const candidate of collectCandidates(finding, context)) {
      if (isExpired(candidate, now)) {
        expired ??= {
          status: "active",
          reason: `Suppression expired on ${candidate.expiresAt}: ${candidate.reason}`,
          ...(candidate.author === undefined ? {} : { author: candidate.author }),
          ...(candidate.expiresAt === undefined ? {} : { expiresAt: candidate.expiresAt }),
        };
        continue;
      }
      return {
        ...finding,
        suppression: {
          status: "suppressed",
          reason: `[${candidate.origin}] ${candidate.reason}`,
          ...(candidate.author === undefined ? {} : { author: candidate.author }),
          ...(candidate.expiresAt === undefined ? {} : { expiresAt: candidate.expiresAt }),
        },
      };
    }
    return expired ? { ...finding, suppression: expired } : finding;
  });
}

function collectCandidates(finding: Finding, context: SuppressionContext): Candidate[] {
  const candidates: Candidate[] = [];

  for (const entry of context.config.suppressions) {
    if (entry.ruleId !== undefined && entry.ruleId !== finding.ruleId) continue;
    if (!matchesAny(finding.file, entry.paths)) continue;
    candidates.push({ origin: "config", reason: entry.reason, ...optional(entry) });
  }

  const policy = context.policies.find((p) => p.id === finding.policyId);
  for (const entry of policy?.suppressions ?? []) {
    if (!matchesAny(finding.file, entry.paths)) continue;
    candidates.push({ origin: "policy", reason: entry.reason, ...optional(entry) });
  }

  const inline = findInlineSuppression(finding, context.readLines);
  if (inline) candidates.push(inline);
  return candidates;
}

function optional(entry: { author?: string | undefined; expiresAt?: string | undefined }): {
  author?: string;
  expiresAt?: string;
} {
  return {
    ...(entry.author === undefined ? {} : { author: entry.author }),
    ...(entry.expiresAt === undefined ? {} : { expiresAt: entry.expiresAt }),
  };
}

/** Looks for `policyguard-ignore <rule-id> reason="..."` on the finding line or the line above. */
function findInlineSuppression(
  finding: Finding,
  readLines: SuppressionContext["readLines"],
): Candidate | undefined {
  if (finding.startLine === undefined || !readLines) return undefined;
  const lines = readLines(finding.file);
  if (!lines) return undefined;
  for (const lineNumber of [finding.startLine, finding.startLine - 1]) {
    const text = lines[lineNumber - 1];
    if (text === undefined) continue;
    const match = INLINE_PATTERN.exec(text);
    if (!match || match[1]?.toLowerCase() !== finding.ruleId) continue;
    const reason = match[2]?.trim();
    if (!reason) continue; // A suppression without a reason is not valid.
    return { origin: "inline", reason };
  }
  return undefined;
}

function isExpired(candidate: Candidate, now: Date): boolean {
  if (candidate.expiresAt === undefined) return false;
  const expires = Date.parse(candidate.expiresAt);
  return !Number.isNaN(expires) && expires < now.getTime();
}

/** True when the finding is currently suppressed. */
export function isSuppressed(finding: Finding): boolean {
  return finding.suppression?.status === "suppressed";
}
