/** Machine-readable error categories. */
export type PolicyGuardErrorCode =
  | "not-a-repository"
  | "git-failure"
  | "ref-not-found"
  | "diff-parse"
  | "config-invalid"
  | "config-not-found"
  | "policy-invalid"
  | "policy-yaml"
  | "policy-unknown-rule"
  | "policy-duplicate-id"
  | "index-failure"
  | "rule-failure"
  | "llm-failure"
  | "llm-invalid-response"
  | "io-failure"
  | "usage";

/** Serializable shape of a {@link PolicyGuardError}. */
export interface PolicyGuardErrorJson {
  readonly code: PolicyGuardErrorCode;
  readonly message: string;
  readonly file?: string;
  readonly suggestion?: string;
}

export interface PolicyGuardErrorOptions {
  readonly file?: string;
  readonly suggestion?: string;
  readonly cause?: unknown;
}

/**
 * Base error for every failure PolicyGuard reports. Carries a stable code and
 * an optional suggested fix so the CLI can print actionable messages.
 */
export class PolicyGuardError extends Error {
  readonly code: PolicyGuardErrorCode;
  readonly file?: string;
  readonly suggestion?: string;

  constructor(code: PolicyGuardErrorCode, message: string, options: PolicyGuardErrorOptions = {}) {
    super(message, options.cause === undefined ? undefined : { cause: options.cause });
    this.name = new.target.name;
    this.code = code;
    if (options.file !== undefined) this.file = options.file;
    if (options.suggestion !== undefined) this.suggestion = options.suggestion;
  }

  toJSON(): PolicyGuardErrorJson {
    return {
      code: this.code,
      message: this.message,
      ...(this.file === undefined ? {} : { file: this.file }),
      ...(this.suggestion === undefined ? {} : { suggestion: this.suggestion }),
    };
  }
}

/** Failure while talking to Git or resolving repository state. */
export class GitError extends PolicyGuardError {}

/** Failure while parsing a unified diff. */
export class DiffParseError extends PolicyGuardError {
  constructor(message: string, options: PolicyGuardErrorOptions = {}) {
    super("diff-parse", message, options);
  }
}

/** Invalid or unreadable configuration. */
export class ConfigError extends PolicyGuardError {}

/** Invalid policy definition or policy file. */
export class PolicyError extends PolicyGuardError {}

/** Failure inside the repository indexer. */
export class IndexError extends PolicyGuardError {
  constructor(message: string, options: PolicyGuardErrorOptions = {}) {
    super("index-failure", message, options);
  }
}

/** Failure inside a rule implementation. */
export class RuleError extends PolicyGuardError {
  constructor(message: string, options: PolicyGuardErrorOptions = {}) {
    super("rule-failure", message, options);
  }
}

/** Failure in the optional LLM layer. */
export class LlmError extends PolicyGuardError {
  constructor(
    code: Extract<PolicyGuardErrorCode, "llm-failure" | "llm-invalid-response">,
    message: string,
    options: PolicyGuardErrorOptions = {},
  ) {
    super(code, message, options);
  }
}

/** Converts any thrown value into a {@link PolicyGuardError}. */
export function toPolicyGuardError(
  value: unknown,
  fallbackCode: PolicyGuardErrorCode = "io-failure",
): PolicyGuardError {
  if (value instanceof PolicyGuardError) return value;
  const message = value instanceof Error ? value.message : String(value);
  return new PolicyGuardError(fallbackCode, message, { cause: value });
}
