import type { ChangedFile, Evidence, Finding } from "../../core/types";
import type { TestCase } from "../../indexing/types";
import { policiesForRule } from "../../policies/policy-context";
import type { LoadedPolicy } from "../../policies/policy-schema";
import type { RuleContext } from "../rule-context";
import type { PolicyRuleImplementation, RuleResult } from "../rule-result";
import {
  baseLines,
  commitMessageAnnotations,
  createFinding,
  filesInScope,
  findReasonAnnotations,
  headLines,
  mapOldToNewLine,
  snippet,
} from "../rule-utils";

const RULE_ID = "deleted-test-requires-justification";
const JUSTIFICATION = "test-change-justified";
const MAX_LISTED_NAMES = 8;

/** Test body with the (renamable) title removed, for detecting renamed-but-unchanged tests. */
function bodyKey(test: TestCase): string | undefined {
  if (!test.source) return undefined;
  return test.source
    .replace(/^[^(]*\(\s*(['"`])(?:\\.|(?!\1)[\s\S])*\1/, "T(")
    .replace(/\s+/g, " ")
    .trim();
}

export const deletedTestRequiresJustification: PolicyRuleImplementation = {
  id: RULE_ID,
  title: "Deleted test requires justification",
  description: "Deleting, skipping, or disabling tests needs a justification.",
  category: "testing",
  defaultSeverity: "warning",
  supportedLanguages: ["typescript"],

  async run(context: RuleContext): Promise<RuleResult> {
    const findings: Finding[] = [];
    const commitJustified =
      commitMessageAnnotations(context.commitMessages, JUSTIFICATION).length > 0;

    for (const policy of policiesForRule(context.policies, RULE_ID)) {
      const files = filesInScope(context, policy, context.config.paths.tests, {
        statuses: ["deleted", "modified", "renamed", "added"],
      });
      for (const file of files) {
        if (file.status === "deleted") {
          const finding = await deletedFileFinding(context, policy, file, commitJustified);
          if (finding) findings.push(finding);
        } else {
          findings.push(...(await changedFileFindings(context, policy, file, commitJustified)));
        }
      }
    }
    return { findings, errors: [] };
  },
};

async function deletedFileFinding(
  context: RuleContext,
  policy: LoadedPolicy,
  file: ChangedFile,
  commitJustified: boolean,
): Promise<Finding | undefined> {
  if (commitJustified) return undefined;
  const content = await context.baseReader.readFile(file.path);
  const tests = content
    ? context.indexer.indexContent(file.path, content).tests.filter((t) => t.kind === "test")
    : [];
  const names = tests.slice(0, MAX_LISTED_NAMES).map((t) => `"${t.fullName}"`);
  const more =
    tests.length > MAX_LISTED_NAMES ? ` and ${tests.length - MAX_LISTED_NAMES} more` : "";

  const evidence: Evidence[] = [
    {
      file: file.path,
      startLine: 1,
      explanation:
        tests.length > 0
          ? `Test file deleted, removing ${tests.length} test case(s): ${names.join(", ")}${more}`
          : "Test file deleted",
      source: "diff",
    },
    {
      file: file.path,
      explanation: `No "policyguard: ${JUSTIFICATION} reason=..." found in commit messages or policy exceptions`,
      source: "policy",
    },
  ];
  return createFinding({
    ruleId: RULE_ID,
    policy,
    title: "Test file deleted without justification",
    message: `${file.path} was deleted${tests.length > 0 ? ` (${tests.length} test case(s))` : ""} without a documented reason.`,
    file: file.path,
    startLine: 1,
    evidence,
    confidence: "high",
    key: "deleted-file",
    remediation: remediation(policy),
  });
}

async function changedFileFindings(
  context: RuleContext,
  policy: LoadedPolicy,
  file: ChangedFile,
  commitJustified: boolean,
): Promise<Finding[]> {
  const headIndex = context.indexedRepository.getFileIndex(file.path);
  if (!headIndex) return [];

  const basePath = file.previousPath ?? file.path;
  const baseContent =
    file.status === "added" ? undefined : await context.baseReader.readFile(basePath);
  const baseTests = baseContent ? context.indexer.indexContent(basePath, baseContent).tests : [];
  const headTests = headIndex.tests;

  const lines = await headLines(context, file.path);
  const oldLines = await baseLines(context, basePath);
  const fileJustified =
    commitJustified ||
    (lines ? findReasonAnnotations(lines, JUSTIFICATION).some((a) => a.reason) : false);
  const findings: Finding[] = [];

  // Removed test cases.
  const headNames = new Set(headTests.map((t) => t.fullName));
  const headBodies = new Set(headTests.map(bodyKey).filter((k): k is string => k !== undefined));
  for (const test of baseTests) {
    if (test.kind !== "test" || headNames.has(test.fullName)) continue;
    const key = bodyKey(test);
    if (key !== undefined && headBodies.has(key)) continue; // renamed, body unchanged
    if (fileJustified) continue;
    const line = mapOldToNewLine(file, test.line);
    const code = snippet(oldLines, test.line);
    findings.push(
      createFinding({
        ruleId: RULE_ID,
        policy,
        title: "Test removed without justification",
        message: `Test "${test.fullName}" was removed from ${file.path} without a documented reason.`,
        file: file.path,
        startLine: line,
        evidence: [
          {
            file: file.path,
            startLine: line,
            ...(code ? { snippet: code } : {}),
            explanation: `Test "${test.fullName}" was removed`,
            source: "diff",
          },
          {
            file: file.path,
            explanation: `No "policyguard: ${JUSTIFICATION} reason=..." found in commit messages or the file`,
            source: "policy",
          },
        ],
        confidence: "medium",
        key: `removed:${test.fullName}`,
        remediation: remediation(policy),
      }),
    );
  }

  // Newly skipped, disabled, or todo tests.
  const baseByName = new Map(baseTests.map((t) => [t.fullName, t]));
  for (const test of headTests) {
    if (test.modifier !== "skip" && test.modifier !== "todo" && test.modifier !== "fixme") continue;
    const before = baseByName.get(test.fullName);
    const wasActive = before !== undefined && before.modifier === "none";
    const isNewlyDisabled = wasActive || (before === undefined && test.modifier !== "todo");
    if (!isNewlyDisabled) continue;
    if (commitJustified || hasNearbyJustification(lines, test.line)) continue;
    const code = snippet(lines, test.line);
    findings.push(
      createFinding({
        ruleId: RULE_ID,
        policy,
        title: `Test ${test.modifier === "skip" ? "skipped" : test.modifier === "todo" ? "marked todo" : "disabled"} without justification`,
        message: `${test.kind === "suite" ? "Suite" : "Test"} "${test.fullName}" is now ${test.modifier} in ${file.path} without a documented reason.`,
        file: file.path,
        startLine: test.line,
        endLine: test.endLine,
        evidence: [
          {
            file: file.path,
            startLine: test.line,
            ...(code ? { snippet: code } : {}),
            explanation: `${test.kind === "suite" ? "Suite" : "Test"} "${test.fullName}" is ${test.modifier}${wasActive ? " (it was active before)" : ""}`,
            source: "diff",
          },
          {
            file: file.path,
            explanation: `No "policyguard: ${JUSTIFICATION} reason=..." next to the test or in commit messages`,
            source: "policy",
          },
        ],
        confidence: "high",
        key: `disabled:${test.fullName}`,
        remediation: remediation(policy),
      }),
    );
  }
  return findings;
}

function hasNearbyJustification(lines: readonly string[] | undefined, testLine: number): boolean {
  if (!lines) return false;
  const from = Math.max(1, testLine - 3);
  return findReasonAnnotations(lines.slice(from - 1, testLine), JUSTIFICATION).some(
    (a) => a.reason,
  );
}

function remediation(policy: LoadedPolicy): string {
  return (
    policy.remediation?.trim() ??
    `Restore the test, or justify the change: policyguard: ${JUSTIFICATION} reason="..." (commit message or next to the test).`
  );
}
